local config = {
  ui_story_5045_50450101_1_dialog_content = "<color=#737378>Time: 5:00 PM</color>",
  ui_story_5045_50450101_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice</color>",
  ui_story_5045_50450101_3_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450101_4_dialog_content = "Ahem... Silence please, everyone.",
  ui_story_5045_50450101_5_dialog_content = "A despicable theft of the worst kind has occurred within the Hall of Justice today.",
  ui_story_5045_50450101_6_dialog_content = "I shall be presiding as judge over this vile case.",
  ui_story_5045_50450101_7_dialog_content = "I swear to honor my superiors by upholding the law, and passing fair and unbiased judgment to the best of my abilities!",
  ui_story_5045_50450101_8_dialog_content = "<size=45>White Night up high. Court is now in session!</size>",
  ui_story_5045_50450101_9_dialog_content = "To begin...",
  ui_story_5045_50450101_10_dialog_content = "<size=32>Who should be the first to speak? I was so nervous just now that my mind's gone completely blank...</size>",
  ui_story_5045_50450101_11_dialog_content = "(Wow, they already made Angel a fully-fledged judge!)",
  ui_story_5045_50450101_12_dialog_content = "(Uh... Why's she staring in my direction?)",
  ui_story_5045_50450101_13_dialog_content = "(Guess it doesn't matter. As her friend, I should do whatever I can to encourage her!)",
  ui_story_5045_50450101_14_option_content = "Wave at her!",
  ui_story_5045_50450101_15_option_content = "Smile at her!",
  ui_story_5045_50450101_16_dialog_content = "PlayerName...?",
  ui_story_5045_50450101_17_dialog_content = "Oh, right!",
  ui_story_5045_50450101_18_dialog_content = "Let us begin by inviting PlayerName, the <color=#1875ad>suspect</color> in this case, to stand before the court!",
  ui_story_5045_50450101_19_dialog_content = "Huh? Wh-When did I become a suspect?!",
  ui_story_5045_50450101_20_dialog_content = "I only came to the Lumo Hall of Justice because I was invited here...",
  ui_story_5045_50450101_21_dialog_content = "<color=#737378>Bang, bang, bang!</color>",
  ui_story_5045_50450101_22_dialog_content = "Silence!",
  ui_story_5045_50450101_23_dialog_content = "Please observe the court's rules, and answer my questions with honesty and to the best of your knowledge.",
  ui_story_5045_50450101_24_dialog_content = "(Angel looks so serious, sitting in the center of the judge's bench. Her white wing blends in perfectly against that holy-looking background.)",
  ui_story_5045_50450101_25_dialog_content = "(It's bad enough that I'm being pushed into the witness stand, but that look she's giving me... She really does think I'm a suspect!)",
  ui_story_5045_50450101_26_dialog_content = "(I have to say something to her! I want to yell it from the bottom of my heart—)",
  ui_story_5045_50450101_27_option_content = "It was all a set-up!",
  ui_story_5045_50450101_28_dialog_content = "Oh?",
  ui_story_5045_50450101_29_dialog_content = "Trying to make excuses for your crime before questioning even begins, I see?",
  ui_story_5045_50450101_30_option_content = "Objection!",
  ui_story_5045_50450101_31_dialog_content = "Overruled!",
  ui_story_5045_50450101_32_dialog_content = "Your objection is denied on the grounds that I haven't even begun questioning you yet!",
  ui_story_5045_50450101_33_dialog_content = "What in the world is going on here?",
  ui_story_5045_50450101_34_dialog_content = "Oh my... Another lowly commoner wanting to be a judge?",
  ui_story_5045_50450101_35_dialog_content = "Quite the affront to the judicial process, don't you think?",
  ui_story_5045_50450101_36_dialog_content = "Keep it down, Matthieu.",
  ui_story_5045_50450101_37_dialog_content = "We're not supposed to make any sort of comments right now. Don't disrespect the Hall of Justice like that.",
  ui_story_5045_50450101_38_dialog_content = "Zzz...",
  ui_story_5045_50450101_39_dialog_content = "Don't you think she's being a lot more disrespectful towards the Hall right now?!",
  ui_story_5045_50450101_40_dialog_content = "Tina, wake up!",
  ui_story_5045_50450101_41_dialog_content = "Yaaaawn... Huh? Why's PlayerName taking the stand? He's a suspect, isn't he?",
  ui_story_5045_50450101_42_dialog_content = "Ah! Oh crap, oh crap!",
  ui_story_5045_50450101_43_dialog_content = "Don't tell me I missed the opening statements for the trial?!",
  ui_story_5045_50450101_44_dialog_content = "Shhhh!!!",
  ui_story_5045_50450101_45_dialog_content = "Er, ahem... We were only confirming that PlayerName is in attendance today.",
  ui_story_5045_50450101_46_dialog_content = "The suspect may return to their seat now.",
  ui_story_5045_50450101_47_dialog_content = "(Does this mean I have to keep going along with this?)",
  ui_story_5045_50450101_48_dialog_content = "And now, we ask that the plaintiff, Judge Irridon, makes her opening statement.",
  ui_story_5045_50450101_49_dialog_content = "Very well.",
  ui_story_5045_50450101_50_dialog_content = "At two o'clock this afternoon, I received a notice from the City Lord to attend a last-minute meeting.",
  ui_story_5045_50450101_51_dialog_content = "After receiving this notice, I locked my office door and left.",
  ui_story_5045_50450101_52_dialog_content = "But when I returned to my office at four o'clock, I noticed that a substantial amount of Nightium had gone missing.",
  ui_story_5045_50450101_53_dialog_content = "Did you notice anything unusual at the crime scene?",
  ui_story_5045_50450101_54_dialog_content = "The door and windows to my office showed no signs of forced entry, and the door was still locked when I returned.",
  ui_story_5045_50450101_55_dialog_content = "Aside from my own fingerprints, the doorknob had no other traces left on it.",
  ui_story_5045_50450101_55X1_dialog_content = "(I don't really understand what's going on here, but Irridon seems to be talking about something important.)",
  ui_story_5045_50450101_55X2_dialog_content = "(I'd better write down these details, just in case!)",
  ui_story_5045_50450101_56_dialog_content = "This appears to be quite a mysterious theft!",
  ui_story_5045_50450101_57_dialog_content = "Can you please tell the court why you suspect PlayerName of stealing the Nightium?",
  ui_story_5045_50450101_58_dialog_content = "Because I found a letter in my office, an invitation I had personally sent to PlayerName.",
  ui_story_5045_50450101_59_dialog_content = "That invitation should have been in PlayerName's possession...",
  ui_story_5045_50450101_60_dialog_content = "So what was it doing inside my locked office?",
  ui_story_5045_50450101_61_dialog_content = "What?!",
  ui_story_5045_50450101_62_dialog_content = "Not only that... Someone attested to seeing PlayerName in the vicinity of my office at the time.",
  ui_story_5045_50450101_63_dialog_content = "That was because—",
  ui_story_5045_50450101_64_dialog_content = "<color=#737378>Bang, bang, bang!</color>",
  ui_story_5045_50450101_65_dialog_content = "<size=45>Silence! Order in the court!</size>",
  ui_story_5045_50450101_66_dialog_content = "Hmm, now what comes next again? Ah, yes! We will now hear testimony from the witness, Mr. Pittman!",
  ui_story_5045_50450101_67_dialog_content = "At two o'clock this afternoon, I went to see Judge Irridon to ask a number of work-related questions...",
  ui_story_5045_50450101_68_dialog_content = "But she promptly told me that she had to leave for an urgent meeting, and asked me to return at a later time.",
  ui_story_5045_50450101_69_dialog_content = "At approximately three o'clock, I walked back to her office to see if she had returned.",
  ui_story_5045_50450101_70_dialog_content = "But as I approached her door, I noticed the fleeting image of a figure leaving the very same spot.",
  ui_story_5045_50450101_71_dialog_content = "So I thought to myself, that must have been PlayerName.",
  ui_story_5045_50450101_72_dialog_content = "Excellent! And now it's time to pass judgment on the witness... Are you ready, PlayerName?",
  ui_story_5045_50450101_73_dialog_content = "W-Wait, Your Honor! Give me a chance to explain!",
  ui_story_5045_50450101_74_dialog_content = "Oh my, not again. I forgot I was supposed to hear his rebuttal first...",
  ui_story_5045_50450101_75_dialog_content = "A-Ahem, very well then! You may offer your rebuttal now.",
  ui_story_5045_50450101_76_dialog_content = "But first, please introduce yourself to the court.",
  ui_story_5045_50450101_77_dialog_content = "My name is PlayerName. I'm a Caelestite.",
  ui_story_5045_50450101_78_dialog_content = "Please introduce to us your <color=#1875ad>occupation</color> as well.",
  ui_story_5045_50450101_79_dialog_content = "I, uh...",
  ui_story_5045_50450101_80_option_content = "I'm Astra's most lovable mascot.",
  ui_story_5045_50450101_81_option_content = "I'm the Dragonwave Angler.",
  ui_story_5045_50450101_82_option_content = "I'm a professional tower-climber.",
  ui_story_5045_50450101_83_dialog_content = "I'm the designated pilot of Soroz.",
  ui_story_5045_50450101_84_dialog_content = "Could you please elaborate?",
  ui_story_5045_50450101_85_dialog_content = "To put it another way, my job is—",
  ui_story_5045_50450101_86_option_content = "To overthrow Lumopolis and its tyranny!",
  ui_story_5045_50450101_87_dialog_content = "Wh-What?! Lumopolis is prospering under the fair and just rule of the City Lord! How dare you reveal your terror-driven ambitions to us!!!",
  ui_story_5045_50450101_88_dialog_content = "I'll have you know that those who threaten the peace of Lumopolis or its people... will spend the rest of their lives in prison!",
  ui_story_5045_50450101_89_dialog_content = "(I was just joking, but she looks dead serious about sentencing me...)",
  ui_story_5045_50450101_90_dialog_content = "O-Oh, come on! You know I'm always saying crazy things like that!",
  ui_story_5045_50450101_91_option_content = "To spread a message of peace and love!",
  ui_story_5045_50450101_92_option_content = "To save the world!",
  ui_story_5045_50450101_93_dialog_content = "Understood. Let the records show that the suspect is not only unemployed but also has adolescent delusions.",
  ui_story_5045_50450101_94_dialog_content = "Tell us truthfully—where were you between the hours of two o'clock and four o'clock this afternoon?",
  ui_story_5045_50450101_95_dialog_content = "I've been in the Hall of Justice this whole time.",
  ui_story_5045_50450101_96_dialog_content = "As a Caelestite, why have you come to the Lumopolis Hall of Justice?",
  ui_story_5045_50450101_96X1_dialog_content = "(Eh, w-why did I come to the Hall of Justice again?)",
  ui_story_5045_50450101_96X2_dialog_content = "(Actually standing here right now, my mind's gone totally blank!)",
  ui_story_5045_50450101_96X3_dialog_content = "(Fortunately, I wrote down some notes just now. Maybe I can remember something from them...)",
  ui_story_5045_50450101_97_dialog_content = "White Night up high, stop trying to derail the proceedings!",
  ui_story_5045_50450101_98_dialog_content = "M-My bad...",
  ui_story_5045_50450101_99_dialog_content = "Good, now let me ask you one more time.",
  ui_story_5045_50450101_100_dialog_content = "I received an <color=#1875ad>invitation</color> from Irridon.",
  ui_story_5045_50450101_101_dialog_content = "She asked me to come to the Hall of Justice and visit her in her office.",
  ui_story_5045_50450101_102_dialog_content = "She said she wanted to show me what a proper trial looks like, and that she had a job for me.",
  ui_story_5045_50450101_103_dialog_content = "I got here at two o'clock, but no one was around to show me the way to her office.",
  ui_story_5045_50450101_104_dialog_content = "After wandering around until three o'clock or so, I finally found her office. Only... she wasn't there at the time.",
  ui_story_5045_50450101_105_dialog_content = "That's when I decided to leave.",
  ui_story_5045_50450101_106_dialog_content = "After that, I spent the rest of the afternoon enjoying the sunshine on the steps of the Hall of Justice. That is, until someone brought me over to this small courtroom.",
  ui_story_5045_50450101_107_dialog_content = "Oh? So does this mean you admit to breaking into Judge Irridon's office?",
  ui_story_5045_50450101_108_dialog_content = "I didn't break into her office! The door was unlocked, so I walked in!",
  ui_story_5045_50450101_109_dialog_content = "Impossible. Judge Irridon herself said that she only left after locking her office door.",
  ui_story_5045_50450101_110_dialog_content = "Your rebuttal was a complete and utter disappointment, PlayerName.",
  ui_story_5045_50450101_111_dialog_content = "Your lack of employment made you desperate for quick money, so you decided to take advantage of Judge Irridon's trust.",
  ui_story_5045_50450101_112_dialog_content = "Unfortunately, you forgot one important thing...",
  ui_story_5045_50450101_113_dialog_content = "This is the Lumopolis Hall of Justice, where no criminal goes unpunished!",
  ui_story_5045_50450101_114_dialog_content = "As a judge, I hereby declare—",
  ui_story_5045_50450101_115_dialog_content = "<size=45>That PlayerName is <color=#1875ad>guilty</color>!</size>",
  ui_story_5045_50450201_1_dialog_content = "<size=45>That PlayerName is <color=#1875ad>guilty</color>!</size>",
  ui_story_5045_50450201_2_dialog_content = "W-Wait, I swear I'm not...",
  ui_story_5045_50450201_3_dialog_content = "Huh? PlayerName is guilty?",
  ui_story_5045_50450201_4_dialog_content = "Waking up just in time for the best part, I see? My, how very convenient.",
  ui_story_5045_50450201_5_dialog_content = "This isn't Angel's usual level of performance. She must be really nervous today.",
  ui_story_5045_50450201_6_dialog_content = "Like I said, commoners have no business becoming judges of Lumopolis. The burden is simply too great for them to bear.",
  ui_story_5045_50450201_7_dialog_content = "Judge Irridon, I failed my <color=#1875ad>mock trial</color> again, didn't I...",
  ui_story_5045_50450201_8_dialog_content = "Wait, this was a <color=#1875ad>mock trial</color> all along?!",
  ui_story_5045_50450201_9_dialog_content = "You're the judge right now, Angel.",
  ui_story_5045_50450201_10_dialog_content = "Don't forget, you still haven't called the court to end.",
  ui_story_5045_50450201_11_dialog_content = "Don't be so nervous, Angel!",
  ui_story_5045_50450201_12_dialog_content = "Why don't you go to the break room and take some time to clear your head?",
  ui_story_5045_50450201_13_dialog_content = "I disagree. You should take a few minutes to gather your thoughts and see if there are any contradictions in the statements that were given just now.",
  ui_story_5045_50450201_14_option_content = "Tina's right.",
  ui_story_5045_50450201_15_dialog_content = "Really? You actually agree with me, PlayerName?",
  ui_story_5045_50450201_16_dialog_content = "Yeah! Go take a break, Angel!",
  ui_story_5045_50450201_17_dialog_content = "I could use one too, since you guys just scared the crap out of me...",
  ui_story_5045_50450201_18_dialog_content = "Thank you for your kind suggestions, everyone.",
  ui_story_5045_50450201_19_option_content = "Leyn's right.",
  ui_story_5045_50450201_20_dialog_content = "You think so too, huh? Thanks, PlayerName.",
  ui_story_5045_50450201_21_dialog_content = "Yeah! Just keep calm and gather your thoughts, Angel!",
  ui_story_5045_50450201_22_dialog_content = "And even though it's just a mock trial, I still want everyone to know that I'm NOT a thief! Okay?",
  ui_story_5045_50450201_23_dialog_content = "Thank you for your kind suggestions, everyone.",
  ui_story_5045_50450201_24_option_content = "Let's just move on.",
  ui_story_5045_50450201_25_dialog_content = "Don't you think you guys should've told me about today?",
  ui_story_5045_50450201_26_dialog_content = "I had no idea what was happening, and you found me guilty right off the bat... That was kind of messed up, you know?",
  ui_story_5045_50450201_27_dialog_content = "Why don't we just forget about it this time, Angel? I promise I'll put on a much better act next time!",
  ui_story_5045_50450201_28_dialog_content = "No, that won't do at all!",
  ui_story_5045_50450201_29_dialog_content = "(Whoa. I don't think I've ever seen Angel so worked up before.)",
  ui_story_5045_50450201_30_dialog_content = "(Guess I should just stay out of it...)",
  ui_story_5045_50450201_31_dialog_content = "Ahem... I feel much more composed now.",
  ui_story_5045_50450201_32_dialog_content = "I was so worried about passing the mock trial that I embarrassed myself in front of everyone.",
  ui_story_5045_50450201_33_dialog_content = "For a judge of the Hall of Justice, good grades will never be as important as uncovering the truth in a case.",
  ui_story_5045_50450201_34_dialog_content = "But even if it's just a mock trial, we owe it to ourselves to trust in our decisions and never give up!",
  ui_story_5045_50450201_35_dialog_content = "Right!",
  ui_story_5045_50450201_36_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450201_37_dialog_content = "We shall now enter into the <color=#1875ad>discussion phase</color> of the trial!",
  ui_story_5045_50450201_38_dialog_content = "The floor is open to anyone who wishes to ask questions, share thoughts, or provide reasoning about the case.",
  ui_story_5045_50450201_39_dialog_content = "I'm not a thief!",
  ui_story_5045_50450201_40_dialog_content = "But this invitation proves that you were in my office at some point today.",
  ui_story_5045_50450201_41_dialog_content = "More importantly, you were the one who admitted to this.",
  ui_story_5045_50450201_42_dialog_content = "It's true that I went into your office, but I didn't take anything with me when I left! Not to mention that the door was unlocked when I got there!",
  ui_story_5045_50450201_43_dialog_content = "I am absolutely certain that I locked the door before I left.",
  ui_story_5045_50450201_44_dialog_content = "My guess is that you used your psychic abilities to unlock the door, then locked it once again before you left.",
  ui_story_5045_50450201_45_dialog_content = "That's not something I'm capable of doing with my powers!",
  ui_story_5045_50450201_46_dialog_content = "None of us are Caelestites, so we cannot be certain if you are lying or not.",
  ui_story_5045_50450201_47_dialog_content = "You're trying to frame me, aren't you?!",
  ui_story_5045_50450201_48_dialog_content = "Objection! Your Honor, PlayerName should not be allowed to make personal attacks against the plaintiff.",
  ui_story_5045_50450201_49_dialog_content = "This isn't fair... You guys are teaming up against me!",
  ui_story_5045_50450201_50_dialog_content = "PlayerName, you have the right to explain or question any details or evidence involved in this case.",
  ui_story_5045_50450201_51_dialog_content = "But choose your words carefully... Honesty and integrity are the cornerstones of the Hall of Justice.",
  ui_story_5045_50450201_52_dialog_content = "...",
  ui_story_5045_50450201_53_dialog_content = "Does anyone else in the court have something to discuss?",
  ui_story_5045_50450201_54_dialog_content = "The current situation is not in your favor at all, PlayerName. Do you have anything else to say?",
  ui_story_5045_50450201_55_dialog_content = "(Something's not right.)",
  ui_story_5045_50450201_56_dialog_content = "(It's true that I went into her office, but aside from that invitation letter...)",
  ui_story_5045_50450201_57_dialog_content = "(I should have left some other <color=#1875ad>traces</color> behind!)",
  ui_story_5045_50450201_58_dialog_content = "And what exactly is the problem with this?",
  ui_story_5045_50450201_59_dialog_content = "Huh? I guess that was the wrong thing to mention.",
  ui_story_5045_50450201_60_dialog_content = "(Come on, think! Aside from that invitation letter...)",
  ui_story_5045_50450201_61_dialog_content = "Irridon said that only her fingerprints were found on the doorknob, but that can't be right.",
  ui_story_5045_50450201_62_dialog_content = "Because I definitely turned it to get into the room!",
  ui_story_5045_50450201_63_dialog_content = "Which means my fingerprints should be on it too!",
  ui_story_5045_50450201_64_dialog_content = "You're absolutely right!",
  ui_story_5045_50450201_65_dialog_content = "I think the real thief must have wiped away their own fingerprints to cover their tracks.",
  ui_story_5045_50450201_66_dialog_content = "But they didn't realize that they wiped off my fingerprints too!",
  ui_story_5045_50450201_67_dialog_content = "That makes sense...",
  ui_story_5045_50450201_68_dialog_content = "How can we be sure that it wasn't you who wiped the doorknob clean?",
  ui_story_5045_50450201_69_dialog_content = "(Sigh... It looks like the only way to clear my name is to find the real thief.)",
  ui_story_5045_50450201_70_dialog_content = "(Wait!)",
  ui_story_5045_50450201_71_dialog_content = "(I'm not the thief, that much is certain... But <color=#1875ad>that person's testimony</color> might give us a clue!)",
  ui_story_5045_50450201_72_dialog_content = "And what exactly is the problem with this?",
  ui_story_5045_50450201_73_dialog_content = "S-Sorry, I misspoke just now...",
  ui_story_5045_50450201_74_dialog_content = "(Just calm down and think carefully...)",
  ui_story_5045_50450201_75_dialog_content = "When exactly did you see me \"sneaking around\", Pittman?",
  ui_story_5045_50450201_76_dialog_content = "At approximately three o'clock.",
  ui_story_5045_50450201_77_dialog_content = "Can you be more specific about the time?",
  ui_story_5045_50450201_78_dialog_content = "I think... It might have been ten minutes past the hour or so.",
  ui_story_5045_50450201_79_dialog_content = "That's strange, considering I left the office shortly before the clock struck three—so how exactly did you see me there?",
  ui_story_5045_50450201_80_dialog_content = "I should mention that the clock struck three just after I walked out of the Hall of Justice.",
  ui_story_5045_50450201_81_dialog_content = "The guards who were stationed outside can attest to this.",
  ui_story_5045_50450201_82_dialog_content = "Th-This...",
  ui_story_5045_50450201_83_dialog_content = "I can't be certain, but it's possible that the figure I saw was the real thief.",
  ui_story_5045_50450201_84_dialog_content = "Which would mean that it was someone else and not me! Right, Pittman?",
  ui_story_5045_50450201_85_dialog_content = "That would appear to be the case, yes.",
  ui_story_5045_50450201_86_dialog_content = "So you see, Your Honor, Pittman has no way of confirming that the figure he saw sneaking around was actually me.",
  ui_story_5045_50450201_87_dialog_content = "As such, his accusation should be disregarded!",
  ui_story_5045_50450201_88_dialog_content = "It does appear to be this way...",
  ui_story_5045_50450201_89_dialog_content = "But that doesn't mean you have cleared yourself of suspicion.",
  ui_story_5045_50450201_90_dialog_content = "Why don't we try looking at things a little differently? Let's assume I'm not the thief; by doing that, you can clearly see a lot of problems with the case.",
  ui_story_5045_50450201_91_dialog_content = "First of all, how did the thief manage to open the door? Is it possible that they had an extra key?",
  ui_story_5045_50450201_92_dialog_content = "...",
  ui_story_5045_50450201_93_dialog_content = "Second, why would the thief go to the trouble of wiping off their fingerprints?",
  ui_story_5045_50450201_94_dialog_content = "It would make sense if it was someone associated with the Hall of Justice, since all it would take to expose them is a quick investigation.",
  ui_story_5045_50450201_95_dialog_content = "...",
  ui_story_5045_50450201_96_dialog_content = "Tell us, Pittman, is it possible that you're the thief?",
  ui_story_5045_50450201_97_dialog_content = "H-How could that even be?",
  ui_story_5045_50450201_98_dialog_content = "You're Irridon's most trusted subordinate, after all. If anyone knows about her leaving Nightium at her office, it's you.",
  ui_story_5045_50450201_99_dialog_content = "Not only that, but you also saw Irridon leave her office, which would have been the perfect time to pull out a spare key and go inside.",
  ui_story_5045_50450201_100_dialog_content = "But it was only after you left with the Nightium that you realized. Your fingerprints were still on the doorknob!",
  ui_story_5045_50450201_101_dialog_content = "That's when you hurried back to wipe them off and lock the door again, making it look like the money just disappeared.",
  ui_story_5045_50450201_102_dialog_content = "What you didn't know, is that you also dragged me into your crime!",
  ui_story_5045_50450201_103_dialog_content = "So when you saw that Irridon suspected me of stealing her Nightium, you took the initiative and tried to get me to take the fall for you!",
  ui_story_5045_50450201_104_dialog_content = "This is all just wild speculation, nothing more! Do you have any proof?!",
  ui_story_5045_50450201_105_dialog_content = "It's true that I'm assuming a lot of things here. But let me ask you something! When I touched on all those points...",
  ui_story_5045_50450201_106_dialog_content = "Why did you suddenly start sweating so much? Also, why are you keep reaching for your <color=#1875ad>pocket</color> every few seconds?",
  ui_story_5045_50450201_107_dialog_content = "Could it be that you actually have a spare key to Irridon's office in there?",
  ui_story_5045_50450201_108_dialog_content = "Mr. Pittman, please show the court what you have in your pocket.",
  ui_story_5045_50450201_109_dialog_content = "...",
  ui_story_5045_50450201_110_dialog_content = "I suppose I have no choice.",
  ui_story_5045_50450201_111_dialog_content = "This key is an exact copy of the key to my office!",
  ui_story_5045_50450201_112_dialog_content = "Mr. Pittman, you stand accused of stealing Judge Irridon's Nightium. Do you have anything to say for yourself?",
  ui_story_5045_50450201_113_dialog_content = "I... I don't. I have nothing to say.",
  ui_story_5045_50450201_114_dialog_content = "If that's the case, then I hereby declare—",
  ui_story_5045_50450201_115_dialog_content = "<size=45>Pittman is <color=#1875ad>guilty</color> of this crime!</size>",
  ui_story_5045_50450201_116_dialog_content = "Whew... Glad that's over.",
  ui_story_5045_50450201_117_dialog_content = "I just knew I was going to fail my mock trial...",
  ui_story_5045_50450201_118_dialog_content = "No need to feel discouraged, Angel. There will be more opportunities in the future.",
  ui_story_5045_50450201_119_dialog_content = "Your seniors here were no different. They only became judges after undergoing countless mock trials and assessments.",
  ui_story_5045_50450201_120_dialog_content = "It's true. In fact, I failed more mock trials than anyone else in the history of the Hall of Justice!",
  ui_story_5045_50450201_121_dialog_content = "Don't let Leyn's excitement fool you, Angel. That's not really something to be proud of.",
  ui_story_5045_50450201_122_dialog_content = "Pardon me, Judge Irridon, but I beg to differ. If you remember correctly, I passed my assessment on my very first try!",
  ui_story_5045_50450201_123_dialog_content = "Yes, I seem to recall now. While we're on the subject, Matthieu...",
  ui_story_5045_50450201_124_dialog_content = "Since Loewe has been on leave recently, Angel will work under you as your assistant for the next few days. I think she could learn much from you.",
  ui_story_5045_50450201_125_dialog_content = "With my intelligence and talent, I hardly think I require an assistant, Judge Irridon!",
  ui_story_5045_50450201_126_dialog_content = "Don't you think our best judges have a responsibility to train our future generations to be just as exemplary?",
  ui_story_5045_50450201_127_dialog_content = "I see, now...",
  ui_story_5045_50450201_128_dialog_content = "You couldn't be more right, Judge Irridon!",
  ui_story_5045_50450201_129_dialog_content = "As one of the greatest judges to ever grace the Hall of Justice, I swear to live up to your expectations and pass on all of my knowledge to my new apprentice!",
  ui_story_5045_50450201_130_dialog_content = "Just try not to expect too much from her... After all, not many can compare to my greatness!",
  ui_story_5045_50450201_131_dialog_content = "<size=32>But I want to be Mr. Pittman's assistant!</size>",
  ui_story_5045_50450301_1_dialog_content = "<color=#737378>Time: 8:00 PM</color>",
  ui_story_5045_50450301_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice</color>",
  ui_story_5045_50450301_3_dialog_content = "I truly had no idea that you, of all people, would be the one to ultimately crack this case.",
  ui_story_5045_50450301_4_dialog_content = "It was just dumb luck, really...",
  ui_story_5045_50450301_5_dialog_content = "(Honestly, Pittman's convincing performance is what really saved me.)",
  ui_story_5045_50450301_6_dialog_content = "Hey, Irridon? Something tells me that today's mock trial was based on a real case of theft.",
  ui_story_5045_50450301_7_dialog_content = "Indeed it was. Yet another astute assumption, PlayerName.",
  ui_story_5045_50450301_8_dialog_content = "I also know that you only sent me that letter to get me wrapped up in this whole thing!",
  ui_story_5045_50450301_9_dialog_content = "You know, if you had just told me it was for a mock trial, I could've been more helpful.",
  ui_story_5045_50450301_10_dialog_content = "In a real trial, unexpected situations arise all of the time.",
  ui_story_5045_50450301_11_dialog_content = "We simply wanted to introduce a few independent variables to the mock trial.",
  ui_story_5045_50450301_12_dialog_content = "However, it was only thanks to you that Angel was able to bring the trial to a satisfying conclusion.",
  ui_story_5045_50450301_13_dialog_content = "I see... Guess that makes me a pretty reliable variable, huh?",
  ui_story_5045_50450301_14_dialog_content = "Indeed. Your powers of observation are incredibly keen.",
  ui_story_5045_50450301_15_dialog_content = "In fact, and I say this with no exaggeration, but your performance today was on the same level as many of our judges undergoing their assessments.",
  ui_story_5045_50450301_16_dialog_content = "If only we had more people like you here in the Hall of Justice.",
  ui_story_5045_50450301_17_dialog_content = "But enough about that.",
  ui_story_5045_50450301_18_dialog_content = "We would like to compensate you for your help today. Consider it a token of gratitude from all of us in the Hall of Justice.",
  ui_story_5045_50450301_19_dialog_content = "Compensate me?",
  ui_story_5045_50450301_20_dialog_content = "Here you are: the stolen goods from today's mock trial.",
  ui_story_5045_50450301_21_dialog_content = "Wow, I thought this Nightium was just being used as a prop for the trial.",
  ui_story_5045_50450301_22_dialog_content = "Are you really giving this to me?",
  ui_story_5045_50450301_23_dialog_content = "Why? Is it too little?",
  ui_story_5045_50450301_24_dialog_content = "N-N-Not at all! It's more than enough!",
  ui_story_5045_50450301_25_dialog_content = "In fact, feel free to call me whenever you have more work like this!",
  ui_story_5045_50450301_26_dialog_content = "Really? I had no idea you were so interested in working for the Hall of Justice, PlayerName...",
  ui_story_5045_50450301_27_dialog_content = "I mean, aside from the initial shock...",
  ui_story_5045_50450301_28_dialog_content = "I actually found the work to be pretty interesting!",
  ui_story_5045_50450301_29_dialog_content = "Hearing you say that brings me much joy.",
  ui_story_5045_50450301_30_dialog_content = "Tell me, would you like to spend some time here and work with us?",
  ui_story_5045_50450301_31_dialog_content = "You see, I recently established a new department within the Hall of Justice, and we could use someone with interpersonal skills such as your own.",
  ui_story_5045_50450301_32_dialog_content = "A new department?",
  ui_story_5045_50450301_33_dialog_content = "It looks like you're interested, after all. In that case, please accept this. You'll need it soon enough.",
  ui_story_5045_50450301_34_dialog_content = "Is this... a<color=#1875ad> Judge's Notebook</color>?",
  ui_story_5045_50450301_35_dialog_content = "From this day forth, you are a <color=#1875ad>probationary judge</color> of the Hall of Justice.",
  ui_story_5045_50450301_36_dialog_content = "<color=#737378>Time: 8:00 AM</color>",
  ui_story_5045_50450301_37_dialog_content = "<color=#737378>Location: An office in the Lumo Hall of Justice</color>",
  ui_story_5045_50450301_38_dialog_content = "Is this the place where Irridon told me to report?",
  ui_story_5045_50450301_39_dialog_content = "Good morning, everyone! How can I help—",
  ui_story_5045_50450301_40_dialog_content = "What kind of case is this?!",
  ui_story_5045_50450301_41_dialog_content = "The plaintiff is right, but so is the defendant...",
  ui_story_5045_50450301_42_dialog_content = "I don't see any laws or legal precedents that apply to this case. Who am I supposed to believe here?!",
  ui_story_5045_50450301_43_dialog_content = "Zzz...",
  ui_story_5045_50450301_44_dialog_content = "Take a good look, Angel.",
  ui_story_5045_50450301_45_dialog_content = "This is why you're studying under me, and not one of those two good-for-nothing judges.",
  ui_story_5045_50450301_46_dialog_content = "But sir, as far as I know, your grades aren't much better than theirs...",
  ui_story_5045_50450301_47_dialog_content = "<size=32>This would explain why you were assigned to such a minor department along with them...</size>",
  ui_story_5045_50450301_48_dialog_content = "My goodness. You're even worse than Loewe, aren't you?!",
  ui_story_5045_50450301_49_dialog_content = "Allow me to repeat myself: I chose to transfer to this department out of sheer interest and my overwhelming sense of duty!",
  ui_story_5045_50450301_50_dialog_content = "Now unless you want to keep failing your assessments, I suggest you gather your things and come along quickly.",
  ui_story_5045_50450301_51_dialog_content = "Yes, sir...",
  ui_story_5045_50450301_52_dialog_content = "Hmm? Why if it isn't PlayerName! What brings you to the doorstep of the <color=#1875ad>Hall of Justice's Romance Division</color> today?",
  ui_story_5045_50450301_53_dialog_content = "Wow, they even gave you guys such a nice office for the Romance Division...",
  ui_story_5045_50450301_54_dialog_content = "Nice, you say? Hah!",
  ui_story_5045_50450301_55_dialog_content = "Just wait until I'm Chief Judge of the Romance Division, then you'll see an office truly befitting a noble such as myself!",
  ui_story_5045_50450301_56_dialog_content = "Chief Judge of the Romance Division?",
  ui_story_5045_50450301_57_dialog_content = "Yes, and you would do well to get out of my way now!",
  ui_story_5045_50450301_58_dialog_content = "...",
  ui_story_5045_50450301_59_dialog_content = "Sigh... Ever since the Romance Division was established, the position of Chief Judge kept rotating between different people. Meanwhile, our backlog of cases only gets bigger and bigger.",
  ui_story_5045_50450301_60_dialog_content = "As it stands, no one is willing to serve as Chief Judge of the Romance Division.",
  ui_story_5045_50450301_61_dialog_content = "... With the exception of my seniors here, of course. They're doing everything in their power to get promoted to Chief Judge.",
  ui_story_5045_50450301_62_dialog_content = "<size=45>Don't keep me waiting, Angel!!</size>",
  ui_story_5045_50450301_63_dialog_content = "Sigh... Well, best of luck, PlayerName!",
  ui_story_5045_50450301_64_dialog_content = "I thought the new department Irridon mentioned before was specifically for mock trials.",
  ui_story_5045_50450301_65_dialog_content = "Why the Romance Division...?",
  ui_story_5045_50450301_66_dialog_content = "PlayerName?",
  ui_story_5045_50450301_67_dialog_content = "So you're the newest member of the Romance Division, huh?",
  ui_story_5045_50450301_68_option_content = "I think there's been a mistake.",
  ui_story_5045_50450301_69_dialog_content = "Judge Irridon asked you to help us, right?",
  ui_story_5045_50450301_70_dialog_content = "That's right.",
  ui_story_5045_50450301_71_dialog_content = "Then why would there be a mistake? This is Judge Irridon we're talking about, after all.",
  ui_story_5045_50450301_72_dialog_content = "So you're the newest member of the Romance Division!",
  ui_story_5045_50450301_73_option_content = "I hope I won't make things worse.",
  ui_story_5045_50450301_74_dialog_content = "You're too modest.",
  ui_story_5045_50450301_75_dialog_content = "Judge Irridon personally chose you as our newest member. I'm sure we'll be able to learn a lot from you!",
  ui_story_5045_50450301_76_option_content = "Well, it's a good thing you're here.",
  ui_story_5045_50450301_77_dialog_content = "Having someone as reliable as you on the team really puts my mind at ease.",
  ui_story_5045_50450301_78_dialog_content = "I'm looking forward to learning from you!",
  ui_story_5045_50450301_79_dialog_content = "D-Don't expect too much! I haven't been working in the Romance Division for very long. I'm still fairly new at this too.",
  ui_story_5045_50450301_80_dialog_content = "Zzz...",
  ui_story_5045_50450301_81_dialog_content = "Who is here?",
  ui_story_5045_50450301_82_dialog_content = "Hey, it's our prime suspect from yesterday's mock trial! Nice to see you again, PlayerName!",
  ui_story_5045_50450301_83_dialog_content = "Although if you're here, it must mean you're having some serious relationship issues?",
  ui_story_5045_50450301_84_dialog_content = "Just submit a formal complaint with all the details of your dispute, and we'll get right on it! *yawns*",
  ui_story_5045_50450301_85_option_content = "I don't have those kinds of problems!",
  ui_story_5045_50450301_86_dialog_content = "My, you sound pretty confident in yourself.",
  ui_story_5045_50450301_87_dialog_content = "Is it because you're secretly a pickup artist? Or maybe you're one of those iron-hearted nerds?",
  ui_story_5045_50450301_88_dialog_content = "N-None of the above! I'm here to help you guys!",
  ui_story_5045_50450301_89_dialog_content = "Ah, so you're the new guy! Welcome, welcome!",
  ui_story_5045_50450301_90_option_content = "Sorry for waking you up.",
  ui_story_5045_50450301_91_dialog_content = "Wow. This is the first time someone's actually apologized for waking me up! I'm so touched...",
  ui_story_5045_50450301_92_dialog_content = "Just kidding, I don't mind at all! Besides, I should be awake right now, since we have a new member joining our department today.",
  ui_story_5045_50450301_93_dialog_content = "That new member... I'm pretty sure it's me.",
  ui_story_5045_50450301_94_dialog_content = "Ah, so you're the new guy! Welcome, welcome!",
  ui_story_5045_50450301_95_option_content = "I'm here to help.",
  ui_story_5045_50450301_96_dialog_content = "Although I still have no idea how I'm going to do that...",
  ui_story_5045_50450301_97_dialog_content = "Wow. So you're the promising, new addition to our team! You have no idea how much I've been looking forward to this!",
  ui_story_5045_50450301_98_dialog_content = "In fact, I even had a dream last night that you came to the Romance Division, PlayerName! I never thought that my dream would come true!",
  ui_story_5045_50450301_99_dialog_content = "I always tell people there's nothing wrong with sleeping and dreaming a little more than usual, and this is precisely why!",
  ui_story_5045_50450301_100_dialog_content = "And with your help, PlayerName... I might even get promoted to Chief Judge!",
  ui_story_5045_50450301_101_dialog_content = "What are you talking about, Tina?",
  ui_story_5045_50450301_102_dialog_content = "Huh? You mean you haven't realized it yet, Leyn?",
  ui_story_5045_50450301_103_dialog_content = "No one wants to serve as Chief Judge of a department as awkward and complicated as ours right now...",
  ui_story_5045_50450301_104_dialog_content = "That's why Matthieu's in such a hurry to get started on these cases while the position is still vacant.",
  ui_story_5045_50450301_105_dialog_content = "He thinks that by doing so, Judge Irridon might consider appointing him as the head of our department!",
  ui_story_5045_50450301_106_dialog_content = "Matthieu? As Chief Judge of the Romance Division?!",
  ui_story_5045_50450301_107_dialog_content = "That's right. You can imagine what our lives would be like if I succeeded, can't you? That's why we would be better off with me in charge!",
  ui_story_5045_50450301_108_dialog_content = "I wouldn't mind at all if you were chosen as Chief Judge, Leyn.",
  ui_story_5045_50450301_109_dialog_content = "I just worry that with you in charge, the other departments might look down on the Romance Division even more.",
  ui_story_5045_50450301_110_dialog_content = "They can look down on me all they want, but not on the Romance Division!",
  ui_story_5045_50450301_111_dialog_content = "If I get appointed Chief Judge of our department, I swear I'll do everything in my power to get the respect we deserve!",
  ui_story_5045_50450301_112_dialog_content = "Hmm... Looks like you've got your eye on the position too, Leyn.",
  ui_story_5045_50450301_113_dialog_content = "Good! A little friendly competition will motivate us to work even harder!",
  ui_story_5045_50450301_114_dialog_content = "I'll be counting on you, PlayerName!",
  ui_story_5045_50450301_115_dialog_content = "Hey, what's that supposed to mean? PlayerName is here to help our entire department! You can't just have him all to yourself!",
  ui_story_5045_50450301_116_dialog_content = "Oh? But I thought you didn't like working with others, Leyn?",
  ui_story_5045_50450301_117_dialog_content = "Or could it be that you're feeling a little envious?",
  ui_story_5045_50450301_118_dialog_content = "I wonder, are you jealous of me because I have PlayerName on my side, or are you jealous of PlayerName because he gets to work with me?",
  ui_story_5045_50450301_119_dialog_content = "I'm just worried that you'll put too much stress on PlayerName, that's all.",
  ui_story_5045_50450301_120_dialog_content = "We have a lot on our plate, and since you can only work for a short period of time... Wait, you're not planning on foisting your workload on PlayerName, are you?!",
  ui_story_5045_50450301_121_dialog_content = "Oh my, I had no idea you could be so sympathetic toward other people.",
  ui_story_5045_50450301_122_dialog_content = "Anyways, you'll need to come up with a more sustainable solution for your problem.",
  ui_story_5045_50450301_123_dialog_content = "I have an idea!",
  ui_story_5045_50450301_124_dialog_content = "Why don't we let PlayerName decide who he wants to work with?",
  ui_story_5045_50450301_125_dialog_content = "I see. That sounds fair enough to me.",
  ui_story_5045_50450301_126_dialog_content = "What do you think, PlayerName?",
  ui_story_5045_50450301_127_dialog_content = "I-I don't think I can make that kind of choice right now.",
  ui_story_5045_50450301_128_dialog_content = "Then don't think about it so much! You'd be way better off as my assistant, you know? I can even pay you extra, if needed!",
  ui_story_5045_50450301_129_dialog_content = "Th-That's not...",
  ui_story_5045_50450301_130_dialog_content = "I may not have the funds to buy out your services like some people, but I guarantee that your labor will not be exploited if you choose to work for me.",
  ui_story_5045_50450301_131_dialog_content = "I'll take the lion's share of the work; all you need to do is offer me some new perspective every now and then and remind me to be fair at all times!",
  ui_story_5045_50450301_132_dialog_content = "(Both of them seem really desperate for my help...)",
  ui_story_5045_50450301_133_dialog_content = "(What should I do?!)",
  ui_story_5045_50450301_134_option_content = "Pick Leyn",
  ui_story_5045_50450301_135_dialog_content = "To be honest, I have no idea how to help you guys in the Hall of Justice, for that matter.",
  ui_story_5045_50450301_136_dialog_content = "But if what Leyn says is true, I think I can handle that kind of work.",
  ui_story_5045_50450301_137_dialog_content = "I'm positive you'll do just fine!",
  ui_story_5045_50450301_138_option_content = "Pick Tina",
  ui_story_5045_50450301_139_dialog_content = "Well, since Tina really needs help right now, I suppose I can give it a shot.",
  ui_story_5045_50450301_140_dialog_content = "Fair warning, though! I have almost zero knowledge of any of this stuff!",
  ui_story_5045_50450301_141_dialog_content = "Don't worry. I'll be sure to teach you everything I know... Yawn—",
  ui_story_5045_50450301_142_dialog_content = "But first, a quick nap.",
  ui_story_5045_50450301_143_option_content = "Pick neither",
  ui_story_5045_50450301_144_dialog_content = "You guys said I'm the newest member of the Romance Division, right? So what's stopping me from competing with you guys for the position of Chief Judge?",
  ui_story_5045_50450301_145_dialog_content = "When you put it that way, I guess you're free to do that too! But you'll need to become an actual judge first.",
  ui_story_5045_50450301_146_dialog_content = "You know, Tina, if PlayerName is confident enough to say something like this, I think we should offer our full support.",
  ui_story_5045_50450301_147_dialog_content = "Who knows? He might even fly through training and become a judge in a short time, just like Matthieu!",
  ui_story_5045_50450301_148_dialog_content = "Sounds good to me... Yawn...",
  ui_story_5045_50450401_1_dialog_content = "<color=#737378>Time: 6:00 PM</color>",
  ui_story_5045_50450401_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50450401_3_dialog_content = "So is there anything else I can help with, Leyn?",
  ui_story_5045_50450401_4_dialog_content = "Oh, just gather the rest of those statements and that should be enough.",
  ui_story_5045_50450401_5_dialog_content = "I can take care of the rest.",
  ui_story_5045_50450401_6_dialog_content = "Though by now, you should be getting ready to go home for the day.",
  ui_story_5045_50450401_7_dialog_content = "What about you?",
  ui_story_5045_50450401_8_dialog_content = "We received another hundred or so complaints today that still need reviewing.",
  ui_story_5045_50450401_9_dialog_content = "Once that's done, I need to take the complaints that are missing materials and send them back for resubmission.",
  ui_story_5045_50450401_10_dialog_content = "But it's already so late... You're really staying to do all of that?",
  ui_story_5045_50450401_11_dialog_content = "To tell you the truth... The cases handled by the Romance Division are all very difficult for me to understand.",
  ui_story_5045_50450401_12_dialog_content = "I need to take the time to study them and learn how to pass judgment on them to the best of my abilities.",
  ui_story_5045_50450401_13_dialog_content = "I see... But from what I can tell, you've already marked all of them for resubmission. Why's that?",
  ui_story_5045_50450401_14_dialog_content = "According to the corresponding newly amended provisions of Lumopolis, so far, all the cases I've handled have had some problems.",
  ui_story_5045_50450401_15_dialog_content = "I'm only following the rules, that's all.",
  ui_story_5045_50450401_16_dialog_content = "But at this rate, you'll never get around to closing a single case!",
  ui_story_5045_50450401_17_dialog_content = "Heh... You seem to be in an even bigger hurry than me.",
  ui_story_5045_50450401_18_dialog_content = "Well, obviously! We're partners, aren't we?",
  ui_story_5045_50450401_19_dialog_content = "Partners...?",
  ui_story_5045_50450401_20_dialog_content = "That's right!",
  ui_story_5045_50450401_21_dialog_content = "I appreciate your concern, I really do, But I swore that I wouldn't take advantage of your labor.",
  ui_story_5045_50450401_22_dialog_content = "Fine... Then let's just hang out for a bit, okay? You look like you could use a quick break.",
  ui_story_5045_50450401_23_dialog_content = "Sure. Besides I've been meaning to ask you something, PlayerName.",
  ui_story_5045_50450401_24_dialog_content = "Do you know what love is?",
  ui_story_5045_50450401_25_dialog_content = "L-Love?",
  ui_story_5045_50450401_26_option_content = "I do.",
  ui_story_5045_50450401_27_dialog_content = "It's when two people like each other so much that they're willing to spend the rest of their lives together, right?",
  ui_story_5045_50450401_28_dialog_content = "I must say, your understanding of the world really impresses me sometimes, PlayerName!",
  ui_story_5045_50450401_29_dialog_content = "I-I'm just guessing, really...",
  ui_story_5045_50450401_30_option_content = "Not really...",
  ui_story_5045_50450401_31_dialog_content = "But I've read about love in lots of stories!",
  ui_story_5045_50450401_32_dialog_content = "Judging from their descriptions, love is something really mysterious.",
  ui_story_5045_50450401_33_dialog_content = "So you're a fan of love stories, PlayerName? Looks like I'm asking the right person.",
  ui_story_5045_50450401_34_dialog_content = "I-I wouldn't say I'm a fan or anything...",
  ui_story_5045_50450401_35_option_content = "I won't tell!",
  ui_story_5045_50450401_36_dialog_content = "It's a secret, and I'm not telling!",
  ui_story_5045_50450401_37_dialog_content = "H-How very mysterious of you...",
  ui_story_5045_50450401_38_dialog_content = "You're pretty popular yourself, aren't you, Leyn?",
  ui_story_5045_50450401_39_dialog_content = "You probably know more about love than I do, right?",
  ui_story_5045_50450401_40_dialog_content = "Well...",
  ui_story_5045_50450401_41_dialog_content = "I suppose it's true that I've been the object of affection for more than a few ladies.",
  ui_story_5045_50450401_42_dialog_content = "But unfortunately, I've never been able to return their feelings.",
  ui_story_5045_50450401_43_dialog_content = "Huh? Why's that?",
  ui_story_5045_50450401_44_dialog_content = "I don't know. I've never really given it much thought, to be honest.",
  ui_story_5045_50450401_45_dialog_content = "But when I was assigned to the Hall of Justice's Romance Division, and tasked with helping couples settle their disputes.",
  ui_story_5045_50450401_46_dialog_content = "That's when I realized I don't know the first thing about love.",
  ui_story_5045_50450401_47_dialog_content = "I even started to doubt if I had ever felt love before in my life...",
  ui_story_5045_50450401_48_dialog_content = "Am I really fit to work as a judge in the Romance Division?",
  ui_story_5045_50450401_49_dialog_content = "Of course you are!",
  ui_story_5045_50450401_50_dialog_content = "What makes you so sure about that?",
  ui_story_5045_50450401_51_dialog_content = "A judge doesn't have to steal in order to pass judgment on a burglar, right?",
  ui_story_5045_50450401_52_dialog_content = "I'm pretty sure the same goes for resolving relationship issues!",
  ui_story_5045_50450401_53_dialog_content = "That seems like a bit of a stretch...",
  ui_story_5045_50450401_54_dialog_content = "But in a way, it makes total sense!",
  ui_story_5045_50450401_55_dialog_content = "Staring at these complaints all day won't get you very far. What matters most is learning through practice!",
  ui_story_5045_50450401_56_dialog_content = "You should try your hand at a few cases and build up your experience first. The rest should come quickly enough!",
  ui_story_5045_50450401_57_dialog_content = "You're right... I can't believe I've been so indecisive lately!",
  ui_story_5045_50450401_58_dialog_content = "I should just start with the first case in front of me!",
  ui_story_5045_50450401_59_dialog_content = "\"The plaintiff, <color=#1875ad>Farrell</color>, demands that the defendant, <color=#1875ad>Sophie</color>, marry him in accordance with the law...\"",
  ui_story_5045_50450401_60_dialog_content = "Th-This is some kind of request... Maybe you should start with something a little less tricky?",
  ui_story_5045_50450401_61_dialog_content = "No need.",
  ui_story_5045_50450401_62_dialog_content = "As a judge, it's my responsibility to address every one of these cases to the best of my abilities.",
  ui_story_5045_50450401_63_dialog_content = "Not only that...",
  ui_story_5045_50450401_64_dialog_content = "I realize that it's a waste of your talents to ask you to help me organize the complaint.",
  ui_story_5045_50450401_65_dialog_content = "Starting tomorrow, you and I will hear each of these cases together.",
  ui_story_5045_50450401_66_dialog_content = "H-Huh? Are you sure about that?",
  ui_story_5045_50450401_67_dialog_content = "Of course. You said it yourself: we're partners, right?",
  ui_story_5045_50450501_1_dialog_content = "<color=#737378>Time: 9:00 AM</color>",
  ui_story_5045_50450501_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Courtroom</color>",
  ui_story_5045_50450501_3_dialog_content = "Look over there! It's Leyn!",
  ui_story_5045_50450501_4_dialog_content = "...",
  ui_story_5045_50450501_5_dialog_content = "(It looks like many ladies in the audience came just to see Leyn?)",
  ui_story_5045_50450501_6_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450501_7_dialog_content = "<size=45>White Night up high. Court is now in session!</size>",
  ui_story_5045_50450501_8_dialog_content = "White Night up high!",
  ui_story_5045_50450501_9_dialog_content = "...",
  ui_story_5045_50450501_10_dialog_content = "Do you know who should be first addressed by the court, PlayerName?",
  ui_story_5045_50450501_11_dialog_content = "Hmm... I'm pretty sure it's supposed to be the plaintiff...",
  ui_story_5045_50450501_12_option_content = "Farrell",
  ui_story_5045_50450501_13_dialog_content = "That's right! Glad to see you remember!",
  ui_story_5045_50450501_14_option_content = "Sophie",
  ui_story_5045_50450501_15_dialog_content = "The plaintiff is Farrell.",
  ui_story_5045_50450501_16_dialog_content = "Differentiating between the plaintiff and the defendant is one of the most basic parts of the job. You should remember that in the future.",
  ui_story_5045_50450501_17_dialog_content = "(Man... How'd I get that one wrong?)",
  ui_story_5045_50450501_18_dialog_content = "(I gotta make sure to take better notes on everything next time!)",
  ui_story_5045_50450501_19_dialog_content = "Will the plaintiff please address the court?",
  ui_story_5045_50450501_20_dialog_content = "Good day, Your Honor. My name is Farrell.",
  ui_story_5045_50450501_21_dialog_content = "The plaintiff is a <color=#1875ad>knight</color> of Lumopolis, huh? That's unexpected...",
  ui_story_5045_50450501_22_dialog_content = "Careful, PlayerName. As judges, we cannot allow preconceived notions of any kind to affect our judgment.",
  ui_story_5045_50450501_23_dialog_content = "O-Okay...",
  ui_story_5045_50450501_24_dialog_content = "Farrell, please tell us why you came to the Hall of Justice today?",
  ui_story_5045_50450501_25_dialog_content = "Because the defendant and I had an agreement!",
  ui_story_5045_50450501_26_dialog_content = "Please elaborate on this agreement between the two of you.",
  ui_story_5045_50450501_27_dialog_content = "Our agreement was that we would get married as soon as our <color=#1875ad>financial resources were equal</color>!",
  ui_story_5045_50450501_28_dialog_content = "But that's normal, isn't it? People always sign betrothal agreements like that to protect their assets.",
  ui_story_5045_50450501_29_dialog_content = "This Sophie person doesn't look particularly well-off. She was most likely trying to take advantage of the knight's economic standing.",
  ui_story_5045_50450501_30_dialog_content = "Do they honestly think such petty disputes are worthy of wasting Judge Leyn's time?",
  ui_story_5045_50450501_31_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450501_32_dialog_content = "Silence! Order in the court!",
  ui_story_5045_50450501_33_dialog_content = "Farrell, may I ask if there were any witnesses to this agreement? Or perhaps proof of some sort?",
  ui_story_5045_50450501_34_dialog_content = "Y-Yes, Your Honor.",
  ui_story_5045_50450501_35_dialog_content = "Here is the <color=#1875ad>contract</color> we signed. You'll find that it was made in accordance with Lumopolis regulations.",
  ui_story_5045_50450501_36_dialog_content = "Hmm... The contract does appear to be in perfect order.",
  ui_story_5045_50450501_37_dialog_content = "Will you please make your demands known to the court?",
  ui_story_5045_50450501_38_dialog_content = "Since our finances are now equal, I ask that the court enforces our agreement to marry one another!",
  ui_story_5045_50450501_39_dialog_content = "I'm sorry, did I hear that correctly?",
  ui_story_5045_50450501_40_dialog_content = "How could a commoner's finances equal those of a knight?",
  ui_story_5045_50450501_41_dialog_content = "The defendant clearly cheated him out of his money.",
  ui_story_5045_50450501_42_dialog_content = "Sophie.",
  ui_story_5045_50450501_43_dialog_content = "Yes, Your Honor!",
  ui_story_5045_50450501_44_dialog_content = "Have you anything to say about this contract?",
  ui_story_5045_50450501_45_dialog_content = "I do, Your Honor. It's true that I signed that agreement.",
  ui_story_5045_50450501_46_dialog_content = "But when I met Farrell, I was still young and inexperienced in the ways of the world... I had no idea what love meant at the time.",
  ui_story_5045_50450501_47_dialog_content = "Back then, Farrell courted me with sweet words and grand promises. He made me truly believe that he was my soul mate.",
  ui_story_5045_50450501_48_dialog_content = "I was overwhelmed by his false affection, which is why I signed that contract.",
  ui_story_5045_50450501_49_dialog_content = "But as time went by, I realized we weren't meant to be together. I even suggested that we go our separate ways on more than one occasion.",
  ui_story_5045_50450501_50_dialog_content = "For this reason, I abide by our agreement to marry.",
  ui_story_5045_50450501_51_dialog_content = "In other words, you are refusing to honor the contents of this signed agreement. Is that correct?",
  ui_story_5045_50450501_52_dialog_content = "Yes, Your Honor. I would rather spend the rest of my life in prison than spend it with someone I do not love.",
  ui_story_5045_50450501_53_dialog_content = "D-Don't say things like that, Sophie...",
  ui_story_5045_50450501_54_dialog_content = "You know that breaking off our engagement would only hurt my reputation as a knight!",
  ui_story_5045_50450501_55_dialog_content = "How could you still be so blind to my love for you?!",
  ui_story_5045_50450501_56_dialog_content = "I can't bear your love any longer, Farrell...",
  ui_story_5045_50450501_57_dialog_content = "You've done nothing but watch my every move and harass me at every turn!",
  ui_story_5045_50450501_58_dialog_content = "I only do it to protect you, Sophie!",
  ui_story_5045_50450501_59_dialog_content = "Well, I'm sorry, but I don't need anyone's protection.",
  ui_story_5045_50450501_60_dialog_content = "How unsightly...",
  ui_story_5045_50450501_61_dialog_content = "I haven't the faintest idea what they're talking about...",
  ui_story_5045_50450501_62_dialog_content = "(And now they're arguing? It looks like the others are starting to gossip amongst themselves too.)",
  ui_story_5045_50450501_63_dialog_content = "(Judging from Leyn's sigh just now, it looks like this whole thing is making his head hurt...)",
  ui_story_5045_50450501_64_dialog_content = "Do you see why no one wants to join the Romance Division now, PlayerName?",
  ui_story_5045_50450501_65_dialog_content = "When it comes to cases like this, there are rarely any existing laws or precedents to rely on.",
  ui_story_5045_50450501_66_dialog_content = "Both sides have perfectly reasonable arguments, which makes it difficult for a judge to pass a fair and unbiased verdict.",
  ui_story_5045_50450501_67_dialog_content = "But that's alright, because it serves as a kind of training for me. I swear I'll uphold justice to the very end!",
  ui_story_5045_50450501_68_dialog_content = "Now then, do you have any thoughts to share on this case?",
  ui_story_5045_50450501_69_dialog_content = "Not right now, no...",
  ui_story_5045_50450501_70_dialog_content = "W-Wait, I got it!",
  ui_story_5045_50450501_71_dialog_content = "I think we should take a closer look at things.",
  ui_story_5045_50450501_72_dialog_content = "Okay...",
  ui_story_5045_50450501_73_dialog_content = "Take a look at this, Leyn...",
  ui_story_5045_50450501_74_dialog_content = "Well, would you look at that? I have to say, seeing that <color=#1875ad>notebook</color> really brings back memories.",
  ui_story_5045_50450501_75_dialog_content = "When I was a probationary judge, I would take it with me every day.",
  ui_story_5045_50450501_76_dialog_content = "I don't think this is a good time to share stories, though.",
  ui_story_5045_50450501_77_dialog_content = "Why don't we focus on the case at hand instead?",
  ui_story_5045_50450501_78_dialog_content = "Well...",
  ui_story_5045_50450501_79_dialog_content = "Maybe we should start with that <color=#1875ad>contract</color>?",
  ui_story_5045_50450501_80_dialog_content = "A wise choice.",
  ui_story_5045_50450501_81_dialog_content = "We may never understand the feelings between the two parties.",
  ui_story_5045_50450501_82_dialog_content = "But a written agreement is subject to the full protection of Lumopolis law!",
  ui_story_5045_50450501_83_dialog_content = "Thanks for your suggestion. I think I have my answer now.",
  ui_story_5045_50450501_84_dialog_content = "What answer would that be?",
  ui_story_5045_50450501_85_dialog_content = "You'll know soon enough.",
  ui_story_5045_50450501_86_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450501_87_dialog_content = "White Night up high. It is time for the verdict!",
  ui_story_5045_50450501_88_dialog_content = "Both parties were consenting adults at the signing of this contract, and must bear responsibility for their decisions.",
  ui_story_5045_50450501_89_dialog_content = "According to the relevant laws of Lumopolis...",
  ui_story_5045_50450501_90_dialog_content = "The court hereby orders the defendant, Sophie, to honor the conditions of the agreement and marry the plaintiff, Farrell.",
  ui_story_5045_50450501_91_dialog_content = "If you do not accept this judgment, you may appeal in accordance with the provisions of the Hall of Justice.",
  ui_story_5045_50450501_92_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450501_93_dialog_content = "The trial is over!",
  ui_story_5045_50450501_94_dialog_content = "Shouldn't we ask Sophie if Farrell has broken any part of their agreement?",
  ui_story_5045_50450501_95_dialog_content = "I think you've just touched on a crucial aspect of this case, PlayerName!",
  ui_story_5045_50450501_96_dialog_content = "Sophie, you claim that the plaintiff has been monitoring your movements, as well as harassing you. Is that correct?",
  ui_story_5045_50450501_97_dialog_content = "Absolutely!",
  ui_story_5045_50450501_98_dialog_content = "Farrell often takes advantage of his status as a knight to loiter outside of my home.",
  ui_story_5045_50450501_99_dialog_content = "Despite clearly rejecting him multiple times, he refuses to leave me alone, and has even taken me to court over it!",
  ui_story_5045_50450501_100_dialog_content = "Your Honor, even though my family is lacking in both status and wealth.",
  ui_story_5045_50450501_101_dialog_content = "That doesn't mean I can be exploited by others!",
  ui_story_5045_50450501_102_dialog_content = "I have a right to love or reject whomever I choose, the same as anyone else!",
  ui_story_5045_50450501_103_dialog_content = "Isn't that why the Romance Division of the Hall of Justice was established? To protect these self-same rights?",
  ui_story_5045_50450501_104_dialog_content = "(The defendant makes an extremely valid point!)",
  ui_story_5045_50450501_105_dialog_content = "(When you think about it, that knight was kind of forcing himself on her.)",
  ui_story_5045_50450501_106_dialog_content = "I must say, Sophie, your understanding of love is quite unique. I've learned much from listening to you.",
  ui_story_5045_50450501_107_dialog_content = "You are absolutely right! The Romance Division of the Hall of Justice has a duty to defend love to the fullest extent of the law!",
  ui_story_5045_50450501_108_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450501_109_dialog_content = "White Night up high. It is time for the verdict!",
  ui_story_5045_50450501_110_dialog_content = "The contract signed between the two parties is perfectly valid.",
  ui_story_5045_50450501_111_dialog_content = "However, the plaintiff's behavior has rendered the defendant unwilling to marry him, thus violating the conditions of their agreement.",
  ui_story_5045_50450501_112_dialog_content = "The court has no choice but to impose a fine of 100 Nightium on the defendant, to be paid in full within the allotted time period.",
  ui_story_5045_50450501_113_dialog_content = "After receiving the penalty for breach of contract, the plaintiff shall no longer harass the defendant, Sophie.",
  ui_story_5045_50450501_114_dialog_content = "If you do not accept this judgment, you may appeal in accordance with the provisions of the Hall of Justice.",
  ui_story_5045_50450501_115_dialog_content = "The nerve of that commoner! How dare she tarnish the honor of a knight!",
  ui_story_5045_50450501_116_dialog_content = "Regardless, this is Judge Leyn's decision, which makes it both fair and just.",
  ui_story_5045_50450501_117_dialog_content = "Judge Leyn! You have a duty to protect our right to love too!",
  ui_story_5045_50450501_118_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450501_119_dialog_content = "The trial is over!",
  ui_story_5045_50450601_1_dialog_content = "<color=#737378>Time: 12:00 PM</color>",
  ui_story_5045_50450601_2_dialog_content = "<color=#737378>Location: Main Hall of the Lumo Hall of Justice</color>",
  ui_story_5045_50450601_3_dialog_content = "Sophie! Wait!",
  ui_story_5045_50450601_4_dialog_content = "Please stay away from me.",
  ui_story_5045_50450601_5_dialog_content = "I knew you wouldn't be willing to marry me, even if I had won in court today.",
  ui_story_5045_50450601_6_dialog_content = "But please, just give us a chance to talk things over!",
  ui_story_5045_50450601_7_dialog_content = "Save it to the court.",
  ui_story_5045_50450601_8_dialog_content = "<color=#737378>Time: 2:00 PM</color>",
  ui_story_5045_50450601_9_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50450601_10_dialog_content = "Huh? Why are you still looking over that agreement, Leyn?",
  ui_story_5045_50450601_11_dialog_content = "Tell me... Do you think I made the right decision in today's case?",
  ui_story_5045_50450601_12_dialog_content = "Well, I don't really know much about your laws and regulations.",
  ui_story_5045_50450601_13_dialog_content = "I know. When I asked you to help me, my only expectation was for you to remind me to pass fair judgment at all costs.",
  ui_story_5045_50450601_14_dialog_content = "Which is why I ask that you share your thoughts with me, if possible.",
  ui_story_5045_50450601_15_dialog_content = "I think your verdict was...",
  ui_story_5045_50450601_16_option_content = "A fair one.",
  ui_story_5045_50450601_17_dialog_content = "Thanks for the reassurance, but I can't help but feel as though something is wrong.",
  ui_story_5045_50450601_18_dialog_content = "The Romance Division's cases are never this simple.",
  ui_story_5045_50450601_19_option_content = "A little harsh.",
  ui_story_5045_50450601_20_dialog_content = "The law may have a binding effect on things like contracts, but it definitely can't tell people how to feel.",
  ui_story_5045_50450601_21_dialog_content = "Even if Sophie ends up marrying Farrell, I can't imagine their life will be a happy one.",
  ui_story_5045_50450601_22_dialog_content = "Ah! S-Sorry, Leyn! I wasn't trying to challenge your verdict or anything...",
  ui_story_5045_50450601_23_dialog_content = "There's no reason to apologize. If anything, I should thank you for your willingness to guide me through cases like this.",
  ui_story_5045_50450601_24_option_content = "I don't really have an opinion.",
  ui_story_5045_50450601_25_dialog_content = "What do you mean by that?",
  ui_story_5045_50450601_26_dialog_content = "Not having an opinion on something is the worst opinion to have.",
  ui_story_5045_50450601_27_dialog_content = "Sigh, then again, I shouldn't keep pinning all of my hopes on you. Sorry.",
  ui_story_5045_50450601_28_dialog_content = "(Leyn looks pretty disappointed in me...)",
  ui_story_5045_50450601_29_dialog_content = "(Maybe I should tell him what I really think about his verdict?)",
  ui_story_5045_50450601_30_dialog_content = "It looks like we'll just have to try even harder on this case.",
  ui_story_5045_50450601_31_dialog_content = "Let's go.",
  ui_story_5045_50450601_32_dialog_content = "Huh? Where to?",
  ui_story_5045_50450601_33_dialog_content = "Sophie submitted an appeal.",
  ui_story_5045_50450601_34_dialog_content = "She said she had more evidence to provide for her case.",
  ui_story_5045_50450601_35_dialog_content = "<color=#737378>Time: 3:00 PM</color>",
  ui_story_5045_50450601_36_dialog_content = "<color=#737378>Location: Lower Lumopolis</color>",
  ui_story_5045_50450601_37_dialog_content = "Good afternoon. Pardon, but is Sophie's home nearby?",
  ui_story_5045_50450601_38_dialog_content = "I'm sorry, but who are you again?",
  ui_story_5045_50450601_39_dialog_content = "(This person looks kind of familiar...)",
  ui_story_5045_50450601_40_dialog_content = "We're, uh...",
  ui_story_5045_50450601_41_dialog_content = "Oh no, PlayerName! Do you have anything to show him that proves our <color=#1875ad>identity</color>?",
  ui_story_5045_50450601_42_dialog_content = "Will this do?",
  ui_story_5045_50450601_43_dialog_content = "I don't think that does much to prove who we are.",
  ui_story_5045_50450601_44_dialog_content = "Oh, r-really? In that case...",
  ui_story_5045_50450601_45_dialog_content = "We're judges from the Lumopolis Hall of Justice.",
  ui_story_5045_50450601_46_dialog_content = "We're here at Sophie's invitation. She said she had more information to provide for her case.",
  ui_story_5045_50450601_47_dialog_content = "I-I had no idea I was in the presence of two judges! Please, you have to help our poor, little Sophie!",
  ui_story_5045_50450601_48_dialog_content = "You know her?",
  ui_story_5045_50450601_49_dialog_content = "Yes, sir! My name is <color=#1875ad>Karl</color>. I'm one of her neighbors.",
  ui_story_5045_50450601_50_dialog_content = "It's no secret that some knight named Farrell has been harassing her for some time now. She's positively miserable because of it.",
  ui_story_5045_50450601_51_dialog_content = "Which is why, as her neighbors, we've taken it upon ourselves to drive away any suspicious visitors.",
  ui_story_5045_50450601_52_dialog_content = "I see. That explains why you wanted proof of who we are.",
  ui_story_5045_50450601_53_dialog_content = "You said Farrell has been harassing Sophie for a long time now, yes?",
  ui_story_5045_50450601_54_dialog_content = "I know it's unbecoming of me to say this about a knight.",
  ui_story_5045_50450601_55_dialog_content = "But the man has been practically staking out her home every single day.",
  ui_story_5045_50450601_56_dialog_content = "Even after Sophie clarifies that she wants nothing to do with him, Farrell refuses to accept it.",
  ui_story_5045_50450601_57_dialog_content = "The way things are going, I can't help but fear for her safety, you know?",
  ui_story_5045_50450601_58_dialog_content = "It looks like Sophie's accusation during the trial was true after all?",
  ui_story_5045_50450601_59_dialog_content = "Does that mean my verdict was...",
  ui_story_5045_50450601_60_dialog_content = "Sophie's home is just up ahead. Let me show you the way.",
  ui_story_5045_50450601_61_dialog_content = "<color=#737378>Time: 3:20 PM</color>",
  ui_story_5045_50450601_62_dialog_content = "<color=#737378>Location: Lower Lumopolis, Sophie's Home</color>",
  ui_story_5045_50450601_63_dialog_content = "Please forgive me, Your Honor. I'm sure my humble home seems laughable to judges like yourselves.",
  ui_story_5045_50450601_64_dialog_content = "We wouldn't dream of it, Sophie. Your home is very warm and inviting, another thing I could learn from you.",
  ui_story_5045_50450601_65_dialog_content = "One of your neighbors told us that Farrell's been harassing you every single day. Is that true?",
  ui_story_5045_50450601_66_dialog_content = "Sigh.",
  ui_story_5045_50450601_67_dialog_content = "At first, he would only follow me around and loiter outside of my home.",
  ui_story_5045_50450601_68_dialog_content = "But just <color=#1875ad>this morning</color>, I noticed a strange set of <color=#1875ad>footprints</color> in my home. I'm starting to get really scared...",
  ui_story_5045_50450601_69_dialog_content = "You mean these footprints here? They do look a little weird.",
  ui_story_5045_50450601_70_dialog_content = "It seems like whoever left them really wanted you to see them. They even stepped on a piece of paper and left it lying on the ground.",
  ui_story_5045_50450601_71_dialog_content = "The heel marks from these footprints are especially clear. The pattern looks a lot like the ones left by the boots that knights usually wear.",
  ui_story_5045_50450601_72_dialog_content = "The footprints seem to start near the window...",
  ui_story_5045_50450601_73_dialog_content = "Is it possible that Farrell snuck in while Sophie wasn't looking?",
  ui_story_5045_50450601_74_dialog_content = "I can't say for sure. Are any of your belongings missing, Sophie?",
  ui_story_5045_50450601_75_dialog_content = "None at all. Which is what makes things even more terrifying!",
  ui_story_5045_50450601_76_dialog_content = "Farrell must be trying to intimidate me... And it's working. Oh, what am I supposed to do?",
  ui_story_5045_50450601_77_dialog_content = "If only I had asked you for more information during the trial.",
  ui_story_5045_50450601_78_dialog_content = "I don't blame you at all, Your Honor.",
  ui_story_5045_50450601_79_dialog_content = "There's no denying that I broke the law by breaking my contract with Farrell. So please, just send me to prison!",
  ui_story_5045_50450601_80_dialog_content = "At the very least, I wouldn't have to marry some manipulative stalker there...",
  ui_story_5045_50450601_81_dialog_content = "Put your mind at ease, Sophie.",
  ui_story_5045_50450601_82_dialog_content = "Now that we have more than enough reason to suspect Farrell of foul play, we will re-examine today's case with all due diligence.",
  ui_story_5045_50450601_83_dialog_content = "Would it be okay if we took a look around, Sophie?",
  ui_story_5045_50450601_84_dialog_content = "By all means, I just hope you don't mind the mess...",
  ui_story_5045_50450601_85_dialog_content = "Ahem, I think investigating Sophie's home would cause her unnecessary discomfort, don't you?",
  ui_story_5045_50450601_86_dialog_content = "S-Sorry! That didn't even occur to me... You're pretty good at knowing how other people feel, Leyn!",
  ui_story_5045_50450601_87_dialog_content = "But still, we came all the way here... Farrell might have left more clues lying around.",
  ui_story_5045_50450601_88_dialog_content = "If anyone asks, just tell them it was my idea, okay?",
  ui_story_5045_50450601_89_dialog_content = "How could I possibly let you shoulder all of the blame?",
  ui_story_5045_50450601_90_dialog_content = "When we're finished here, I'll be sure to apologize to Sophie on your behalf.",
  ui_story_5045_50450601_91_dialog_content = "Haha...",
  ui_story_5045_50450601_92_dialog_content = "Ah! Sorry, I didn't mean to eavesdrop!",
  ui_story_5045_50450601_93_dialog_content = "But the way you two keep trying to take the blame for each other. You must be very good friends.",
  ui_story_5045_50450601_94_dialog_content = "Please investigate however you see fit. I could never take offense, when the two of you are working so hard to help me.",
  ui_story_5045_50450601_95_dialog_content = "... Thank you for your understanding.",
  ui_story_5045_50450601_96_dialog_content = "Now then, where should we start our <color=#1875ad>investigation</color>?",
  ui_story_5045_50450601_97_dialog_content = "Let me think...",
  ui_story_5045_50450601_98_option_content = "Check the drawers",
  ui_story_5045_50450601_99_dialog_content = "There are a bunch of fancy-looking letters in here.",
  ui_story_5045_50450601_100_dialog_content = "Those are no ordinary letters.",
  ui_story_5045_50450601_101_dialog_content = "What makes you say that?",
  ui_story_5045_50450601_102_dialog_content = "Because I've got plenty of them myself...",
  ui_story_5045_50450601_103_dialog_content = "You too? Wait... I get it now! These are love letters, aren't they?",
  ui_story_5045_50450601_104_dialog_content = "The handwriting and signature on each one are different, though.",
  ui_story_5045_50450601_105_dialog_content = "It seems Sophie is quite popular as well. But we have no business reading her private letters.",
  ui_story_5045_50450601_106_dialog_content = "Let's try looking somewhere else.",
  ui_story_5045_50450601_106X1_dialog_content = "Where else should I investigate?",
  ui_story_5045_50450601_107_option_content = "Check the ground",
  ui_story_5045_50450601_108_dialog_content = "I don't see any other footprints aside from the ones near the window.",
  ui_story_5045_50450601_109_dialog_content = "Wait, what's this?",
  ui_story_5045_50450601_110_dialog_content = "It's a card? It looks like some sort of <color=#1875ad>attendance card</color>.",
  ui_story_5045_50450601_111_dialog_content = "Oh, yes. I started taking some housekeeping lessons recently.",
  ui_story_5045_50450601_112_dialog_content = "That's my attendance card for the course.",
  ui_story_5045_50450601_113_dialog_content = "With both of my parents died, I have no way to rebuild our family business. But that doesn't mean I want to sit idly and do nothing about it!",
  ui_story_5045_50450601_114_dialog_content = "I want to work hard and rely on my own skills to make a living.",
  ui_story_5045_50450601_115_dialog_content = "I... I'm positive you'll succeed!",
  ui_story_5045_50450601_116_option_content = "Wrap it up",
  ui_story_5045_50450601_117_dialog_content = "There doesn't seem to be anything else here, aside from those footprints.",
  ui_story_5045_50450601_118_dialog_content = "So he didn't take anything with him, or leave anything behind.",
  ui_story_5045_50450601_119_dialog_content = "What exactly is Farrell up to?",
  ui_story_5045_50450601_120_dialog_content = "<color=#737378>Time: 5:00 PM</color>",
  ui_story_5045_50450601_121_dialog_content = "<color=#737378>Location: Lumopolis Guard Station</color>",
  ui_story_5045_50450601_122_dialog_content = "Th-This place is terrifying... Is this really where Farrell works?",
  ui_story_5045_50450601_123_dialog_content = "Of course it's terrifying. Only the most fearless of nobles are worthy of working here.",
  ui_story_5045_50450601_124_dialog_content = "B-Beverly?!",
  ui_story_5045_50450601_125_dialog_content = "Farrell is out on duty right now. If you wish to see him, you'll have to come back another day.",
  ui_story_5045_50450601_126_dialog_content = "Pardon the intrusion, Lady Duchess, but we're here on an investigation.",
  ui_story_5045_50450601_127_dialog_content = "From what I understand, Farrell is one of your colleagues here, yes?",
  ui_story_5045_50450601_128_dialog_content = "Indeed, he is. But I thought his case had already been settled?",
  ui_story_5045_50450601_129_dialog_content = "The defendant submitted an appeal, which requires us to re-examine the case.",
  ui_story_5045_50450601_130_dialog_content = "Hmph. Is that so?",
  ui_story_5045_50450601_131_dialog_content = "Then you would do well to examine things more carefully this time. Ever since he met that Sophie, Farrell has become an entirely different man.",
  ui_story_5045_50450601_132_dialog_content = "He keeps sputtering on about losing his honor as a knight if he fails to rescue his princess.",
  ui_story_5045_50450601_133_dialog_content = "While it hasn't presented any complications in his work, I find the whole thing unbearably annoying.",
  ui_story_5045_50450601_134_dialog_content = "A true knight must serve the people with all their heart. But I fear his heart is already spoken for.",
  ui_story_5045_50450601_135_dialog_content = "I hear he moved into these barracks recently. Is that true?",
  ui_story_5045_50450601_136_dialog_content = "It is. Not long ago, he donated all of his wealth and assets to the impoverished of Umbraton.",
  ui_story_5045_50450601_137_dialog_content = "He's been living here ever since.",
  ui_story_5045_50450601_138_dialog_content = "His selflessness is something to be commended, to be sure. But what does this have to do with his case?",
  ui_story_5045_50450601_139_dialog_content = "A-All of his assets?!",
  ui_story_5045_50450601_140_dialog_content = "Could you please show us to Farrell's quarters?",
  ui_story_5045_50450601_141_dialog_content = "His quarters are just to the left of here. You may see yourselves in.",
  ui_story_5045_50450601_142_dialog_content = "<color=#737378>Some time later</color>",
  ui_story_5045_50450601_143_dialog_content = "Well? Find anything yet?",
  ui_story_5045_50450601_144_dialog_content = "The size and shape of the footprints are a perfect match with the boot print Farrell left in the house.",
  ui_story_5045_50450601_145_dialog_content = "So the person who broke into Sophie's house really was Farrell...",
  ui_story_5045_50450601_146_dialog_content = "What about you, PlayerName? Any discoveries?",
  ui_story_5045_50450601_147_dialog_content = "Aside from this, I don't see anything particularly out of place in his room.",
  ui_story_5045_50450601_148_dialog_content = "Is this... a<color=#1875ad> kite</color>?",
  ui_story_5045_50450601_149_dialog_content = "And look, it has Sophie's name written on it!",
  ui_story_5045_50450601_150_dialog_content = "Does this mean that Farrell did take something from her home? Why didn't she tell us about it?",
  ui_story_5045_50450601_151_dialog_content = "Maybe it isn't worth very much?",
  ui_story_5045_50450601_152_dialog_content = "All of the evidence we've gathered thus far seems to point to Farrell as the person at fault.",
  ui_story_5045_50450601_153_dialog_content = "If this is the case, not only will Farrell lose the case. He will be faced with even more severe punishment.",
  ui_story_5045_50450601_154_dialog_content = "What kind of punishment?",
  ui_story_5045_50450601_155_dialog_content = "He will lose his status as a knight, and be forced to live as a commoner.",
  ui_story_5045_50450601_156_dialog_content = "For the nobility, this is one of the worst punishments a person of their status could be given.",
  ui_story_5045_50450601_157_dialog_content = "I see... But something tells me there's more to this case than we realize.",
  ui_story_5045_50450601_158_dialog_content = "My thoughts exactly.",
  ui_story_5045_50450601_159_dialog_content = "We can't afford to skip over a single detail of tomorrow's trial.",
  ui_story_5045_50450701_1_dialog_content = "<color=#737378>Time: 9:00 AM</color>",
  ui_story_5045_50450701_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Courtroom</color>",
  ui_story_5045_50450701_3_dialog_content = "Wow! Leyn looks as handsome as ever today, don't you think?",
  ui_story_5045_50450701_4_dialog_content = "(Looks like Leyn's fan club is back again...)",
  ui_story_5045_50450701_5_dialog_content = "What's on your mind, PlayerName?",
  ui_story_5045_50450701_6_dialog_content = "Nothing, just...",
  ui_story_5045_50450701_7_option_content = "You look as handsome as ever today, Leyn!",
  ui_story_5045_50450701_8_dialog_content = "(Crap, I repeated that girl's words without thinking...)",
  ui_story_5045_50450701_9_dialog_content = "A-Ahem... The court will be in session soon, so please try to focus.",
  ui_story_5045_50450701_10_option_content = "Remember to make a fair judgment!",
  ui_story_5045_50450701_11_dialog_content = "I will. Thank you for reminding me.",
  ui_story_5045_50450701_12_dialog_content = "I learned my lesson from the last trial. I won't show any indecision today.",
  ui_story_5045_50450701_13_option_content = "I wish I was as popular as you...",
  ui_story_5045_50450701_14_dialog_content = "Really? I always thought you had greater ambitions than that...",
  ui_story_5045_50450701_15_dialog_content = "But now's not the time for that kind of talk! Court will be in session soon!",
  ui_story_5045_50450701_16_dialog_content = "(And here I thought Leyn would feel better if I gave him a little compliment...)",
  ui_story_5045_50450701_17_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450701_18_dialog_content = "<size=45>White Night up high. Court is now in session!</size>",
  ui_story_5045_50450701_19_dialog_content = "To begin, will the appellant, Sophie, please state her case?",
  ui_story_5045_50450701_20_dialog_content = "Good day, Your Honor. I can't accept the first instance verdict.",
  ui_story_5045_50450701_21_dialog_content = "I appeal to rescind the agreement between Farrell and me.",
  ui_story_5045_50450701_22_dialog_content = "As a knight, he used his position to stalk and harass me.",
  ui_story_5045_50450701_23_dialog_content = "He even broke into my house <color=#1875ad>after the first trial</color> and left his footprints there!",
  ui_story_5045_50450701_24_dialog_content = "Something's wrong with Sophie's statement!",
  ui_story_5045_50450701_25_dialog_content = "What's the problem?",
  ui_story_5045_50450701_26_dialog_content = "Huh? No problem?",
  ui_story_5045_50450701_26X1_dialog_content = "Are you sure you didn't mishear me? Let me say it once more...",
  ui_story_5045_50450701_27_dialog_content = "Take a look at this, Leyn...",
  ui_story_5045_50450701_28_dialog_content = "Well, would you look at that? I have to say, seeing that notebook really brings back memories.",
  ui_story_5045_50450701_29_dialog_content = "When I was a probationary judge, I would take it with me every day.",
  ui_story_5045_50450701_30_dialog_content = "Why does this conversation seem so familiar?",
  ui_story_5045_50450701_31_dialog_content = "Just what are you trying to say?",
  ui_story_5045_50450701_32_dialog_content = "I-I'm thinking...",
  ui_story_5045_50450701_33_dialog_content = "Sophie, you said you found these footprints on <color=#1875ad>the morning of the first trial</color>?",
  ui_story_5045_50450701_34_dialog_content = "Oh... I-I must've been mistaken.",
  ui_story_5045_50450701_35_dialog_content = "Your Honor, I was really nervous just now... Let me say that again!",
  ui_story_5045_50450701_36_dialog_content = "On the morning of the first trial, I found these footprints at my home.",
  ui_story_5045_50450701_37_dialog_content = "But nothing was stolen... I knew it must have been a deliberate attempt to break into my house and frighten me!",
  ui_story_5045_50450701_38_dialog_content = "Nothing was stolen? But...",
  ui_story_5045_50450701_39_dialog_content = "I think I remember that Farrell had <color=#1875ad>something that was yours</color>!",
  ui_story_5045_50450701_40_dialog_content = "Is there anything wrong here?",
  ui_story_5045_50450701_41_dialog_content = "Ah, that's not it! What I wanted to say was...",
  ui_story_5045_50450701_42_dialog_content = "This <color=#1875ad>kite</color> has Sophie's signature on it. It must belong to you, right?",
  ui_story_5045_50450701_43_dialog_content = "This is...",
  ui_story_5045_50450701_44_dialog_content = "Your Honor, this is a token of our love!",
  ui_story_5045_50450701_45_dialog_content = "At that time, I had just finished patrolling...",
  ui_story_5045_50450701_46_dialog_content = "(Erm, is he going to fall in love all over again right here in the Hall of Justice?)",
  ui_story_5045_50450701_47_dialog_content = "Sir...",
  ui_story_5045_50450701_48_dialog_content = "Yes, what can I do to help?",
  ui_story_5045_50450701_49_dialog_content = "M-My kite is stuck in that tree over there. I know I shouldn't trouble you...",
  ui_story_5045_50450701_50_dialog_content = "But that kite is very important to me. It was made by my father...",
  ui_story_5045_50450701_51_dialog_content = "It's no trouble at all. Please wait a moment.",
  ui_story_5045_50450701_52_dialog_content = "Thank you so much! I really don't know what to do if it weren't for you...",
  ui_story_5045_50450701_53_dialog_content = "It's all in a day's work. Please, don't mention it.",
  ui_story_5045_50450701_54_dialog_content = "Erm... Do you like flying kites?",
  ui_story_5045_50450701_55_dialog_content = "And so, we met from time to time to fly kites together, and gradually became closely acquainted with one another.",
  ui_story_5045_50450701_56_dialog_content = "It was at that time that my family wished to choose a suitable wife for me.",
  ui_story_5045_50450701_57_dialog_content = "But I believe that love is born from freedom, and I didn't want to be controlled by my family.",
  ui_story_5045_50450701_58_dialog_content = "So I turned my back on my family and proposed to Sophie.",
  ui_story_5045_50450701_59_dialog_content = "Farrell, our kites are flying so high!",
  ui_story_5045_50450701_60_dialog_content = "No matter how high a kite flies, it must return to the ground after the wind stops.",
  ui_story_5045_50450701_61_dialog_content = "Like no matter how far we travel in the wide world, we must finally return to a warm, loving family.",
  ui_story_5045_50450701_62_dialog_content = "I'm not sure I understand.",
  ui_story_5045_50450701_63_dialog_content = "Sophie, would you like to build a happy family with me?",
  ui_story_5045_50450701_64_dialog_content = "I... I appreciate your kindly feelings.",
  ui_story_5045_50450701_65_dialog_content = "But will your family accept someone in a position as low as mine?",
  ui_story_5045_50450701_66_dialog_content = "Sophie, don't worry. I will make them accept you.",
  ui_story_5045_50450701_67_dialog_content = "If you fall out with your family because of me, I won't be able to forgive myself...",
  ui_story_5045_50450701_68_dialog_content = "I promise to marry you, but please wait until the time is ripe.",
  ui_story_5045_50450701_69_dialog_content = "I want to restore my family's honor...",
  ui_story_5045_50450701_70_dialog_content = "Your family may accept me once I recover my family's property.",
  ui_story_5045_50450701_71_dialog_content = "That's why you signed the betrothal agreement!",
  ui_story_5045_50450701_72_dialog_content = "Objection! These past events have nothing to do with today's case.",
  ui_story_5045_50450701_73_dialog_content = "Although it is a little embarrassing, having to sit through someone else's love story...",
  ui_story_5045_50450701_74_dialog_content = "I assure you that this is all related to the case!",
  ui_story_5045_50450701_75_dialog_content = "Overruled!",
  ui_story_5045_50450701_76_dialog_content = "Your Honor, I admit that we had a good relationship, but that is over now.",
  ui_story_5045_50450701_77_dialog_content = "I broke up with him a long time ago.",
  ui_story_5045_50450701_78_dialog_content = "We have the freedom to love, and the freedom not to love.",
  ui_story_5045_50450701_79_dialog_content = "You can't force someone to give up their life's happiness because of what it says on a piece of paper!",
  ui_story_5045_50450701_80_dialog_content = "Yes, what the appellant says is quite reasonable.",
  ui_story_5045_50450701_81_dialog_content = "But after we broke up, Farrell still harassed me and often followed me...",
  ui_story_5045_50450701_82_dialog_content = "He even broke into my house!",
  ui_story_5045_50450701_83_dialog_content = "Hmm... Why is Sophie so sure that those footprints are Farrell's?",
  ui_story_5045_50450701_84_dialog_content = "It's because Farrell harassed Sophie that she subconsciously believes they're his, right?",
  ui_story_5045_50450701_85_dialog_content = "But... this is just a guess. Let's ask the client.",
  ui_story_5045_50450701_86_dialog_content = "Farrell, do you admit to Sophie's accusation?",
  ui_story_5045_50450701_87_dialog_content = "I...",
  ui_story_5045_50450701_88_dialog_content = "I admit that sometimes I would look for Sophie after my patrol, but I just wanted to ask her to give me another chance.",
  ui_story_5045_50450701_89_dialog_content = "White Night up high. I swear on my honor as a knight that I did not do anything untoward to Sophie.",
  ui_story_5045_50450701_90_dialog_content = "Sophie, did someone break into your room?",
  ui_story_5045_50450701_91_dialog_content = "It's all my fault. I should have been there to protect you...",
  ui_story_5045_50450701_92_dialog_content = "It seems he won't admit to the footprints being his.",
  ui_story_5045_50450701_93_dialog_content = "If only there were some way to identify the footprints...",
  ui_story_5045_50450701_94_dialog_content = "... That's it! Let's compare the footprints in court!",
  ui_story_5045_50450701_95_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450701_96_dialog_content = "Farrell, please make a footprint on this paper.",
  ui_story_5045_50450701_97_dialog_content = "O-Okay...",
  ui_story_5045_50450701_98_dialog_content = "Can you see any difference, PlayerName?",
  ui_story_5045_50450701_99_dialog_content = "The marks left by the hard soles and heels are roughly the same in depth.",
  ui_story_5045_50450701_100_dialog_content = "And there are many tears along the edges of the soles. It seems that these boots have been worn for many years.",
  ui_story_5045_50450701_101_dialog_content = "But the <color=#1875ad>footprints</color> we found that day were...",
  ui_story_5045_50450701_102_dialog_content = "Is there any problem with this?",
  ui_story_5045_50450701_103_dialog_content = "Cough, cough, I've made a mistake!",
  ui_story_5045_50450701_104_dialog_content = "The footprints from Sophie's house had a very clear pattern—a pattern obviously made by new shoes, but Farrell's shoes are old and tattered.",
  ui_story_5045_50450701_105_dialog_content = "The two footprints are blatantly different.",
  ui_story_5045_50450701_106_dialog_content = "What!?",
  ui_story_5045_50450701_107_dialog_content = "No! Maybe he was wearing a new pair of shoes that day.",
  ui_story_5045_50450701_108_dialog_content = "Well, that's not an impossibility.",
  ui_story_5045_50450701_109_dialog_content = "Your Honor, I only have these boots now...",
  ui_story_5045_50450701_110_dialog_content = "Who knows? Maybe you hid the boots from that day somewhere no one will ever find them?",
  ui_story_5045_50450701_111_dialog_content = "No... The person who broke into Sophie's house was not Farrell!",
  ui_story_5045_50450701_112_dialog_content = "And what brings you so firmly to that conclusion, PlayerName?",
  ui_story_5045_50450701_113_dialog_content = "The footprints found at Sophie's house... The tracks left by the heel are very distinct.",
  ui_story_5045_50450701_114_dialog_content = "Such footprints only occur when wearing shoes that are much larger than your own feet.",
  ui_story_5045_50450701_115_dialog_content = "Therefore, the footprints at Sophie's house couldn't have belonged to Farrell.",
  ui_story_5045_50450701_116_dialog_content = "Your powers of observation are eerily astute!",
  ui_story_5045_50450701_117_dialog_content = "So, who would deliberately wear boots larger than their own feet in order to leave footprints at Sophie's home?",
  ui_story_5045_50450701_118_dialog_content = "Well...",
  ui_story_5045_50450701_119_dialog_content = "Sophie, did you make this evidence yourself?",
  ui_story_5045_50450701_120_dialog_content = "Uh, I...",
  ui_story_5045_50450701_121_dialog_content = "White Night up high! This is the Hall of Justice, you're obligated to tell the truth!",
  ui_story_5045_50450701_122_dialog_content = "I was afraid that you would still uphold the original judgment, so I made a decision of my own.",
  ui_story_5045_50450701_123_dialog_content = "I made a mistake, Your Honor, but I really don't want to marry Farrell!",
  ui_story_5045_50450701_124_dialog_content = "Is it because Farrell doesn't have a penny to his name?",
  ui_story_5045_50450701_125_dialog_content = "...",
  ui_story_5045_50450701_126_dialog_content = "Although it was not explicitly stated, your agreement mentioned that if you had enough money, you would get married.",
  ui_story_5045_50450701_127_dialog_content = "But now...",
  ui_story_5045_50450701_128_dialog_content = "<color=#1875ad>The condition of Farrell's property</color> has undergone a significant change.",
  ui_story_5045_50450701_129_dialog_content = "What's that?",
  ui_story_5045_50450701_130_dialog_content = "Oh, what I actually wanted to say was...",
  ui_story_5045_50450701_131_dialog_content = "Farrell, can you tell us why you wanted to give away all of your property?",
  ui_story_5045_50450701_132_dialog_content = "Th-This is my responsibility as a knight.",
  ui_story_5045_50450701_133_dialog_content = "Is that really true?",
  ui_story_5045_50450701_134_dialog_content = "White Night up high! Farrell, you should know that honesty is the most basic quality of any knight.",
  ui_story_5045_50450701_135_dialog_content = "Well...",
  ui_story_5045_50450701_136_dialog_content = "Alright, I'll talk.",
  ui_story_5045_50450701_137_dialog_content = "Sorry, that last investment was another lame duck...",
  ui_story_5045_50450701_138_dialog_content = "But this time will be different!",
  ui_story_5045_50450701_139_dialog_content = "Farrell, can you lend me some more money? I know I'll pick a winner this time!",
  ui_story_5045_50450701_140_dialog_content = "Sophie, I have some good news.",
  ui_story_5045_50450701_141_dialog_content = "I've given away all my properties.",
  ui_story_5045_50450701_142_dialog_content = "But... why would you do something like that?",
  ui_story_5045_50450701_143_dialog_content = "This way, we'll be financially equal.",
  ui_story_5045_50450701_144_dialog_content = "We can get married.",
  ui_story_5045_50450701_145_dialog_content = "Sophie tried for the longest time, but she couldn't get her family's property back.",
  ui_story_5045_50450701_146_dialog_content = "I didn't want her to work so hard.",
  ui_story_5045_50450701_147_dialog_content = "Money and property are superficial things. The love between the two of us is more important than anything in the world!",
  ui_story_5045_50450701_148_dialog_content = "Obviously, Sophie doesn't agree with you on that.",
  ui_story_5045_50450701_149_dialog_content = "... Right, I don't think she does.",
  ui_story_5045_50450701_150_dialog_content = "I believe money to be the prerequisite for building a family.",
  ui_story_5045_50450701_151_dialog_content = "I could never agree with Farrell's approach, which shows that we're clearly incompatible—so I broke up with him.",
  ui_story_5045_50450701_152_dialog_content = "Is there anything wrong with that?",
  ui_story_5045_50450701_153_dialog_content = "After we get married, we can work hard together and slowly build up our own wealth!",
  ui_story_5045_50450701_154_dialog_content = "But I don't love you anymore.",
  ui_story_5045_50450701_155_dialog_content = "Or rather, I didn't love you from the beginning.",
  ui_story_5045_50450701_156_dialog_content = "Are you satisfied now?",
  ui_story_5045_50450701_157_dialog_content = "Sophie... No... It's not true!",
  ui_story_5045_50450701_158_dialog_content = "Poor Farrell...",
  ui_story_5045_50450701_159_dialog_content = "Leyn, how do we deal with this?",
  ui_story_5045_50450701_160_dialog_content = "I always thought cases could be judged based on the law alone.",
  ui_story_5045_50450701_161_dialog_content = "But things are different in Romance Division...",
  ui_story_5045_50450701_162_dialog_content = "After all, emotions can't be explained and understood so easily.",
  ui_story_5045_50450701_163_dialog_content = "If it goes on like this, they'll both end up with nothing but misery and regret.",
  ui_story_5045_50450701_164_dialog_content = "I hope our judgment can protect both of them at the same time.",
  ui_story_5045_50450701_165_dialog_content = "Does that mean you have an idea?",
  ui_story_5045_50450701_166_dialog_content = "Yes.",
  ui_story_5045_50450701_167_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450701_168_dialog_content = "White Night up high. It is time for the verdict!",
  ui_story_5045_50450701_169_dialog_content = "Firstly, although the betrothal agreement between Farrell and Sophie is legal and effective...",
  ui_story_5045_50450701_170_dialog_content = "However, the retrial finds that the differences between Sophie and Farrell are irreconcilable.",
  ui_story_5045_50450701_171_dialog_content = "Secondly, Sophie's accusation against Farrell is untrue. Specifically, Farrell did not follow Sophie to her home and entered her property illegally.",
  ui_story_5045_50450701_172_dialog_content = "But his wistful, unilateral love does not make a marriage.",
  ui_story_5045_50450701_173_dialog_content = "Therefore, we have come to the following judgment!",
  ui_story_5045_50450701_174_dialog_content = "Sophie must provide Farrell with a public apology...",
  ui_story_5045_50450701_175_dialog_content = "... clarifying the reasons for canceling the engagement and the false accusations of Farrell's illegal intrusion.",
  ui_story_5045_50450701_176_dialog_content = "After the trial, Farrell must not contact Sophie in private—the Guard will enforce its own internal monitoring to this effect.",
  ui_story_5045_50450701_177_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50450701_178_dialog_content = "The trial is over!",
  ui_story_5045_50450801_1_dialog_content = "<color=#737378>Time: 12:00 PM</color>",
  ui_story_5045_50450801_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Courtroom</color>",
  ui_story_5045_50450801_3_dialog_content = "Your Honor, can you help me give this to Sophie?",
  ui_story_5045_50450801_4_dialog_content = "I thought Sophie and I would fly kites together again...",
  ui_story_5045_50450801_5_dialog_content = "Now it looks like it'll never happen... Not in this life.",
  ui_story_5045_50450801_6_dialog_content = "Although I‘m tempted to keep it as a memento...",
  ui_story_5045_50450801_7_dialog_content = "It was made by Sophie's late father, so I think she might need it more than I do.",
  ui_story_5045_50450801_8_dialog_content = "Please rest assured, we'll deliver it to Sophie.",
  ui_story_5045_50450801_9_dialog_content = "You'll meet someone who really loves you one day!",
  ui_story_5045_50450801_10_dialog_content = "Please tell Sophie that I'll wait for her.",
  ui_story_5045_50450801_11_dialog_content = "... I think you deserve a good rest.",
  ui_story_5045_50450801_12_dialog_content = "Sigh...",
  ui_story_5045_50450801_13_dialog_content = "Sophie, please wait!",
  ui_story_5045_50450801_14_dialog_content = "Is something the matter?",
  ui_story_5045_50450801_15_dialog_content = "Farrell asked us to return this kite to you.",
  ui_story_5045_50450801_16_dialog_content = "I don't need it anymore. Just throw it away.",
  ui_story_5045_50450801_17_dialog_content = "Wasn't it made by your father?",
  ui_story_5045_50450801_18_dialog_content = "... That old man made a lot of kites. I don't want this one anymore.",
  ui_story_5045_50450801_19_dialog_content = "Must you really concern yourself with such a trifling matter, Your Honor?",
  ui_story_5045_50450801_20_dialog_content = "Well...",
  ui_story_5045_50450801_21_dialog_content = "I have one last question to ask you, Sophie.",
  ui_story_5045_50450801_22_dialog_content = "I have nothing to say about this.",
  ui_story_5045_50450801_23_dialog_content = "Have you ever deceived others emotionally?",
  ui_story_5045_50450801_24_dialog_content = "How can you use the word \"deceived\" to describe the relationships I had with them?",
  ui_story_5045_50450801_25_dialog_content = "If we ask the Hall of Justice to investigate your interpersonal relationships more thoroughly...",
  ui_story_5045_50450801_26_dialog_content = "We may find that you're not as harmless as you seem.",
  ui_story_5045_50450801_27_dialog_content = "... No one is pressing charges against me—you have no right to do that!",
  ui_story_5045_50450801_28_dialog_content = "Indeed, no one is pressing charges against you.",
  ui_story_5045_50450801_29_dialog_content = "Because your targets are the nobles.",
  ui_story_5045_50450801_30_dialog_content = "Even if they are deceived, they wouldn't want anyone else to know about it.",
  ui_story_5045_50450801_31_dialog_content = "This time, you encountered a lot of unexpected bother, namely, he was wholeheartedly genuine with you.",
  ui_story_5045_50450801_32_dialog_content = "And somehow you didn't want to tell him the truth.",
  ui_story_5045_50450801_33_dialog_content = "And then, when Farrell literally gave up everything for you...",
  ui_story_5045_50450801_34_dialog_content = "Enough!",
  ui_story_5045_50450801_35_dialog_content = "I've already wasted too much time here. Sorry, I have to go.",
  ui_story_5045_50450801_36_dialog_content = "She ran off... Just like that.",
  ui_story_5045_50450801_37_dialog_content = "We promised Farrell we'd hand over the kite...",
  ui_story_5045_50450801_38_dialog_content = "Cases here certainly aren't exactly clear-cut...",
  ui_story_5045_50450801_39_dialog_content = "Even though judgment has been passed, my soul toils in restless torment.",
  ui_story_5045_50450801_40_dialog_content = "Yeah, I feel like... there's this indescribable weight dragging down my heart.",
  ui_story_5045_50450801_41_option_content = "I hope Farrell doesn't mind too much.",
  ui_story_5045_50450801_42_dialog_content = "We did all we could, and the law has no answers to the questions that remain.",
  ui_story_5045_50450801_43_dialog_content = "Argh, just forget about it. Let's hurry back!",
  ui_story_5045_50450801_44_dialog_content = "You're right. We'd better hurry along and start the next case!",
  ui_story_5045_50450801_45_dialog_content = "Maybe we'll be able to solve any case smoothly if we have a higher <color=#1875ad>Rapport</color>!",
  ui_story_5045_50450801_46_dialog_content = "What!?",
  ui_story_5045_50450801_47_dialog_content = "I just...",
  ui_story_5045_50450801_48_dialog_content = "I just wanted to go back and have a rest!",
  ui_story_5045_50450801_49_option_content = "You did the best you could!",
  ui_story_5045_50450801_50_dialog_content = "I think this is the best result we could hope for.",
  ui_story_5045_50450801_51_dialog_content = "Let's hope so.",
  ui_story_5045_50450801_52_dialog_content = "Anyway, let's take this opportunity to walk around.",
  ui_story_5045_50450801_53_dialog_content = "A little exercise might make you feel better.",
  ui_story_5045_50450801_54_dialog_content = "If you say so.",
  ui_story_5045_50450801_55_dialog_content = "Today's weather is really...",
  ui_story_5045_50450801_56_dialog_content = "<color=#737378>Whoosh—</color>",
  ui_story_5045_50450801_57_dialog_content = "The wind is so strong! It almost blew me away.",
  ui_story_5045_50450801_58_dialog_content = "The kite I was holding just now... Where did that kite go?",
  ui_story_5045_50450801_59_dialog_content = "Over there!",
  ui_story_5045_50450801_60_dialog_content = "<color=#737378>Whoosh—</color>",
  ui_story_5045_50450801_61_dialog_content = "(Leyn?)",
  ui_story_5045_50450801_62_dialog_content = "(How did he fly up into the sky and grab that kite!?)",
  ui_story_5045_50450801_63_dialog_content = "(Wait...)",
  ui_story_5045_50450801_64_dialog_content = "(Why do I feel like I've seen this whole scenario play out before?)",
  ui_story_5045_50450801_65_dialog_content = "(I remember now!)",
  ui_story_5045_50450801_66_dialog_content = "(It's because of Farrell, he met Sophie because he...)",
  ui_story_5045_50450801_67_dialog_content = "It seems like this kite really likes to run away from its masters.",
  ui_story_5045_50450801_68_dialog_content = "Or do all kites simply wish to pursue freedom in the wind?",
  ui_story_5045_50450801_69_dialog_content = "(It's true that a kite can fly into the blue sky because of the wind that raises it up.)",
  ui_story_5045_50450801_70_dialog_content = "(But why do we have to restrict its freedom with a silken thread?)",
  ui_story_5045_50450801_71_dialog_content = "PlayerName, I know what you're thinking.",
  ui_story_5045_50450801_72_dialog_content = "But I believe that freedom without restraint is not real freedom at all.",
  ui_story_5045_50450801_73_dialog_content = "If the kite lacks the support of the thread, it will soon be blown into the barren wilderness by the merciless wind.",
  ui_story_5045_50450801_74_dialog_content = "The recent upsurge in free love in Lumopolis is like the kite's desire for the sky.",
  ui_story_5045_50450801_75_dialog_content = "If there's no thread—the thread of justice...",
  ui_story_5045_50450801_76_dialog_content = "Neither the freedom to love nor the freedom not to love can be guaranteed.",
  ui_story_5045_50450801_77_dialog_content = "I've gotta hand it to you...",
  ui_story_5045_50450801_78_dialog_content = "From just a simple rogue kite flying through the sky, you've managed to unravel the mysteries of life, love, and liberty.",
  ui_story_5045_50450801_79_dialog_content = "Ah! My apologies.",
  ui_story_5045_50450801_80_dialog_content = "Please pay no heed to my nonsense!",
  ui_story_5045_50450801_81_dialog_content = "It's just that, after this recent trial, I think I understand how to go forward trying other Romance Division cases.",
  ui_story_5045_50450801_82_dialog_content = "Of course, I owe it all to your help.",
  ui_story_5045_50450801_83_option_content = "Don't mention it!",
  ui_story_5045_50450801_84_dialog_content = "In fact, you did most of the work yourself.",
  ui_story_5045_50450801_85_dialog_content = "I just put forward a few unprofessional suggestions from the periphery.",
  ui_story_5045_50450801_86_dialog_content = "You're too modest.",
  ui_story_5045_50450801_87_dialog_content = "If it wasn't for your suggestion, who knows when I would have finished that first case.",
  ui_story_5045_50450801_88_option_content = "It seems like there's something on your mind?",
  ui_story_5045_50450801_89_dialog_content = "Needless to say, nothing gets past you, PlayerName.",
  ui_story_5045_50450801_90_dialog_content = "To be honest, I've been thinking... if only there were no love in the world.",
  ui_story_5045_50450801_91_dialog_content = "Huh? You don't want to work in the Romance Division?",
  ui_story_5045_50450801_92_dialog_content = "No, no, I cherish my current position.",
  ui_story_5045_50450801_93_dialog_content = "I just feel more and more as though love is like poison.",
  ui_story_5045_50450801_94_dialog_content = "It can make an upright knight suddenly become so humble...",
  ui_story_5045_50450801_95_dialog_content = "Love is really hard to understand, but we can't let these cases get to us.",
  ui_story_5045_50450801_96_dialog_content = "There must be many cases of truly wonderful love in the world.",
  ui_story_5045_50450801_97_dialog_content = "The reason you haven't seen them is that all these happy lovers would never end up in the Hall of Justice.",
  ui_story_5045_50450801_98_dialog_content = "Truly wonderful love? I wonder what that would feel like?",
  ui_story_5045_50450801_99_dialog_content = "Two people appreciate each other, trust each other, and bettering themselves for each other.",
  ui_story_5045_50450801_100_dialog_content = "That is what I consider to be a truly wonderful love.",
  ui_story_5045_50450801_101_dialog_content = "Right...",
  ui_story_5045_50450801_102_dialog_content = "What's got you in this philosophical mood, all of a sudden?",
  ui_story_5045_50450801_103_dialog_content = "Your words reminded me of someone.",
  ui_story_5045_50450801_104_dialog_content = "Who? Do I know them?",
  ui_story_5045_50450801_105_dialog_content = "It's you, PlayerName.",
  ui_story_5045_50450801_106_dialog_content = "What!?",
  ui_story_5045_50450801_107_dialog_content = "It turns out the love between lovers is so similar to the friendship between allies?",
  ui_story_5045_50450801_108_dialog_content = "That's actually quite true... Hahaha...",
  ui_story_5045_50450801_109_dialog_content = "In such case I wish everyone all the best in matters of the heart.",
  ui_story_5045_50450801_110_dialog_content = "White Night up high, I hope that everyone's love can remain happy for a long, long time.",
  ui_story_5045_50450801_111_dialog_content = "But what are we going to do about this kite, now?",
  ui_story_5045_50450801_112_dialog_content = "For now, let's take care of it on their behalf.",
  ui_story_5045_50450801_113_dialog_content = "<color=#737378>Whoosh—</color>",
  ui_story_5045_50450801_114_dialog_content = "Ah, the wind is rising again. This time, I'm gonna take good care of this kite.",
  ui_story_5045_50450801_115_dialog_content = "May be we should let the kite fly one more time.",
  ui_story_5045_50450801_116_dialog_content = "Eh?",
  ui_story_5045_50450801_117_dialog_content = "PlayerName, have you flown a kite before?",
  ui_story_5045_50450901_1_dialog_content = "<color=#737378>Time: 3:00 PM</color>",
  ui_story_5045_50450901_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50450901_3_dialog_content = "(I never thought I'd finish a case so soon.)",
  ui_story_5045_50450901_4_dialog_content = "(My legal abilities can't be better than my psychic abilities, can they?)",
  ui_story_5045_50450901_5_dialog_content = "(If Irridon saw our trial, she might think about paying me more.)",
  ui_story_5045_50450901_6_dialog_content = "(When the time comes, heh, I'll give Vice and the others a surprise!)",
  ui_story_5045_50450901_7_dialog_content = "(But then again...)",
  ui_story_5045_50450901_8_dialog_content = "Why are so many people filing today!?",
  ui_story_5045_50450901_9_dialog_content = "Huh? Lost interest in trial work so soon?",
  ui_story_5045_50450901_10_dialog_content = "N-No way!",
  ui_story_5045_50450901_11_dialog_content = "Ah, what brings our ever-busy Lady Irridon here?",
  ui_story_5045_50450901_12_dialog_content = "Zzz...",
  ui_story_5045_50450901_13_dialog_content = "Tina, wake up!",
  ui_story_5045_50450901_14_dialog_content = "Right...",
  ui_story_5045_50450901_15_dialog_content = "Angel, what are you waiting for? Go and make some tea for our esteemed chief judge!",
  ui_story_5045_50450901_16_dialog_content = "... Oh.",
  ui_story_5045_50450901_17_dialog_content = "There's no need.",
  ui_story_5045_50450901_18_dialog_content = "I heard that you tried a case this morning, so I came to assess the aftermath.",
  ui_story_5045_50450901_19_dialog_content = "The case was conducted by the book.",
  ui_story_5045_50450901_20_dialog_content = "On the contrary, my trial tomorrow will inspire the world and become a precedent for future generations to learn from and imitate.",
  ui_story_5045_50450901_21_dialog_content = "When the time comes, feel free to come again and witness it for yourself.",
  ui_story_5045_50450901_22_dialog_content = "We'll see. Perhaps, if I have time.",
  ui_story_5045_50450901_23_dialog_content = "I just heard that the case this morning caused quite a stir. I want to know the specifics.",
  ui_story_5045_50450901_24_dialog_content = "Lady Irridon, PlayerName and I tried this morning's case.",
  ui_story_5045_50450901_25_dialog_content = "I recorded the details and the trial process in this notebook. Please have a look.",
  ui_story_5045_50450901_26_dialog_content = "Impressive. You have formed some good habits since arriving here, PlayerName.",
  ui_story_5045_50450901_27_dialog_content = "Did you just say that this case caused a stir?",
  ui_story_5045_50450901_28_dialog_content = "Yes.",
  ui_story_5045_50450901_29_dialog_content = "So, how does public opinion currently stand regarding this case?",
  ui_story_5045_50450901_30_dialog_content = "What do you think?",
  ui_story_5045_50450901_31_dialog_content = "Well... I'm guessing it must be pretty positive, no?",
  ui_story_5045_50450901_32_dialog_content = "PlayerName has proven himself worthy of being personally chosen by you, Chief Judge, to assist us here.",
  ui_story_5045_50450901_33_dialog_content = "With the help of PlayerName, it's only natural that Leyn should make some progress too.",
  ui_story_5045_50450901_34_dialog_content = "Maybe it won't be long before he becomes the second-best judge in the Romance Division!",
  ui_story_5045_50450901_35_dialog_content = "Leyn, are PlayerName's records complete?",
  ui_story_5045_50450901_36_dialog_content = "Yes, his records are very complete, indeed.",
  ui_story_5045_50450901_37_dialog_content = "The investigation only scratched the surface, and the parties were not allowed to fully explain themselves in court...",
  ui_story_5045_50450901_38_dialog_content = "I remember that your previous trials were not so sloppy.",
  ui_story_5045_50450901_39_dialog_content = "The cases of the Romance Division are different from anything we have encountered before.",
  ui_story_5045_50450901_40_dialog_content = "I'm also trying to figure out how best to handle such cases",
  ui_story_5045_50450901_41_dialog_content = "The Romance Division has only just been established, and there are no cases for us to learn from.",
  ui_story_5045_50450901_42_dialog_content = "I understand the pressure.",
  ui_story_5045_50450901_43_dialog_content = "But please remember that even a small case in our eyes may affect the lives of the parties concerned.",
  ui_story_5045_50450901_44_dialog_content = "The way you deal with each case will affect the attitude the people of Lumopolis hold toward romantic relationships in the future.",
  ui_story_5045_50450901_45_dialog_content = "It seems public opinion as a result of taking up the case this morning is not very good...",
  ui_story_5045_50450901_46_dialog_content = "This morning's case shows us that the cost of violating a betrothal agreement is negligible.",
  ui_story_5045_50450901_47_dialog_content = "We may see more cases involving the dissolution of engagements.",
  ui_story_5045_50450901_48_dialog_content = "Prepare yourselves.",
  ui_story_5045_50450901_49_dialog_content = "Did Leyn's trial just increase our workload?",
  ui_story_5045_50450901_50_dialog_content = "Since all our cases are of the same type, we should be able to handle them much faster.",
  ui_story_5045_50450901_51_dialog_content = "If that's true, such cases will be handed over to Leyn and PlayerName in the future.",
  ui_story_5045_50450901_52_dialog_content = "Huh? But with all these cases...",
  ui_story_5045_50450901_53_dialog_content = "How many sessions will it take to complete each trial?",
  ui_story_5045_50451001_1_dialog_content = "<color=#737378>Time: 2:00 PM</color>",
  ui_story_5045_50451001_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50451001_3_dialog_content = "Yawn—",
  ui_story_5045_50451001_4_dialog_content = "Huh? PlayerName, why are you staring at me so seriously?",
  ui_story_5045_50451001_5_dialog_content = "Did you fall asleep just now?",
  ui_story_5045_50451001_6_dialog_content = "Sure, I dozed off...",
  ui_story_5045_50451001_7_dialog_content = "But you were so happy just now...",
  ui_story_5045_50451001_8_dialog_content = "Come to think of it, I had such a beautiful dream just now... Heeheehee!",
  ui_story_5045_50451001_9_dialog_content = "Ahem... Anyway, as long as you're awake now.",
  ui_story_5045_50451001_10_dialog_content = "I'm not sure exactly how I'm supposed to help you.",
  ui_story_5045_50451001_11_dialog_content = "So when you were asleep, I just helped to speak with some of the people filing cases.",
  ui_story_5045_50451001_12_dialog_content = "New cases?",
  ui_story_5045_50451001_13_dialog_content = "Let me see...",
  ui_story_5045_50451001_14_dialog_content = "Well, thank you, PlayerName, but these complaints are not the responsibility of the Romance Division.",
  ui_story_5045_50451001_15_dialog_content = "R-Really? Sorry. I guess I've done more harm than good...",
  ui_story_5045_50451001_16_dialog_content = "Don't take it to heart.",
  ui_story_5045_50451001_17_dialog_content = "I didn't tell you about it before I fell asleep, so it's my fault.",
  ui_story_5045_50451001_18_dialog_content = "You can rest assured, though, that although my working hours are short, my efficiency is very high.",
  ui_story_5045_50451001_19_dialog_content = "I'll teach you my unique work secret in just a moment.",
  ui_story_5045_50451001_20_dialog_content = "Wow, that's awesome! Let's get started!",
  ui_story_5045_50451001_21_dialog_content = "There's no hurry. Just answer me a question first.",
  ui_story_5045_50451001_22_dialog_content = "If one day you were to fall in love with someone, would you let them know?",
  ui_story_5045_50451001_23_option_content = "Yes.",
  ui_story_5045_50451001_24_dialog_content = "If I knew it was really love, I'd want to let them know.",
  ui_story_5045_50451001_25_dialog_content = "Even if they turned me down, it wouldn't matter. I'd do it out of respect for the feeling.",
  ui_story_5045_50451001_26_dialog_content = "I never expected you to be so insightful in this respect, PlayerName.",
  ui_story_5045_50451001_27_dialog_content = "I hope the person I like thinks just like you, heehee.",
  ui_story_5045_50451001_28_option_content = "No.",
  ui_story_5045_50451001_29_dialog_content = "If they didn't like me back, confessing my love would only cause them trouble.",
  ui_story_5045_50451001_30_dialog_content = "So, I don't think I would tell them too hastily.",
  ui_story_5045_50451001_31_dialog_content = "Heehee, you're just as shy as I thought, PlayerName.",
  ui_story_5045_50451001_32_option_content = "I don't know.",
  ui_story_5045_50451001_33_dialog_content = "I can't predict how I might feel in the future.",
  ui_story_5045_50451001_34_dialog_content = "I might know what to do then.",
  ui_story_5045_50451001_35_dialog_content = "Hmph, what a boring answer.",
  ui_story_5045_50451001_36_dialog_content = "I don't understand what you mean. Why do you ask?",
  ui_story_5045_50451001_37_dialog_content = "It seems like this has nothing to do with our work.",
  ui_story_5045_50451001_38_dialog_content = "It has everything to do with our work.",
  ui_story_5045_50451001_39_dialog_content = "What division are we working in?",
  ui_story_5045_50451001_40_dialog_content = "The Romance Division.",
  ui_story_5045_50451001_41_dialog_content = "So, of course, we should discuss topics related to love.",
  ui_story_5045_50451001_42_dialog_content = "And discussing the topic of love can quickly result in a closer working relationship.",
  ui_story_5045_50451001_43_dialog_content = "I hope we can cooperate happily.",
  ui_story_5045_50451001_44_dialog_content = "In that case...",
  ui_story_5045_50451001_45_dialog_content = "How would you answer that question just now, Tina?",
  ui_story_5045_50451001_46_dialog_content = "Haha, I didn't expect you to turn the tables on me like this. Well, let me tell you.",
  ui_story_5045_50451001_47_dialog_content = "I would never take the initiative. After all, I'm a lady.",
  ui_story_5045_50451001_48_dialog_content = "At most... I would secretly, actively increase the chances of us running into each other.",
  ui_story_5045_50451001_49_dialog_content = "But if you don't see each other, how can you know if you really like them?",
  ui_story_5045_50451001_50_dialog_content = "What will you do if the other person turns out to be wrong for you?",
  ui_story_5045_50451001_51_dialog_content = "I've never considered things from such a perspective...",
  ui_story_5045_50451001_52_dialog_content = "That's just like you, PlayerName. You understand more than Leyn!",
  ui_story_5045_50451001_53_dialog_content = "You're indeed a fine assistant. I'll be sure to trouble you with such matters from now on.",
  ui_story_5045_50451001_54_dialog_content = "Please help me receive all the cases, check whether the statements are true, and determine relevant laws and regulations...",
  ui_story_5045_50451001_55_dialog_content = "Then summarize the details of the case for me!",
  ui_story_5045_50451001_56_dialog_content = "You mean, you basically want me to do everything for you?",
  ui_story_5045_50451001_57_dialog_content = "I'll sit in the judge's chair and ultimately carry out the trial. This is the most crucial and exhausting part.",
  ui_story_5045_50451001_58_dialog_content = "But you seem quite interested in the trial... Why don't you join me in court?",
  ui_story_5045_50451001_59_dialog_content = "<size=32>It's a good thing she promised to pay me extra...</size>",
  ui_story_5045_50451001_60_dialog_content = "Hmm? Did you say something?",
  ui_story_5045_50451001_61_dialog_content = "I said... with so many cases to process, which one should we start with?",
  ui_story_5045_50451001_62_dialog_content = "Don't waste your time on such trifling matters... Yawn—",
  ui_story_5045_50451001_63_dialog_content = "Just choose the one in your hands right now.",
  ui_story_5045_50451001_64_dialog_content = "\"Request for the defendant Fanny and the plaintiff Bacon to be <color=#1875ad>divorced</color> according to law...\"?",
  ui_story_5045_50451001_65_dialog_content = "Right! Let's start!",
  ui_story_5045_50451001_66_dialog_content = "Zzz...",
  ui_story_5045_50451001_67_dialog_content = "Did she mean to start working or start sleeping...",
  ui_story_5045_50451101_1_dialog_content = "<color=#737378>Time: 9:00 AM</color>",
  ui_story_5045_50451101_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Courtroom</color>",
  ui_story_5045_50451101_3_dialog_content = "PlayerName, do you remember which case we're trying today?",
  ui_story_5045_50451101_4_dialog_content = "I remember! The plaintiff, <color=#1875ad>Bacon</color> and the defendant, <color=#1875ad>Fanny</color>'s...",
  ui_story_5045_50451101_5_option_content = "Divorce dispute",
  ui_story_5045_50451101_6_dialog_content = "That's right. Seems the lesson before the trial is actually working on you.",
  ui_story_5045_50451101_7_dialog_content = "Perhaps one day soon, you'll be able to finish a trial on your own.",
  ui_story_5045_50451101_8_option_content = "Engagement annulment",
  ui_story_5045_50451101_9_dialog_content = "Wow! It looks like the lesson before the trial isn't working on you.",
  ui_story_5045_50451101_10_dialog_content = "Your most basic responsibility is to remember the information in these case files before the court session.",
  ui_story_5045_50451101_11_dialog_content = "In the next trial, you should try to watch, listen, and learn more.",
  ui_story_5045_50451101_12_dialog_content = "Ah, the case file does say \"divorce dispute\"!",
  ui_story_5045_50451101_13_dialog_content = "I never thought I'd stumble at the first hurdle like this...",
  ui_story_5045_50451101_14_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451101_15_dialog_content = "<size=45>White Night up high. Court is now in session!</size>",
  ui_story_5045_50451101_16_dialog_content = "White Night up high!",
  ui_story_5045_50451101_17_dialog_content = "(There are so many people listening in today! I guess everyone is really paying close attention to the Romance Division's cases these days...)",
  ui_story_5045_50451101_18_dialog_content = "First of all, let's hear what the plaintiff has to say.",
  ui_story_5045_50451101_19_dialog_content = "Y-Your Honor, my name is Bacon.",
  ui_story_5045_50451101_20_dialog_content = "Why does the plaintiff look so scared?",
  ui_story_5045_50451101_21_dialog_content = "Bacon, please don't feel nervous or afraid.",
  ui_story_5045_50451101_22_dialog_content = "The Hall of Justice is the fairest and safest place in Lumopolis.",
  ui_story_5045_50451101_23_dialog_content = "You can state your request with confidence here.",
  ui_story_5045_50451101_24_dialog_content = "I-I want to divorce my wife, Fanny...",
  ui_story_5045_50451101_25_dialog_content = "Bacon, do you really have to do this?",
  ui_story_5045_50451101_26_dialog_content = "Can... Can you let me finish?",
  ui_story_5045_50451101_27_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451101_28_dialog_content = "The defendant will refrain from interrupting the plaintiff.",
  ui_story_5045_50451101_29_dialog_content = "...",
  ui_story_5045_50451101_30_dialog_content = "Bacon, why do you want to divorce your wife Fanny?",
  ui_story_5045_50451101_31_dialog_content = "Because we... we're just so different!",
  ui_story_5045_50451101_32_dialog_content = "How long have you been married?",
  ui_story_5045_50451101_33_dialog_content = "Seven years.",
  ui_story_5045_50451101_34_dialog_content = "A few years ago, I had a job that was good enough to support us, so life was tolerable.",
  ui_story_5045_50451101_35_dialog_content = "But last year, I was suddenly made redundant and lost my source of income.",
  ui_story_5045_50451101_36_dialog_content = "Since then, Fanny has nagged me every day at home, and resented me for not having a job.",
  ui_story_5045_50451101_37_dialog_content = "I have now just realized that the love between us has been eroded by time.",
  ui_story_5045_50451101_38_dialog_content = "All we see now are each other's shortcomings.",
  ui_story_5045_50451101_39_dialog_content = "I don't want to waste any more time in such a marriage... I want a divorce, so I can become free again.",
  ui_story_5045_50451101_40_dialog_content = "In other words, your relationship has broken down?",
  ui_story_5045_50451101_41_dialog_content = "Defendant, do you agree with the plaintiff?",
  ui_story_5045_50451101_42_dialog_content = "Your Honor, I do not agree.",
  ui_story_5045_50451101_43_dialog_content = "Bacon became very depressed after his employer let him go.",
  ui_story_5045_50451101_44_dialog_content = "I just wanted to cheer Bacon up, so I would constantly ask him to talk and walk with me.",
  ui_story_5045_50451101_45_dialog_content = "I never once thought about leaving Bacon.",
  ui_story_5045_50451101_46_dialog_content = "Since he lost his job, I have been working part-time to supplement our savings. I have only ever complained maybe once or twice.",
  ui_story_5045_50451101_47_dialog_content = "But since...",
  ui_story_5045_50451101_48_dialog_content = "But, at the end of the day, if I've done something wrong, I'll change!",
  ui_story_5045_50451101_49_dialog_content = "(It appears Fanny wanted to say something just now, but suddenly <color=#1875ad>changed her mind</color>...)",
  ui_story_5045_50451101_50_dialog_content = "That's how it is.",
  ui_story_5045_50451101_51_dialog_content = "Is that right?",
  ui_story_5045_50451101_52_dialog_content = "I think Bacon may have been out of work for too long now... He gets so easily agitated.",
  ui_story_5045_50451101_53_dialog_content = "That's why he wants to divorce me—he's so stressed out!",
  ui_story_5045_50451101_54_dialog_content = "But I want to believe that Bacon will get better eventually.",
  ui_story_5045_50451101_55_dialog_content = "And, no matter what, I won't divorce him!",
  ui_story_5045_50451101_56_dialog_content = "I see.",
  ui_story_5045_50451101_57_dialog_content = "So... Yawn—",
  ui_story_5045_50451101_58_dialog_content = "Tina, we're in the middle of a trial! Don't fall asleep!",
  ui_story_5045_50451101_59_dialog_content = "Huh...? Ah!",
  ui_story_5045_50451101_60_dialog_content = "Thank you for waking me up, PlayerName. I almost made a fool of myself just now...",
  ui_story_5045_50451101_61_dialog_content = "Well, trust you to choose a case like this. It's not easy to try.",
  ui_story_5045_50451101_62_dialog_content = "After this wave of free love swept through Lumopolis, the number of divorce cases has indeed increased.",
  ui_story_5045_50451101_63_dialog_content = "But whether or not to grant a divorce is the problem that Romance Division has been looking into for quite some time.",
  ui_story_5045_50451101_64_dialog_content = "As for the current case, PlayerName...",
  ui_story_5045_50451101_65_dialog_content = "Do you have any other ideas?",
  ui_story_5045_50451101_66_dialog_content = "It seems you haven't found any useful clues too.",
  ui_story_5045_50451101_67_dialog_content = "Th-This clue is useless?",
  ui_story_5045_50451101_67X1_dialog_content = "In addition to that...",
  ui_story_5045_50451101_68_dialog_content = "Oh... I know!",
  ui_story_5045_50451101_69_dialog_content = "Tina, take a look at this!",
  ui_story_5045_50451101_70_dialog_content = "Now you're capable of recording the statements of both sides of the court without me? Not bad.",
  ui_story_5045_50451101_71_dialog_content = "You really are a joy of an assistant.",
  ui_story_5045_50451101_72_dialog_content = "But don't just pay attention to the records!",
  ui_story_5045_50451101_73_dialog_content = "As for the current case...",
  ui_story_5045_50451101_74_dialog_content = "I don't think Bacon's grounds for divorce are completely arbitrary.",
  ui_story_5045_50451101_75_dialog_content = "Didn't Bacon say that he felt there was no love between them?",
  ui_story_5045_50451101_76_dialog_content = "Marriage without love... It's hard to imagine.",
  ui_story_5045_50451101_77_dialog_content = "But Fanny also explained how she just wanted to cheer Bacon up.",
  ui_story_5045_50451101_78_dialog_content = "And it seemed clear to me that Fanny had made up her mind to help Bacon through this rough patch, no matter what.",
  ui_story_5045_50451101_79_dialog_content = "That makes sense, Bacon's unemployed and depressed...",
  ui_story_5045_50451101_80_dialog_content = "But not only did Fanny not mind, she also promised to stay with Bacon and help him get back on his feet.",
  ui_story_5045_50451101_81_dialog_content = "This kind of relationship between husband and wife is simply a story of Lumopolis!",
  ui_story_5045_50451101_82_dialog_content = "If Bacon is merely angry at this moment in time, and the judge decides to grant him a divorce...",
  ui_story_5045_50451101_83_dialog_content = "Won't the God of Light rob me of my chance to find my true love?",
  ui_story_5045_50451101_84_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451101_85_dialog_content = "White Night up high. It is time for the verdict!",
  ui_story_5045_50451101_86_dialog_content = "The Hall of Justice has ultimately decided that the relationship between the plaintiff Bacon and the defendant Fanny should not be dissolved.",
  ui_story_5045_50451101_87_dialog_content = "A union formed before the eyes of the God of Light should not be so hastily discarded.",
  ui_story_5045_50451101_88_dialog_content = "Please continue to love each other and work on your marriage.",
  ui_story_5045_50451101_89_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451101_90_dialog_content = "The trial is over!",
  ui_story_5045_50451101_91_dialog_content = "Fanny's side of the story is very touching.",
  ui_story_5045_50451101_92_dialog_content = "But don't you feel like she has been deliberately hiding something?",
  ui_story_5045_50451101_93_dialog_content = "PlayerName, your powers of observation are quite impressive.",
  ui_story_5045_50451101_94_dialog_content = "Let's ask Fanny what she's hiding.",
  ui_story_5045_50451101_95_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451101_96_dialog_content = "White Night up high, Fanny, are you sure you've told us the whole story?",
  ui_story_5045_50451101_97_dialog_content = "I-I think so...",
  ui_story_5045_50451101_98_dialog_content = "If you won't say it... then allow me!",
  ui_story_5045_50451101_99_dialog_content = "Your Honor, Fanny knows that we don't have much money, but she still borrowed a large amount, and now we're in debt.",
  ui_story_5045_50451101_100_dialog_content = "Bacon, like I told you, it was all for you.",
  ui_story_5045_50451101_101_dialog_content = "For me?",
  ui_story_5045_50451101_102_dialog_content = "You... You borrowed it without even asking me!",
  ui_story_5045_50451101_103_dialog_content = "I just... I just...",
  ui_story_5045_50451101_104_dialog_content = "Fanny, is it true that you borrowed money without Bacon's knowledge?",
  ui_story_5045_50451101_105_dialog_content = "... It's true.",
  ui_story_5045_50451101_106_dialog_content = "Your Honor, I can't live with someone who lied to me like that.",
  ui_story_5045_50451101_107_dialog_content = "Please allow me to divorce Fanny.",
  ui_story_5045_50451101_108_dialog_content = "I have only one request—please let us discuss the division of our assets.",
  ui_story_5045_50451101_109_dialog_content = "Fanny, do you agree to Bacon's request?",
  ui_story_5045_50451101_110_dialog_content = "Sigh, I have nothing more to say...",
  ui_story_5045_50451101_111_dialog_content = "I'll go along with whatever Bacon wants.",
  ui_story_5045_50451101_112_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451101_113_dialog_content = "White Night up high. It is time for the verdict!",
  ui_story_5045_50451101_114_dialog_content = "Due to irreconcilable differences between the plaintiff Bacon and the defendant Fanny, the Hall of Justice rules that their marriage should be dissolved immediately.",
  ui_story_5045_50451101_115_dialog_content = "According to the request of the parties, they can now negotiate the division of their assets between themselves.",
  ui_story_5045_50451101_116_dialog_content = "After which, they will sign the corresponding agreement in the presence of the judge.",
  ui_story_5045_50451101_117_dialog_content = "If you do not accept this judgment, you may appeal in accordance with the provisions of the Hall of Justice.",
  ui_story_5045_50451101_118_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451101_119_dialog_content = "The trial is over!",
  ui_story_5045_50451201_1_dialog_content = "<color=#737378>Time: 11:00 AM</color>",
  ui_story_5045_50451201_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Courtroom</color>",
  ui_story_5045_50451201_3_dialog_content = "Sigh, Tina's really gonna let me do this on my own...?",
  ui_story_5045_50451201_4_dialog_content = "Whatever happens, don't wake me up before two o'clock in the afternoon.",
  ui_story_5045_50451201_5_dialog_content = "But the property settlement agreement between Bacon and Fanny...",
  ui_story_5045_50451201_6_dialog_content = "As long as no one objects to the agreement, you can just let them go ahead and sign it.",
  ui_story_5045_50451201_7_dialog_content = "I know you can handle it... Yawn—",
  ui_story_5045_50451201_8_dialog_content = "Zzz...",
  ui_story_5045_50451201_9_dialog_content = "Hey, there's no way you can fall asleep that fast!",
  ui_story_5045_50451201_10_dialog_content = "Bacon and Fanny signed the agreement in the end. Fortunately, nothing out of the ordinary came up.",
  ui_story_5045_50451201_11_dialog_content = "Uhh!",
  ui_story_5045_50451201_12_dialog_content = "Your Honor...",
  ui_story_5045_50451201_13_dialog_content = "Fanny, what are you doing back here?",
  ui_story_5045_50451201_14_dialog_content = "<color=#737378>Time: 2:00 PM</color>",
  ui_story_5045_50451201_15_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50451201_16_dialog_content = "Ya—wn.",
  ui_story_5045_50451201_17_dialog_content = "What's eating you, PlayerName?",
  ui_story_5045_50451201_18_dialog_content = "You finally woke up.",
  ui_story_5045_50451201_19_dialog_content = "Bacon and Fanny signed the agreement this morning.",
  ui_story_5045_50451201_20_dialog_content = "But Fanny filed an appeal soon after.",
  ui_story_5045_50451201_21_dialog_content = "Huh? Is she not happy with how their property was divided up?",
  ui_story_5045_50451201_22_dialog_content = "You could say that, but it's not what you might think.",
  ui_story_5045_50451201_23_dialog_content = "Look at their agreement.",
  ui_story_5045_50451201_24_dialog_content = "\"All of the couple's property now belongs to Fanny, and all of their debts belong to Bacon\"?",
  ui_story_5045_50451201_25_dialog_content = "Did... Fanny force Bacon to write this?",
  ui_story_5045_50451201_26_dialog_content = "On the contrary—the agreement was written by Bacon. Fanny didn't want to fight over their property because she was too distressed by the whole ordeal.",
  ui_story_5045_50451201_27_dialog_content = "She signed the agreement without reading it, then found that these were the terms after the fact.",
  ui_story_5045_50451201_28_dialog_content = "Bacon clearly showed us that he resented Fanny at the trial. Why would he do this?",
  ui_story_5045_50451201_29_dialog_content = "Fanny feels that this shows Bacon still loves her, so she appeals to the ruling.",
  ui_story_5045_50451201_30_dialog_content = "She has asked us to withdraw the divorce judgment.",
  ui_story_5045_50451201_31_dialog_content = "My judgment was... wrong?",
  ui_story_5045_50451201_32_option_content = "Don't be too quick to blame yourself.",
  ui_story_5045_50451201_33_dialog_content = "The concerned parties may not have stated all the facts in court.",
  ui_story_5045_50451201_34_dialog_content = "You made the judgment that best suited the situation at the time.",
  ui_story_5045_50451201_35_dialog_content = "Now, we just need to find a way to extract the facts from all this and prepare for the appeal!",
  ui_story_5045_50451201_36_dialog_content = "... I never thought you'd be the one to comfort me.",
  ui_story_5045_50451201_37_dialog_content = "But still, thank you, PlayerName.",
  ui_story_5045_50451201_38_dialog_content = "I'm a real judge after all—I'd never let such a small thing like this rattle me.",
  ui_story_5045_50451201_39_option_content = "We can't be sure yet.",
  ui_story_5045_50451201_40_dialog_content = "Bacon's property settlement agreement clearly contradicts his previous statement about their irreconcilable differences.",
  ui_story_5045_50451201_41_dialog_content = "How can we bear judgment when we don't know what really happened between them?",
  ui_story_5045_50451201_42_dialog_content = "You're right. To try this case properly, it's crucial that we find out what really happened.",
  ui_story_5045_50451201_43_option_content = "Then it's wrong",
  ui_story_5045_50451201_44_dialog_content = "There's no other explanation for what's happening now.",
  ui_story_5045_50451201_45_dialog_content = "Really...?",
  ui_story_5045_50451201_46_dialog_content = "However, as judges, we still have to make our judgments based on facts.",
  ui_story_5045_50451201_47_dialog_content = "But what happened between them?",
  ui_story_5045_50451201_48_dialog_content = "Let's go!",
  ui_story_5045_50451201_49_dialog_content = "Huh? Where to?",
  ui_story_5045_50451201_50_dialog_content = "To their house to investigate what really happened, of course.",
  ui_story_5045_50451201_51_dialog_content = "And we'd better hurry up about it—if we don't finish investigating within the next two hours...",
  ui_story_5045_50451201_52_dialog_content = "You'll have to carry me on your back when I fall asleep.",
  ui_story_5045_50451201_53_dialog_content = "A-Alright, let's go then!",
  ui_story_5045_50451201_54_dialog_content = "<color=#737378>Time: 2:30 PM</color>",
  ui_story_5045_50451201_55_dialog_content = "<color=#737378>Location: Lower Lumopolis</color>",
  ui_story_5045_50451201_56_dialog_content = "Bacon and Fanny's house is just up ahead.",
  ui_story_5045_50451201_57_dialog_content = "Hey, who's that guy standing at their door?",
  ui_story_5045_50451201_58_dialog_content = "(Why does he look so familiar...?)",
  ui_story_5045_50451201_59_dialog_content = "...",
  ui_story_5045_50451201_60_dialog_content = "Hello. Do you know Bacon and Fanny?",
  ui_story_5045_50451201_61_dialog_content = "I'm sorry, but... who are you?",
  ui_story_5045_50451201_62_dialog_content = "We're from the Hall of Justice.",
  ui_story_5045_50451201_63_dialog_content = "PlayerName, show him that thing and you can prove our <color=#1875ad>identity</color>.",
  ui_story_5045_50451201_64_dialog_content = "This?",
  ui_story_5045_50451201_65_dialog_content = "That's not what I meant.",
  ui_story_5045_50451201_66_dialog_content = "Oh, i-is it? In that case...",
  ui_story_5045_50451201_67_dialog_content = "You're judges? Please forgive my rudeness just now.",
  ui_story_5045_50451201_68_dialog_content = "I'm a friend of Bacon's. The name's <color=#1875ad>Karl</color>.",
  ui_story_5045_50451201_69_dialog_content = "I just came here looking for Bacon, but it seems only Fanny is home right now.",
  ui_story_5045_50451201_70_dialog_content = "(Doesn't he know that Bacon and Fanny are going through a divorce?)",
  ui_story_5045_50451201_71_dialog_content = "So, what's your take on Bacon's relationship with his wife?",
  ui_story_5045_50451201_72_dialog_content = "... Have they done something illegal?",
  ui_story_5045_50451201_73_dialog_content = "They're going to—",
  ui_story_5045_50451201_74_dialog_content = "...",
  ui_story_5045_50451201_75_dialog_content = "<size=32>Ahem... Don't let the details of the case affect the witness's opinion!</size>",
  ui_story_5045_50451201_76_dialog_content = "We're actually just carrying out some research into the happiness of marriage life in Lumopolis.",
  ui_story_5045_50451201_77_dialog_content = "We'd appreciate it if you could answer some questions for us.",
  ui_story_5045_50451201_78_dialog_content = "Well, they have always been a very loving couple—a shining example to everyone who knows them.",
  ui_story_5045_50451201_79_dialog_content = "Are you aware of any issues over which the two of them may have argued?",
  ui_story_5045_50451201_80_dialog_content = "Haha! Argue? Even if Lumopolis fell from the sky, they wouldn't fight.",
  ui_story_5045_50451201_81_dialog_content = "I see...",
  ui_story_5045_50451201_82_dialog_content = "<color=#737378>Time: 3:00 PM</color>",
  ui_story_5045_50451201_83_dialog_content = "<color=#737378>Location: Lower Lumopolis, Bacon and Fanny's House</color>",
  ui_story_5045_50451201_84_dialog_content = "Hello? Is anybody home?",
  ui_story_5045_50451201_85_dialog_content = "Your Honors, what brings you here?",
  ui_story_5045_50451201_86_dialog_content = "We have received your appeal request and have realized that mistakes may have been made during the first trial.",
  ui_story_5045_50451201_87_dialog_content = "So, we're here to find the two of you to ascertain the full details of the situation.",
  ui_story_5045_50451201_88_dialog_content = "Bacon... he said he'd come home later to pack his bags.",
  ui_story_5045_50451201_89_dialog_content = "But please, come in!",
  ui_story_5045_50451201_90_dialog_content = "What's this on the ground...?",
  ui_story_5045_50451201_91_dialog_content = "I'm so sorry. I haven't had time to clean things up...",
  ui_story_5045_50451201_92_dialog_content = "This <color=#1875ad>plate</color> is...",
  ui_story_5045_50451201_93_dialog_content = "It's me! I accidentally broke it...",
  ui_story_5045_50451201_94_dialog_content = "But this plate doesn't look like it was broken accidentally.",
  ui_story_5045_50451201_95_dialog_content = "Fanny, we came here for a reason—we wish to find the truth.",
  ui_story_5045_50451201_96_dialog_content = "If you're still holding something back, I'm afraid the truth of this case will never come to light.",
  ui_story_5045_50451201_97_dialog_content = "... Alright.",
  ui_story_5045_50451201_98_dialog_content = "Bacon broke this plate last night.",
  ui_story_5045_50451201_99_dialog_content = "But I could feel that he was deliberately trying to make me angry so I'd accept the fact that we'd soon be divorced.",
  ui_story_5045_50451201_100_dialog_content = "I don't understand. If this is how Bacon treats you... why would you still want to stay with him?",
  ui_story_5045_50451201_101_dialog_content = "Obviously, you've never known true love.",
  ui_story_5045_50451201_102_dialog_content = "One day, you'll start a family of your own with the person you love...",
  ui_story_5045_50451201_103_dialog_content = "When that day comes, you'll do everything in your power to hold on to that family.",
  ui_story_5045_50451201_104_dialog_content = "Even if Bacon wants to break up your family?",
  ui_story_5045_50451201_105_dialog_content = "Your Honors, there are some things I couldn't say in court. I was afraid that Bacon would be laughed at.",
  ui_story_5045_50451201_106_dialog_content = "Please rest assured that we'll keep your secret safe.",
  ui_story_5045_50451201_107_dialog_content = "It would be in everyone's best interests if you'd just tell us what you have to say.",
  ui_story_5045_50451201_108_dialog_content = "One day, I dragged Bacon out for a walk and we stumbled upon a free consultation event a certain clinic happened to be holding.",
  ui_story_5045_50451201_109_dialog_content = "It was then that Bacon was diagnosed with <color=#1875ad>depression</color>.",
  ui_story_5045_50451201_110_dialog_content = "The doctor said it was something about he's heart that was making Bacon a lethargic, depressed, insomniac...",
  ui_story_5045_50451201_111_dialog_content = "That was when I first found out that Bacon was sick, and wasn't just lazing about for the sake of it.",
  ui_story_5045_50451201_112_dialog_content = "So after that, I didn't nag him ever again.",
  ui_story_5045_50451201_113_dialog_content = "I just hoped that Bacon could get the treatment he needed and gradually get better.",
  ui_story_5045_50451201_114_dialog_content = "But I really didn't expect Bacon to suddenly go to the Hall of Justice and file for divorce.",
  ui_story_5045_50451201_115_dialog_content = "Something must have happened to him... but he refused to tell me anything.",
  ui_story_5045_50451201_116_dialog_content = "What could have happened to Bacon?",
  ui_story_5045_50451201_117_dialog_content = "He probably won't tell us if we ask him directly. Why don't we look for clues around their home first?",
  ui_story_5045_50451201_118_dialog_content = "Is there anywhere in particular you'd like to investigate?",
  ui_story_5045_50451201_119_dialog_content = "Let me think...",
  ui_story_5045_50451201_120_option_content = "Check the walls",
  ui_story_5045_50451201_121_dialog_content = "Can I take a look at that <color=#1875ad>photo</color> hanging on the wall?",
  ui_story_5045_50451201_122_dialog_content = "Sure, I'll take it down for you.",
  ui_story_5045_50451201_123_dialog_content = "It's a photo of Fanny and Bacon.",
  ui_story_5045_50451201_124_dialog_content = "Yes, but that was seven years ago.",
  ui_story_5045_50451201_125_dialog_content = "At that time, we had just got married and we had nothing.",
  ui_story_5045_50451201_126_dialog_content = "I don't know how, but Bacon somehow persuaded a photographer to take this picture for us for free...",
  ui_story_5045_50451201_127_dialog_content = "Come to think of it, this was the first and only photo we had taken of ourselves together.",
  ui_story_5045_50451201_128_dialog_content = "Is the <color=#1875ad>address</color> written on the back where you had it taken?",
  ui_story_5045_50451201_129_dialog_content = "Hmm, that's strange. I don't remember there being anything written on the back of it...",
  ui_story_5045_50451201_130_dialog_content = "But this is Bacon's handwriting.",
  ui_story_5045_50451201_131_dialog_content = "It seems somewhat suspicious, doesn't it? Let's write it down.",
  ui_story_5045_50451201_132_dialog_content = "In addition to that...",
  ui_story_5045_50451201_133_option_content = "Check the table",
  ui_story_5045_50451201_134_dialog_content = "Huh? What's this <color=#1875ad>card</color>?",
  ui_story_5045_50451201_135_dialog_content = "... That's from the <color=#1875ad>self-help course</color>. It's an <color=#1875ad>attendance card</color>.",
  ui_story_5045_50451201_136_dialog_content = "Our friend Karl told me that this course was particularly good.",
  ui_story_5045_50451201_137_dialog_content = "They help people develop their willpower so they no longer fear facing life's difficulties.",
  ui_story_5045_50451201_138_dialog_content = "He said that many of the people who took this course went on to lead better lives.",
  ui_story_5045_50451201_139_dialog_content = "They actually offer courses like this in Lumopolis?",
  ui_story_5045_50451201_140_dialog_content = "I haven't taken any courses like this myself, but I know that they're quite expensive.",
  ui_story_5045_50451201_141_dialog_content = "... I wanted Bacon to get help, so I borrowed money to sign him up.",
  ui_story_5045_50451201_142_dialog_content = "But Bacon said he wouldn't go... However, there are no refunds for the self-help course.",
  ui_story_5045_50451201_143_dialog_content = "So, I hope Bacon can come back, even just to try it once...",
  ui_story_5045_50451201_144_dialog_content = "So Fanny borrowed the money for Bacon...",
  ui_story_5045_50451201_145_dialog_content = "In addition to that...",
  ui_story_5045_50451201_146_option_content = "Wrap it up",
  ui_story_5045_50451201_147_dialog_content = "Indeed. It doesn't seem as though there are any more valuable clues here.",
  ui_story_5045_50451201_148_dialog_content = "But this <color=#1875ad>bottle</color> does seem rather intriguing.",
  ui_story_5045_50451201_149_dialog_content = "<color=#737378>Rustle—</color>",
  ui_story_5045_50451201_150_dialog_content = "What kind of seasoning do you keep in this bottle?",
  ui_story_5045_50451201_151_dialog_content = "Oh, that's Bacon's <color=#1875ad>medicine bottle</color>!",
  ui_story_5045_50451201_152_dialog_content = "Bacon has been receiving treatment from a free clinic doctor since that time, and has to take medicine every day.",
  ui_story_5045_50451201_153_dialog_content = "I don't know if he's even taken his medicine today.",
  ui_story_5045_50451201_154_dialog_content = "Erm, Bacon really doesn't mind making people worry about him.",
  ui_story_5045_50451201_155_dialog_content = "<color=#737378>Time: 4:00 PM</color>",
  ui_story_5045_50451201_156_dialog_content = "<color=#737378>Location: Lower Lumopolis, Outside the Free Clinic</color>",
  ui_story_5045_50451201_157_dialog_content = "So, we went to Bacon's house to investigate, but now I feel even more confused than ever.",
  ui_story_5045_50451201_158_dialog_content = "I hope we can find out some useful information here.",
  ui_story_5045_50451201_159_dialog_content = "Hey, PlayerName and Judge Tina!",
  ui_story_5045_50451201_160_dialog_content = "Raphael, what are you doing here?",
  ui_story_5045_50451201_161_dialog_content = "I could ask you the same thing... This is where I work!",
  ui_story_5045_50451201_162_dialog_content = "We believe a party to our case might be a patient here, so we came here to investigate the situation.",
  ui_story_5045_50451201_163_dialog_content = "Breakfast foods aside, does the name Bacon mean anything to you?",
  ui_story_5045_50451201_164_dialog_content = "Bacon? He's my <color=#1875ad>patient</color>!",
  ui_story_5045_50451201_165_dialog_content = "Really? What a coincidence...",
  ui_story_5045_50451201_166_dialog_content = "It sure is. Bacon is a patient I took on during a free clinic outreach event.",
  ui_story_5045_50451201_167_dialog_content = "His condition hasn't shown any signs of improving. It's really very baffling.",
  ui_story_5045_50451201_168_dialog_content = "But he hasn't come in for a visit in such a long time, now. I'm worried...",
  ui_story_5045_50451201_169_dialog_content = "Wait! You said Bacon's your client? What's happened to him? He's not in jail, is he!?",
  ui_story_5045_50451201_170_dialog_content = "Don't worry, it's nothing that serious.",
  ui_story_5045_50451201_171_dialog_content = "Really? Then you should remind him to come to me as soon as possible for further consultation, and to pick up his medicine.",
  ui_story_5045_50451201_172_dialog_content = "He must have already finished the medicine I gave him last time.",
  ui_story_5045_50451201_173_dialog_content = "Huh? But we found a medicine bottle in his house, and it was full of pills...",
  ui_story_5045_50451201_174_dialog_content = "No way!",
  ui_story_5045_50451201_175_dialog_content = "The medicine I gave Bacon is only administered in small doses. He's supposed to come back to me after finishing it all.",
  ui_story_5045_50451201_176_dialog_content = "Could Fanny have made a mistake?",
  ui_story_5045_50451201_177_dialog_content = "<color=#737378>Time: 5:00 PM</color>",
  ui_story_5045_50451201_178_dialog_content = "<color=#737378>Location: Lower Lumopolis, Bacon and Fanny's House</color>",
  ui_story_5045_50451201_179_dialog_content = "<size=45>Heavens!</size>",
  ui_story_5045_50451201_180_dialog_content = "Shh! If Fanny sees Bacon's doctor here, she'll get worried.",
  ui_story_5045_50451201_181_dialog_content = "What did you find, Raphael?",
  ui_story_5045_50451201_182_dialog_content = "These are the sleeping pills I gave Bacon a while back.",
  ui_story_5045_50451201_183_dialog_content = "Why didn't he take any of them?",
  ui_story_5045_50451201_184_dialog_content = "You mean to say, Bacon has been accumulating these pills deliberately?",
  ui_story_5045_50451201_185_dialog_content = "I really don't understand what Bacon could be thinking...",
  ui_story_5045_50451201_186_dialog_content = "Raphael, supposedly, just suppose for a second...",
  ui_story_5045_50451201_187_dialog_content = "Suppose someone were to swallow all these pills at once... What would happen to them?",
  ui_story_5045_50451201_188_dialog_content = "<size=45>Whoa!</size>",
  ui_story_5045_50451201_189_dialog_content = "You still have so much to live for!",
  ui_story_5045_50451201_190_dialog_content = "PlayerName, I'm getting a bad feeling about all this...",
  ui_story_5045_50451201_191_dialog_content = "Me too.",
  ui_story_5045_50451201_192_dialog_content = "It appears we should begin the trial sooner rather than later.",
  ui_story_5045_50451201_193_dialog_content = "But before that, I must ask for one thing from you, PlayerName.",
  ui_story_5045_50451201_194_dialog_content = "Go on then, say it!",
  ui_story_5045_50451201_195_dialog_content = "I'm... going to... sleep... carry me back...",
  ui_story_5045_50451201_196_dialog_content = "Zzz...",
  ui_story_5045_50451201_197_dialog_content = "...",
  ui_story_5045_50451301_1_dialog_content = "<color=#737378>Time: 9:00 AM</color>",
  ui_story_5045_50451301_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Courtroom</color>",
  ui_story_5045_50451301_3_dialog_content = "Hmm? Seems we don't have any audience today...",
  ui_story_5045_50451301_4_dialog_content = "After thinking about it for a long time, I believe that the audience present may have an effect on the parties involved in this case.",
  ui_story_5045_50451301_5_dialog_content = "Therefore, today's case will not be open to the public.",
  ui_story_5045_50451301_6_dialog_content = "Huh? When did you start thinking about this?",
  ui_story_5045_50451301_7_dialog_content = "Maybe it was last night when you returned with me sleeping on your back.",
  ui_story_5045_50451301_8_dialog_content = "You mean, you...",
  ui_story_5045_50451301_9_option_content = "You were still working while sleeping!?",
  ui_story_5045_50451301_10_dialog_content = "Yes, I dream a lot.",
  ui_story_5045_50451301_11_dialog_content = "Sometimes I can even think up solutions in my dreams to problems I could never handle in my waking life.",
  ui_story_5045_50451301_12_dialog_content = "Compared to your waking life, your dreams sound exhausting...",
  ui_story_5045_50451301_13_dialog_content = "Heehee, I knew you'd understand, PlayerName.",
  ui_story_5045_50451301_14_dialog_content = "Leyn has never been as nice to me as you are.",
  ui_story_5045_50451301_15_dialog_content = "R-Really...?",
  ui_story_5045_50451301_16_option_content = "You're actually quite reliable.",
  ui_story_5045_50451301_17_dialog_content = "Uh-huh, naturally.",
  ui_story_5045_50451301_18_dialog_content = "Reliability is the minimum requirement in this profession.",
  ui_story_5045_50451301_19_dialog_content = "Wait! So, in your mind, you've always seen me as being unreliable?",
  ui_story_5045_50451301_20_dialog_content = "I-I...",
  ui_story_5045_50451301_21_option_content = "Were you pretending to be asleep?",
  ui_story_5045_50451301_22_dialog_content = "Hmm.. It seems you're still far behind Leyn when it comes to being considerate toward your partner, PlayerName.",
  ui_story_5045_50451301_23_dialog_content = "(Am I imagining things, or is Tina suddenly looking at me with an air of disgust?)",
  ui_story_5045_50451301_24_dialog_content = "(It seems that my answer has shaken the trust between us...)",
  ui_story_5045_50451301_25_dialog_content = "But never mind that, we need to start the trial soon.",
  ui_story_5045_50451301_26_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451301_27_dialog_content = "<size=45>White Night up high. Court is now in session!</size>",
  ui_story_5045_50451301_28_dialog_content = "First of all, I call the appellant Fanny to make her statement.",
  ui_story_5045_50451301_29_dialog_content = "Thank you, Your Honor. I cannot accept the divorce judgment of the first trial.",
  ui_story_5045_50451301_30_dialog_content = "I don't agree that my relationship with Bacon has broken down, therefor I do not want a divorce.",
  ui_story_5045_50451301_31_dialog_content = "Fanny, stop this...",
  ui_story_5045_50451301_32_dialog_content = "Just let me go, please.",
  ui_story_5045_50451301_33_dialog_content = "Bacon, you still insist that your relationship has broken down, correct?",
  ui_story_5045_50451301_34_dialog_content = "Correct, Your Honor.",
  ui_story_5045_50451301_35_dialog_content = "But...",
  ui_story_5045_50451301_36_dialog_content = "Your actions prove that you've been <color=#1875ad>protecting Fanny's best interests</color> all along!",
  ui_story_5045_50451301_37_dialog_content = "PlayerName, what makes you say this all of a sudden?",
  ui_story_5045_50451301_38_dialog_content = "M-My mistake!",
  ui_story_5045_50451301_39_dialog_content = "What I actually wanted to say was...",
  ui_story_5045_50451301_40_dialog_content = "Tina, take a look at this!",
  ui_story_5045_50451301_41_dialog_content = "Hmm, your records are indeed very detailed.",
  ui_story_5045_50451301_42_dialog_content = "But why does this scene seem so familiar? Didn't I see this all in a dream?",
  ui_story_5045_50451301_43_dialog_content = "I haven't had any nightmares recently... so, today's trial should be a success!",
  ui_story_5045_50451301_44_dialog_content = "Then again, did you pull this out all of a sudden just so I'd indulge your ego?",
  ui_story_5045_50451301_45_dialog_content = "That's not it. What I actually wanted to say was...",
  ui_story_5045_50451301_46_dialog_content = "You're leaving all your property to Fanny and taking on all of your debt yourself! What more do I need to say?",
  ui_story_5045_50451301_47_dialog_content = "Th-This has nothing to do with the breakdown of our marriage.",
  ui_story_5045_50451301_48_dialog_content = "I'm handing over all our property to Fanny as compensation for her hard work at home for the past seven years.",
  ui_story_5045_50451301_49_dialog_content = "I simply wish to trade this much for my freedom... that's all.",
  ui_story_5045_50451301_50_dialog_content = "Is that all?",
  ui_story_5045_50451301_51_dialog_content = "You really don't love me anymore, do you...?",
  ui_story_5045_50451301_52_dialog_content = "That's right, now please stop pestering me.",
  ui_story_5045_50451301_53_dialog_content = "Boo-hoo... Why? Why are you doing this to me!?",
  ui_story_5045_50451301_54_dialog_content = "Fanny, we have yet to bring this case to a satisfactory degree of clarity. Don't worry about it just yet.",
  ui_story_5045_50451301_55_dialog_content = "Your Honor, if that's how Bacon feels, I really don't want to pester him anymore.",
  ui_story_5045_50451301_56_dialog_content = "Is there any point in dragging out this trial any further?",
  ui_story_5045_50451301_57_dialog_content = "Yes! Of course there is!",
  ui_story_5045_50451301_58_dialog_content = "Hmm? Why do you suddenly seem so excited, PlayerName?",
  ui_story_5045_50451301_59_dialog_content = "I believe that the two parties still love each other...",
  ui_story_5045_50451301_60_dialog_content = "Well, what do you plan on doing next?",
  ui_story_5045_50451301_61_dialog_content = "I... I don't know...",
  ui_story_5045_50451301_62_dialog_content = "Haha, just watch and learn then.",
  ui_story_5045_50451301_63_dialog_content = "Ahem, we found some peculiar things during our investigation.",
  ui_story_5045_50451301_64_dialog_content = "If you can't explain them clearly, you may be facing more than just a trial in the Romance Division.",
  ui_story_5045_50451301_65_dialog_content = "One of the strange things mentioned is <color=#1875ad>the thing Raphael checked yesterday</color>. She must mean...",
  ui_story_5045_50451301_66_dialog_content = "That's not it. Think again, PlayerName.",
  ui_story_5045_50451301_67_dialog_content = "Got it!",
  ui_story_5045_50451301_68_dialog_content = "Bacon, do you recognize this?",
  ui_story_5045_50451301_69_dialog_content = "Well...",
  ui_story_5045_50451301_70_dialog_content = "Can you tell us what kind of medicine is in this bottle?",
  ui_story_5045_50451301_71_dialog_content = "Th-This is the sleeping medicine my doctor prescribed me.",
  ui_story_5045_50451301_72_dialog_content = "We met your free clinic doctor Raphael yesterday.",
  ui_story_5045_50451301_73_dialog_content = "According to her, she only gives you a small dose of sleeping pills each time you see her.",
  ui_story_5045_50451301_74_dialog_content = "It appears you have been secretly stocking up on the pills without telling your doctor.",
  ui_story_5045_50451301_75_dialog_content = "With such a large dosage of sleeping pills at your disposal... could it be that you plan on poisoning your wife?",
  ui_story_5045_50451301_76_dialog_content = "<size=45>What!?</size>",
  ui_story_5045_50451301_77_dialog_content = "Fanny, no, that's not it! I didn't want to poison anyone...",
  ui_story_5045_50451301_78_dialog_content = "Then why did you deliberately save up these sleeping pills?",
  ui_story_5045_50451301_79_dialog_content = "...",
  ui_story_5045_50451301_80_dialog_content = "It has nothing to do with the divorce.",
  ui_story_5045_50451301_81_dialog_content = "Bacon, you really have changed. I don't know who you are anymore...",
  ui_story_5045_50451301_82_dialog_content = "Fanny...",
  ui_story_5045_50451301_83_dialog_content = "Tina, what should we do now?",
  ui_story_5045_50451301_84_dialog_content = "If Bacon doesn't spill the beans, there's nothing we can do.",
  ui_story_5045_50451301_85_dialog_content = "Can you think of any questionable points we haven't clarified yet?",
  ui_story_5045_50451301_86_dialog_content = "The whole case is one big questionable point!",
  ui_story_5045_50451301_87_dialog_content = "Hmm, come to think of it...",
  ui_story_5045_50451301_88_dialog_content = "The <color=#1875ad>address</color>!",
  ui_story_5045_50451301_89_dialog_content = "What address?",
  ui_story_5045_50451301_90_dialog_content = "No... Right, this is it!",
  ui_story_5045_50451301_91_dialog_content = "There's an address on the back of this photo that we haven't fully investigated yet.",
  ui_story_5045_50451301_92_dialog_content = "Oh! That's right, you just reminded me. I invited a witness!",
  ui_story_5045_50451301_93_dialog_content = "When did you invite a witness? Was it also during your dream?",
  ui_story_5045_50451301_94_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451301_95_dialog_content = "Now, I'd like to ask witness <color=#1875ad>Michenny</color> to take the stand.",
  ui_story_5045_50451301_96_dialog_content = "Good morning, everyone. I'm the tax collector, Michenny.",
  ui_story_5045_50451301_97_dialog_content = "Do you recognize the handwritten address on the back of this photo?",
  ui_story_5045_50451301_98_dialog_content = "This is a new type of organization that provides <color=#1875ad>insurance services</color>.",
  ui_story_5045_50451301_99_dialog_content = "Bacon, the plaintiff in this case, bought <color=#1875ad>life insurance</color> for himself from this insurance agency.",
  ui_story_5045_50451301_100_dialog_content = "If Bacon falls victim to accidental death or injury, a <color=#1875ad>huge claim</color> can be made to the insurance agency.",
  ui_story_5045_50451301_101_dialog_content = "If that happens, who stands to receive the payout?",
  ui_story_5045_50451301_102_dialog_content = "According to the agency, this information is confidential.",
  ui_story_5045_50451301_103_dialog_content = "But if this information is vital to the case, the law states that we're entitled to this information.",
  ui_story_5045_50451301_104_dialog_content = "Very well... Many thanks!",
  ui_story_5045_50451301_105_dialog_content = "Well, I'll take my leave then.",
  ui_story_5045_50451301_106_dialog_content = "Your Honor, what do you mean by this?",
  ui_story_5045_50451301_107_dialog_content = "Could it really be that... Bacon prepared all of these pills for himself?",
  ui_story_5045_50451301_108_dialog_content = "He planned on leaving a huge insurance payout to someone?",
  ui_story_5045_50451301_109_dialog_content = "Bacon, do you realize that this kind of behavior could land you in prison?",
  ui_story_5045_50451301_110_dialog_content = "They say that being sent to Lumopolis Prison is a fate worse than death.",
  ui_story_5045_50451301_111_dialog_content = "...",
  ui_story_5045_50451301_112_dialog_content = "I...",
  ui_story_5045_50451301_113_dialog_content = "Don't worry. If you confess now, we will deal with you leniently.",
  ui_story_5045_50451301_114_dialog_content = "Bacon, what were you planning?",
  ui_story_5045_50451301_115_dialog_content = "Tell the judge quickly. This is the last thing I'll ever ask of you as your wife.",
  ui_story_5045_50451301_116_dialog_content = "Fanny, I'm sorry.",
  ui_story_5045_50451301_117_dialog_content = "I planned for so long, cheated myself, and even cheated you, but in the end... I still failed.",
  ui_story_5045_50451301_118_dialog_content = "What have you done...?",
  ui_story_5045_50451301_119_dialog_content = "Your Honor, I was a gardener, working for a noble household.",
  ui_story_5045_50451301_120_dialog_content = "It was because I accidentally broke the master's beloved porcelain plate that I was fired.",
  ui_story_5045_50451301_121_dialog_content = "Because of this, I became a laughing stock among the servants, and no one would even think of hiring me...",
  ui_story_5045_50451301_122_dialog_content = "I hid away at home, increasingly afraid to leave the house, and with no hope for the future.",
  ui_story_5045_50451301_123_dialog_content = "After this, as our debts accrued, Fanny began working harder and harder.",
  ui_story_5045_50451301_124_dialog_content = "It should be me to protect Fanny—protect our home—but I couldn't do a thing...",
  ui_story_5045_50451301_125_dialog_content = "That's when I came across that new insurance agency.",
  ui_story_5045_50451301_126_dialog_content = "I was thinking that instead of being a burden on Fanny, it would be better if...",
  ui_story_5045_50451301_127_dialog_content = "You fool! I've never thought of you as a burden! Never!",
  ui_story_5045_50451301_128_dialog_content = "It's all because I was too greedy.",
  ui_story_5045_50451301_129_dialog_content = "I thought that if I divorced Fanny, I could take on all of our debt.",
  ui_story_5045_50451301_130_dialog_content = "Then, after my death, the debt would also be written off.",
  ui_story_5045_50451301_131_dialog_content = "In the end, it turns out I'm too useless to even do this much.",
  ui_story_5045_50451301_132_dialog_content = "Bacon, let me tell you something.",
  ui_story_5045_50451301_133_dialog_content = "If you were to end your own life, the insurance company would deny the claim.",
  ui_story_5045_50451301_134_dialog_content = "R-Really!?",
  ui_story_5045_50451301_135_dialog_content = "If you were to do such a thing, you would only leave Fanny with a ton of debt and endless sorrow.",
  ui_story_5045_50451301_136_dialog_content = "Heavens, what have I done?",
  ui_story_5045_50451301_137_dialog_content = "Fanny, I'm sorry! I'm sorry...",
  ui_story_5045_50451301_138_dialog_content = "In the end, I still failed to give you a happy life.",
  ui_story_5045_50451301_139_dialog_content = "Bacon, what are you talking about?",
  ui_story_5045_50451301_140_dialog_content = "I have always been happy with you.",
  ui_story_5045_50451301_141_dialog_content = "...",
  ui_story_5045_50451301_142_dialog_content = "Remember the clay plate we made ourselves?",
  ui_story_5045_50451301_143_dialog_content = "I remember that <color=#1875ad>clay plate</color>!",
  ui_story_5045_50451301_144_dialog_content = "PlayerName, don't make this any more of a mess than it already is.",
  ui_story_5045_50451301_145_dialog_content = "Sorry, but I think...",
  ui_story_5045_50451301_146_dialog_content = "Is this the broken plate?",
  ui_story_5045_50451301_147_dialog_content = "I remember, it was from when we got married...",
  ui_story_5045_50451301_148_dialog_content = "Uh, is Bacon about to recall the joy of their whole honeymoon period here in the court?",
  ui_story_5045_50451301_149_dialog_content = "Hush!",
  ui_story_5045_50451301_150_dialog_content = "I'm sorry...",
  ui_story_5045_50451301_151_dialog_content = "Fanny, what are you apologizing for?",
  ui_story_5045_50451301_152_dialog_content = "I wanted to surprise you with dinner, but I accidentally broke our plates...",
  ui_story_5045_50451301_153_dialog_content = "Hahaha! Why did you apologize for that?",
  ui_story_5045_50451301_154_dialog_content = "I can't even remember how long those plates had been used. It's about time we replaced them.",
  ui_story_5045_50451301_155_dialog_content = "But... we don't have any money right now.",
  ui_story_5045_50451301_156_dialog_content = "We can make some ourselves.",
  ui_story_5045_50451301_157_dialog_content = "Ourselves? How?",
  ui_story_5045_50451301_158_dialog_content = "Follow me!",
  ui_story_5045_50451301_159_dialog_content = "Hahaha, I thought Bacon had met a shopkeeper who could help us with some plates.",
  ui_story_5045_50451301_160_dialog_content = "Unexpectedly, he took me into the wilderness.",
  ui_story_5045_50451301_161_dialog_content = "Pointing at clay from the river, he said he would perform some magic for me.",
  ui_story_5045_50451301_162_dialog_content = "We can mold this clay into whatever shape we want, then bake it in the fire....",
  ui_story_5045_50451301_163_dialog_content = "... and we'll have our very own plates.",
  ui_story_5045_50451301_164_dialog_content = "Wow, my husband is amazing!",
  ui_story_5045_50451301_165_dialog_content = "Heh, although this plate is a little ugly.",
  ui_story_5045_50451301_166_dialog_content = "Mine looks worse.",
  ui_story_5045_50451301_167_dialog_content = "But these are our unique clay plates! No matter how much those nobles want them, they can't have them!",
  ui_story_5045_50451301_168_dialog_content = "At that time, we had nothing, but we were so happy.",
  ui_story_5045_50451301_169_dialog_content = "Now we have our own house, although we're in debt...",
  ui_story_5045_50451301_170_dialog_content = "But we can still be healthy and happy together, which is something no amount of Nightium can buy!",
  ui_story_5045_50451301_171_dialog_content = "Fanny...",
  ui_story_5045_50451301_172_dialog_content = "Everything is going to be okay.",
  ui_story_5045_50451301_173_dialog_content = "This is the truth you taught me and made me believe through your actions.",
  ui_story_5045_50451301_174_dialog_content = "Will you believe me this time, Bacon?",
  ui_story_5045_50451301_175_dialog_content = "... Yes.",
  ui_story_5045_50451301_176_dialog_content = "It seems that this case has already reached its conclusion.",
  ui_story_5045_50451301_177_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451301_178_dialog_content = "White Night up high. It is time for the verdict!",
  ui_story_5045_50451301_179_dialog_content = "Firstly, Bacon and Fanny, through the course of this trial, proved the love that exists between them.",
  ui_story_5045_50451301_180_dialog_content = "Secondly, although Bacon intended to commit insurance fraud, he shall be given a lighter punishment, as he did not execute his plan and showed the sincerity of his repentance.",
  ui_story_5045_50451301_181_dialog_content = "Therefore, we have come to the following judgment!",
  ui_story_5045_50451301_182_dialog_content = "The marriage status of Bacon and Fanny will continue unaltered.",
  ui_story_5045_50451301_183_dialog_content = "Bacon's accumulated medicine will be confiscated. He'll be made to see a doctor regularly and take his medicine in the days following these visits.",
  ui_story_5045_50451301_184_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451301_185_dialog_content = "The trial is over!",
  ui_story_5045_50451401_1_dialog_content = "<color=#737378>Time: 2:00 PM</color>",
  ui_story_5045_50451401_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50451401_3_dialog_content = "Yawn—",
  ui_story_5045_50451401_4_dialog_content = "You're awake?",
  ui_story_5045_50451401_5_dialog_content = "I've picked out some case summaries. Tina, let's see which case we should look at first.",
  ui_story_5045_50451401_6_dialog_content = "Not bad, PlayerName.",
  ui_story_5045_50451401_7_dialog_content = "You're very proactive in your work. Perhaps you should stay and be my assistant in the future.",
  ui_story_5045_50451401_8_dialog_content = "Erm...",
  ui_story_5045_50451401_9_dialog_content = "Your Honor.",
  ui_story_5045_50451401_10_dialog_content = "Eh!?",
  ui_story_5045_50451401_11_dialog_content = "Bacon? And Fanny too? What are you doing back here?",
  ui_story_5045_50451401_12_dialog_content = "Has another problem cropped up?",
  ui_story_5045_50451401_13_dialog_content = "Nothing like that, Your Honor. We're here to thank you both.",
  ui_story_5045_50451401_14_dialog_content = "After the trial, it was like I had just awakened from a dream...",
  ui_story_5045_50451401_15_dialog_content = "I realized that I nearly made a big mistake, and I also caused you two a lot of trouble.",
  ui_story_5045_50451401_16_dialog_content = "You're welcome. It was our honor to help you.",
  ui_story_5045_50451401_17_dialog_content = "And I don't feel as though you brought us any trouble at all!",
  ui_story_5045_50451401_18_dialog_content = "(Because I did all the hard work...)",
  ui_story_5045_50451401_19_dialog_content = "PlayerName, do you have anything you wish to say to Bacon?",
  ui_story_5045_50451401_20_dialog_content = "Oh, right, I wanted to <color=#1875ad>tell</color> you something...",
  ui_story_5045_50451401_21_dialog_content = "The case is over. Why are you still asking about this?",
  ui_story_5045_50451401_22_dialog_content = "Raphael has been worried about you.",
  ui_story_5045_50451401_23_dialog_content = "Although Raphael looks like a child, and her treatment techniques may seem a little crude...",
  ui_story_5045_50451401_24_dialog_content = "But her medical skills are excellent!",
  ui_story_5045_50451401_25_dialog_content = "I understand... I'll apologize to Dr. Raphael too.",
  ui_story_5045_50451401_26_dialog_content = "If she's willing to give me another chance, I'll accept her treatment.",
  ui_story_5045_50451401_27_dialog_content = "Bacon, Fanny—what are your plans for the future?",
  ui_story_5045_50451401_28_dialog_content = "I'm not sure, but we're going to try doing some part-time work together first and pay off our debts little by little.",
  ui_story_5045_50451401_29_dialog_content = "Also, going to the <color=#1875ad>self-help course</color> might help me find a new direction in life.",
  ui_story_5045_50451401_30_dialog_content = "That sounds very encouraging!",
  ui_story_5045_50451401_31_dialog_content = "But what's with all this luggage? Are you moving house?",
  ui_story_5045_50451401_32_dialog_content = "These are our pottery tools.",
  ui_story_5045_50451401_33_dialog_content = "We're heading to the countryside later to make some new plates.",
  ui_story_5045_50451401_34_dialog_content = "Wow! Reliving the good old days?",
  ui_story_5045_50451401_35_dialog_content = "Ahem... You could say that.",
  ui_story_5045_50451401_36_dialog_content = "I am to blame for breaking our most precious memento.",
  ui_story_5045_50451401_37_dialog_content = "It's only right that I make up for it.",
  ui_story_5045_50451401_38_dialog_content = "That's so sweet!",
  ui_story_5045_50451401_39_option_content = "Is that a hint of envy I detect, Tina?",
  ui_story_5045_50451401_40_dialog_content = "Hmm... Is there something strange about admiring the beauty of love?",
  ui_story_5045_50451401_41_dialog_content = "If Your Honors don't mind, we'll make some more small plates for the two of you!",
  ui_story_5045_50451401_42_dialog_content = "We would love that, but as judges, we can't accept gifts from our clients.",
  ui_story_5045_50451401_43_dialog_content = "The clay plates we make are of very little value...",
  ui_story_5045_50451401_44_dialog_content = "We appreciate your kindness, but in my opinion, your plates are priceless.",
  ui_story_5045_50451401_45_dialog_content = "Thank you, Your Honor... Well then, we've taken up enough of your time.",
  ui_story_5045_50451401_46_dialog_content = "Sigh, I really hope that one day, my sweetheart will take me out to do something just as romantic.",
  ui_story_5045_50451401_47_dialog_content = "But it's still work time, PlayerName, get back to your work...",
  ui_story_5045_50451401_47X1_dialog_content = "As partners, there's room for our <color=#1875ad>Rapport</color> to improve!",
  ui_story_5045_50451401_48_dialog_content = "What about you?",
  ui_story_5045_50451401_49_dialog_content = "I need to catch up on some sleep, of course. There might be some sweet dreams waiting for me if I fall asleep with a happy heart!",
  ui_story_5045_50451401_50_dialog_content = "What—?!",
  ui_story_5045_50451401_51_option_content = "Let's go together!",
  ui_story_5045_50451401_52_dialog_content = "Huh?",
  ui_story_5045_50451401_53_dialog_content = "Ah, sorry... I forgot it's still work time.",
  ui_story_5045_50451401_54_dialog_content = "Then let's get going!",
  ui_story_5045_50451401_55_dialog_content = "Alright, I'll just—",
  ui_story_5045_50451401_56_dialog_content = "Huh? She's gone?",
  ui_story_5045_50451401_57_dialog_content = "<color=#737378>Time: 9:00 PM</color>",
  ui_story_5045_50451401_58_dialog_content = "<color=#737378>Location: Lumopolis Outskirts</color>",
  ui_story_5045_50451401_59_dialog_content = "Once you're all ready, you can put it into the fire to bake it.",
  ui_story_5045_50451401_60_dialog_content = "Tina, what are you making?",
  ui_story_5045_50451401_61_dialog_content = "Wait a second, I'll show you soon enough.",
  ui_story_5045_50451401_62_dialog_content = "Don't worry about it, mine looks awful. I promise I won't laugh at yours.",
  ui_story_5045_50451401_63_dialog_content = "I'm very satisfied with my masterpiece, I just haven't finished it yet—",
  ui_story_5045_50451401_64_dialog_content = "Heh... Hahaha!",
  ui_story_5045_50451401_65_dialog_content = "W-What is it?",
  ui_story_5045_50451401_66_dialog_content = "PlayerName, your plate really is awful, and your face is covered in clay.",
  ui_story_5045_50451401_67_dialog_content = "Were you trying to turn yourself into a clay sculpture?",
  ui_story_5045_50451401_68_dialog_content = "R-Really? I didn't even notice...",
  ui_story_5045_50451401_69_dialog_content = "But I could say the same about you...",
  ui_story_5045_50451401_70_dialog_content = "What!?",
  ui_story_5045_50451401_71_dialog_content = "It doesn't matter. Looks aren't important as long as it's for my masterpiece!",
  ui_story_5045_50451401_72_dialog_content = "That thing you're holding is your... masterpiece?",
  ui_story_5045_50451401_73_dialog_content = "That's right, heehee!",
  ui_story_5045_50451401_74_dialog_content = "I don't get it... What is it supposed to be?",
  ui_story_5045_50451401_75_dialog_content = "What is there not to get? Look carefully...",
  ui_story_5045_50451401_76_dialog_content = "This is a boy and this is a girl.",
  ui_story_5045_50451401_77_dialog_content = "They love each other deeply. Looking into each other's eyes affectionately, they wish to offer the sweetest kiss to one another...",
  ui_story_5045_50451401_78_dialog_content = "Ahem... I made this small ornament, especially for the Romance Division.",
  ui_story_5045_50451401_79_dialog_content = "So, it's supposed to be two clay figurines...",
  ui_story_5045_50451401_80_dialog_content = "These two little clay figurines are so cute. Why didn't I think of making some small ornaments?",
  ui_story_5045_50451401_81_dialog_content = "You know, this little clay figurine looks a little familiar...",
  ui_story_5045_50451401_82_dialog_content = "Haha, don't you think they look like the two judges?",
  ui_story_5045_50451401_83_dialog_content = "What?",
  ui_story_5045_50451401_84_option_content = "I don't think so.",
  ui_story_5045_50451401_85_dialog_content = "That's right, they're not us!",
  ui_story_5045_50451401_86_dialog_content = "They're just a random little boy and girl I casually put together.",
  ui_story_5045_50451401_87_dialog_content = "I hope that all lovers in Lumopolis will be blessed by the God of Light.",
  ui_story_5045_50451401_88_dialog_content = "At least then the Romance Division wouldn't be as dreadfully busy as it is now...",
  ui_story_5045_50451401_89_dialog_content = "If we're so busy, why did you take me out to mess about in the countryside?",
  ui_story_5045_50451401_90_dialog_content = "Because...",
  ui_story_5045_50451401_91_dialog_content = "Huh? Because what?",
  ui_story_5045_50451401_92_option_content = "I can see the resemblance.",
  ui_story_5045_50451401_93_dialog_content = "Really?",
  ui_story_5045_50451401_94_dialog_content = "Where!? I-I don't see it!",
  ui_story_5045_50451401_95_dialog_content = "Who are they supposed to be then?",
  ui_story_5045_50451401_96_dialog_content = "No one in particular.",
  ui_story_5045_50451401_97_dialog_content = "These two clay figurines are abstract incarnations of all the world's lovers!",
  ui_story_5045_50451401_98_dialog_content = "I just want everyone to experience a truly beautiful love.",
  ui_story_5045_50451401_99_dialog_content = "I hope they last a long, long time.",
  ui_story_5045_50451401_100_dialog_content = "Tina, you really love working in the Romance Division, don't you...",
  ui_story_5045_50451401_101_dialog_content = "To tell the truth, it doesn't matter where I work.",
  ui_story_5045_50451401_102_dialog_content = "However, I can't deny that my recent cases in the Romance Division are really more interesting than anything I've encountered before.",
  ui_story_5045_50451401_103_dialog_content = "If it were not for your help...",
  ui_story_5045_50451401_104_dialog_content = "I might not have known how to handle the cases of the Romance Division.",
  ui_story_5045_50451401_105_dialog_content = "Why do you say that? You're a phenomenal judge.",
  ui_story_5045_50451401_106_dialog_content = "But my understanding of love was severely deficient.",
  ui_story_5045_50451401_107_dialog_content = "I always liked people for no apparent reason, but in the end, I realized that I just liked the impression of them I had formed in my imagination.",
  ui_story_5045_50451401_108_dialog_content = "It seems like such a silly sentiment now.",
  ui_story_5045_50451401_109_dialog_content = "True love...",
  ui_story_5045_50451401_110_dialog_content = "It's helping each other out through thick and thin, battling the mundanity of life.",
  ui_story_5045_50451401_111_dialog_content = "It is the need to take care of each other, rather than make each other surrender to submission.",
  ui_story_5045_50451401_112_dialog_content = "Right. We have Fanny and Bacon to thank for teaching us this.",
  ui_story_5045_50451401_113_dialog_content = "I'd also like to thank you, PlayerName.",
  ui_story_5045_50451401_114_dialog_content = "You helped me to see it...",
  ui_story_5045_50451401_115_dialog_content = "Huh? See what?",
  ui_story_5045_50451401_116_dialog_content = "Zzz...",
  ui_story_5045_50451401_117_dialog_content = "She's sleeping?",
  ui_story_5045_50451401_118_dialog_content = "What was Tina about to say?",
  ui_story_5045_50451401_119_dialog_content = "I guess I won't be getting any answers today... Good night, then.",
  ui_story_5045_50451401_120_dialog_content = "...",
  ui_story_5045_50451401_121_dialog_content = "I think Tina is dreaming.",
  ui_story_5045_50451401_122_dialog_content = "PlayerName, remember to help me put my masterpiece away!",
  ui_story_5045_50451401_123_dialog_content = "O-Okay!",
  ui_story_5045_50451401_124_dialog_content = "Huh? Is she just talking in her sleep?",
  ui_story_5045_50451401_125_dialog_content = "Tina really doesn't laze around when she's dreaming...",
  ui_story_5045_50451501_1_dialog_content = "<color=#737378>Time: 3:00 PM</color>",
  ui_story_5045_50451501_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50451501_3_dialog_content = "(I never thought I'd finish a case so soon.)",
  ui_story_5045_50451501_4_dialog_content = "(My legal abilities can't be better than my psychic abilities, can they?)",
  ui_story_5045_50451501_5_dialog_content = "(If Irridon saw our trial, she might think about paying me more.)",
  ui_story_5045_50451501_6_dialog_content = "(When the time comes, heh, I'll give Vice and the others a surprise!)",
  ui_story_5045_50451501_7_dialog_content = "(But then again...)",
  ui_story_5045_50451501_8_dialog_content = "Why are so many people filing today!?",
  ui_story_5045_50451501_9_dialog_content = "Huh? Lost interest in trial work so soon?",
  ui_story_5045_50451501_10_dialog_content = "N-No way!",
  ui_story_5045_50451501_11_dialog_content = "Ah, what brings our ever-busy Lady Irridon here?",
  ui_story_5045_50451501_12_dialog_content = "Zzz...",
  ui_story_5045_50451501_13_dialog_content = "Tina, wake up!",
  ui_story_5045_50451501_14_dialog_content = "Right...",
  ui_story_5045_50451501_15_dialog_content = "Angel, what are you waiting for? Go and make some tea for our esteemed chief judge!",
  ui_story_5045_50451501_16_dialog_content = "... Oh.",
  ui_story_5045_50451501_17_dialog_content = "There's no need.",
  ui_story_5045_50451501_18_dialog_content = "I heard that you tried a case this morning, so I came to assess the aftermath.",
  ui_story_5045_50451501_19_dialog_content = "The case was conducted by the book.",
  ui_story_5045_50451501_20_dialog_content = "On the contrary, my trial tomorrow will inspire the world and become a precedent for future generations to learn from and imitate.",
  ui_story_5045_50451501_21_dialog_content = "When the time comes, feel free to come again and witness it for yourself.",
  ui_story_5045_50451501_22_dialog_content = "We'll see. Perhaps, if I have time.",
  ui_story_5045_50451501_23_dialog_content = "I just heard that the case this morning caused quite a stir. I want to know the specifics.",
  ui_story_5045_50451501_24_dialog_content = "Lady Irridon, PlayerName and I tried this morning's case.",
  ui_story_5045_50451501_25_dialog_content = "I recorded the details and the trial process in this notebook. Please have a look.",
  ui_story_5045_50451501_26_dialog_content = "Impressive. You have formed some good habits since arriving here, PlayerName.",
  ui_story_5045_50451501_27_dialog_content = "Did you just say that this case caused a stir?",
  ui_story_5045_50451501_28_dialog_content = "Yes.",
  ui_story_5045_50451501_29_dialog_content = "So, how does public opinion currently stand regarding this case?",
  ui_story_5045_50451501_30_dialog_content = "What do you think?",
  ui_story_5045_50451501_31_dialog_content = "Well... I'm guessing it must be pretty positive, no?",
  ui_story_5045_50451501_32_dialog_content = "PlayerName has proven himself worthy of being personally chosen by you, Chief Judge, to assist us here.",
  ui_story_5045_50451501_33_dialog_content = "With the help of PlayerName, it's only natural that Tina should make some progress too.",
  ui_story_5045_50451501_34_dialog_content = "Maybe it won't be long before she becomes the second-best judge in the Romance Division!",
  ui_story_5045_50451501_35_dialog_content = "Tina, are PlayerName's records complete?",
  ui_story_5045_50451501_36_dialog_content = "Yes, I made PlayerName write down everything in detail.",
  ui_story_5045_50451501_37_dialog_content = "The investigation only scratched the surface, and the parties were not allowed to fully explain themselves in court...",
  ui_story_5045_50451501_38_dialog_content = "Tina, have you been sleeping in the court?",
  ui_story_5045_50451501_39_dialog_content = "I-I haven't done anything of the sort... Yawn—",
  ui_story_5045_50451501_40_dialog_content = "I was struggling against a bout of drowsiness this morning, so I was sleeping until just now.",
  ui_story_5045_50451501_41_dialog_content = "The Romance Division has only just been established, and there are no cases for us to learn from.",
  ui_story_5045_50451501_42_dialog_content = "I understand the pressure.",
  ui_story_5045_50451501_43_dialog_content = "But please remember that even a small case in our eyes may affect the lives of the parties concerned.",
  ui_story_5045_50451501_44_dialog_content = "The way you deal with each case will affect the attitude the people of Lumopolis hold toward romantic relationships in the future.",
  ui_story_5045_50451501_45_dialog_content = "It seems public opinion as a result of taking up the case this morning is not very good...",
  ui_story_5045_50451501_46_dialog_content = "Those who advocate freedom in love and marriage are very dissatisfied with the trial this morning.",
  ui_story_5045_50451501_47_dialog_content = "We may see retaliatory appeals against the Hall of Justice in the near future.",
  ui_story_5045_50451501_48_dialog_content = "Prepare yourselves.",
  ui_story_5045_50451501_49_dialog_content = "Retaliatory appeals?",
  ui_story_5045_50451501_50_dialog_content = "We may even see people intentionally marrying and then suing for divorce.",
  ui_story_5045_50451501_51_dialog_content = "Since Tina's the one who stirred up all this trouble, let Tina handle such appeals by herself.",
  ui_story_5045_50451501_52_dialog_content = "Zzz...",
  ui_story_5045_50451501_53_dialog_content = "Well, it seems Tina approves.",
  ui_story_5045_50451501_54_dialog_content = "Huh? W-Wait...",
  ui_story_5045_50451501_55_dialog_content = "So, essentially, I have to deal with all of the divorce cases that come through here?",
  ui_story_5045_50451501_56_dialog_content = "How many sessions will it take to complete each trial?",
  ui_story_5045_50451601_1_dialog_content = "<color=#737378>Time: 3:00 PM</color>",
  ui_story_5045_50451601_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Courtroom</color>",
  ui_story_5045_50451601_3_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451601_4_dialog_content = "<size=45>Court is in session!</size>",
  ui_story_5045_50451601_5_dialog_content = "First of all, let's hear what the plaintiff has to say.",
  ui_story_5045_50451601_6_dialog_content = "Hmm? And who are you?",
  ui_story_5045_50451601_7_dialog_content = "Can you really do a good job of trying my case?",
  ui_story_5045_50451601_8_dialog_content = "Order!",
  ui_story_5045_50451601_9_dialog_content = "Please do not raise questions irrelevant to this case.",
  ui_story_5045_50451601_10_dialog_content = "Such impudence!",
  ui_story_5045_50451601_11_dialog_content = "Do you know who I am? Where does a pathetic little judge like you get the right to talk to me like that?",
  ui_story_5045_50451601_12_dialog_content = "I should report you to Irridon!",
  ui_story_5045_50451601_13_dialog_content = "I'm a probationary judge, personally appointed by Chief Judge Irridon.",
  ui_story_5045_50451601_14_dialog_content = "Please cooperate in maintaining order in the Hall of Justice.",
  ui_story_5045_50451601_15_dialog_content = "Hmph! Just you wait!",
  ui_story_5045_50451601_16_dialog_content = "Huh? Plaintiff, where are you going?",
  ui_story_5045_50451601_17_dialog_content = "<color=#737378>Time: 4:00 PM</color>",
  ui_story_5045_50451601_18_dialog_content = "<color=#737378>Location: Lumo Hall of Justice</color>",
  ui_story_5045_50451601_19_dialog_content = "Lady Irridon, you've been looking for me?",
  ui_story_5045_50451601_20_dialog_content = "PlayerName, are you aware that someone has filed a complaint against you?",
  ui_story_5045_50451601_21_dialog_content = "Huh? Did that guy really complain about me just now?",
  ui_story_5045_50451601_22_dialog_content = "But I don't think I've said anything wrong. He showed a complete lack of respect for the order of the Hall of Justice!",
  ui_story_5045_50451601_23_dialog_content = "He has his problems. Naturally, this is something I understand all too well.",
  ui_story_5045_50451601_24_dialog_content = "But you...",
  ui_story_5045_50451601_25_dialog_content = "I asked you to go to the Romance Division to help, but I didn't give you permission to hear cases by yourself.",
  ui_story_5045_50451601_26_dialog_content = "I-I don't think it's that difficult, so perhaps, maybe I can...",
  ui_story_5045_50451601_27_dialog_content = "If it were that easy to become a real judge, even Angel would have passed the mock trial examination.",
  ui_story_5045_50451601_28_dialog_content = "I admit that you have a gift.",
  ui_story_5045_50451601_29_dialog_content = "But this does not mean that you can skip the learning stage and become a judge right away.",
  ui_story_5045_50451601_30_dialog_content = "Even a genius born into a family of judges should start out as an assistant magistrate.",
  ui_story_5045_50451601_31_dialog_content = "I'm sorry...",
  ui_story_5045_50451601_32_dialog_content = "I-I understand. I'll go back and work even harder as an assistant now!",
  ui_story_5045_50451601_33_dialog_content = "...",
  ui_story_5045_50451601_34_dialog_content = "There's no need for that.",
  ui_story_5045_50451601_35_dialog_content = "Really?",
  ui_story_5045_50451601_36_dialog_content = "In order to prevent this matter from fermenting to the point where the public misunderstands the intentions of the Hall of Justice...",
  ui_story_5045_50451601_37_dialog_content = "I'm very sorry, PlayerName, but you can no longer continue working in the Hall of Justice.",
  ui_story_5045_50451601_38_dialog_content = "Well, then what about my payment...?",
  ui_story_5045_50451601_39_dialog_content = "The Hall of Justice had to pay a large sum to appease the complainant just now.",
  ui_story_5045_50451601_40_dialog_content = "Your payment is far from enough to even cover this compensation.",
  ui_story_5045_50451601_41_dialog_content = "But as I have my own responsibility to bear in this matter, I'll not ask you to pay any additional fees for said compensation.",
  ui_story_5045_50451601_42_dialog_content = "If you are willing to attend any of the trials here, the doors of the Hall of Justice are still open to you.",
  ui_story_5045_50451601_43_dialog_content = "Hmm...",
  ui_story_5045_50451601_44_dialog_content = "M-My payment...",
  ui_story_5045_50451601_45_dialog_content = "If I had known this would happen, I would have been their assistant and nothing more!",
  ui_story_5045_50451601_46_dialog_content = "And as for this notebook... I'm afraid you can't keep it.",
  ui_story_5045_50451601_47_dialog_content = "I took the liberty of picking it up, since I'm already here.",
  ui_story_5045_50451601_48_dialog_content = "Lady Irridon, d-don't go...",
  ui_story_5045_50451601_49_dialog_content = "This time...",
  ui_story_5045_50451601_50_dialog_content = "I really messed up big this time...",
  ui_story_5045_50451701_1_dialog_content = "<color=#737378>Time: 8:00 AM</color>",
  ui_story_5045_50451701_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50451701_3_dialog_content = "Marriage should be arranged by the family. This is the responsibility of the nobility!",
  ui_story_5045_50451701_4_dialog_content = "If your family arranged for you to marry a slovenly wife who refused to bathe, would you accept your fate?",
  ui_story_5045_50451701_5_dialog_content = "I believe that my family would never find such a wife for me.",
  ui_story_5045_50451701_6_dialog_content = "But you cannot be sure of that.",
  ui_story_5045_50451701_7_dialog_content = "In the end, you all just want to maximize your interests and estates and not care about the feelings of the concerned party!",
  ui_story_5045_50451701_8_dialog_content = "I am the judge presiding over this case! Everyone must respect my judgment!",
  ui_story_5045_50451701_9_dialog_content = "If your judgment is wrong, I'll be the one to get scolded as you are...",
  ui_story_5045_50451701_10_dialog_content = "What's going on with Matthieu and Angel?",
  ui_story_5045_50451701_11_dialog_content = "Obviously, they cannot agree on the case currently at trial.",
  ui_story_5045_50451701_12_dialog_content = "Why are they still fighting? Some people are trying to sleep here—Yawn—",
  ui_story_5045_50451701_13_dialog_content = "Unless someone does something about this, they're gonna keep fighting until the sun goes down...",
  ui_story_5045_50451701_14_dialog_content = "How about we ask what's going on? Maybe we can help.",
  ui_story_5045_50451701_15_dialog_content = "If you say so, PlayerName...",
  ui_story_5045_50451701_16_dialog_content = "Well, we can't just sit back and do nothing.",
  ui_story_5045_50451701_17_dialog_content = "So... Matthieu, Angel, what's the case all about?",
  ui_story_5045_50451701_18_dialog_content = "You're just in time. Please listen to me and tell me if my judgment is reasonable.",
  ui_story_5045_50451701_19_dialog_content = "The only daughter of a great noble is suing her parents, claiming that they have interfered with her freedom to love.",
  ui_story_5045_50451701_20_dialog_content = "I felt that the case was not as simple as it seemed, so I brought Angel to visit them and gather evidence.",
  ui_story_5045_50451701_21_dialog_content = "It turns out that their only daughter has fallen in love with a poor boy who doesn't even have a decent job.",
  ui_story_5045_50451701_22_dialog_content = "No, it was those noble parents who deliberately made him lose his job! He used to be a good cook.",
  ui_story_5045_50451701_23_dialog_content = "Didn't we confirm this through our investigation?",
  ui_story_5045_50451701_24_dialog_content = "But he's a commoner. There's no way he approached a noble girl without other intention!",
  ui_story_5045_50451701_25_dialog_content = "I disagree!",
  ui_story_5045_50451701_26_dialog_content = "This noble girl is willing to give up all her wealth for him...",
  ui_story_5045_50451701_27_dialog_content = "He also wants to give up pursuing her in order not to jeopardize the noble girl's future.",
  ui_story_5045_50451701_28_dialog_content = "This is a pure love.",
  ui_story_5045_50451701_29_dialog_content = "As you said, the poor boy finally realized the distance between their circumstances and was willing to give up this relationship.",
  ui_story_5045_50451701_30_dialog_content = "So I judged that the noble parents were right. Is there any problem with this?",
  ui_story_5045_50451701_31_dialog_content = "It sounds really complicated...",
  ui_story_5045_50451701_32_dialog_content = "Huh? What's this on the ground?",
  ui_story_5045_50451701_33_dialog_content = "I think I've seen this somewhere before?",
  ui_story_5045_50451701_34_dialog_content = "Oh, I guess not. But I remember...",
  ui_story_5045_50451701_35_dialog_content = "I remember that after the investigation, I definitely returned this to Sophie...",
  ui_story_5045_50451701_36_dialog_content = "I supposed I didn't notice before, but this <color=#1875ad>attendance card</color> is identical to Bacon's!",
  ui_story_5045_50451701_37_dialog_content = "I definitely returned this to Bacon after the investigation...",
  ui_story_5045_50451701_38_dialog_content = "I supposed I didn't notice before, but this <color=#1875ad>attendance card</color> is identical to Sophie's!",
  ui_story_5045_50451701_39_dialog_content = "But...",
  ui_story_5045_50451701_40_dialog_content = "Sorry, this is the evidence I just found! I didn't notice one of them before...",
  ui_story_5045_50451701_41_dialog_content = "Thank you, PlayerName. If someone had happened to pick it up, it would have been difficult to explain.",
  ui_story_5045_50451701_42_dialog_content = "Angel, you'd better finish your work and then we'll discuss how to judge this case.",
  ui_story_5045_50451701_43_dialog_content = "...",
  ui_story_5045_50451701_44_dialog_content = "Angel, whose attendance card is this?",
  ui_story_5045_50451701_45_dialog_content = "Eh? You're good! Just one look and you knew it was an attendance card?",
  ui_story_5045_50451701_46_dialog_content = "This is what we found in <color=#1875ad>Karl</color>'s house. According to him, he studied law in this self-help course...",
  ui_story_5045_50451701_47_dialog_content = "It seems he wants to change his current situation and strive to become a judge.",
  ui_story_5045_50451701_48_dialog_content = "No, there's something not right here...",
  ui_story_5045_50451701_49_dialog_content = "It's a card... It looks like some sort of attendance card.",
  ui_story_5045_50451701_50_dialog_content = "Oh, yes. I started taking some housekeeping lessons recently.",
  ui_story_5045_50451701_51_dialog_content = "Huh? What's this card here on the table?",
  ui_story_5045_50451701_52_dialog_content = "... That's from the <color=#1875ad>self-help course</color>. It's an attendance card.",
  ui_story_5045_50451701_53_dialog_content = "They help people develop their willpower so they no longer fear facing life's difficulties.",
  ui_story_5045_50451701_54_dialog_content = "I hear that a lot of the students who have taken this course have become Lumopolis' newest millionaires.",
  ui_story_5045_50451701_55_dialog_content = "Why are the courses everyone's talking about all different?",
  ui_story_5045_50451701_56_dialog_content = "Could it be...?",
  ui_story_5045_50451701_57_dialog_content = "<size=45>!!!</size>",
  ui_story_5045_50451701_58_dialog_content = "Matthieu, the name of the poor boy the noble girl fell in love with in your case...",
  ui_story_5045_50451701_59_dialog_content = "He's called Karl. Oh really, why must I be made to say the name of a commoner?",
  ui_story_5045_50451701_60_dialog_content = "I think I've met <color=#1875ad>Karl</color> somewhere before...",
  ui_story_5045_50451701_61_dialog_content = "That's not it! I remember...",
  ui_story_5045_50451701_62_dialog_content = "I remember Sophie's neighbor was called Karl!",
  ui_story_5045_50451701_63_dialog_content = "And Bacon and Fanny's friend was also called Karl...",
  ui_story_5045_50451701_64_dialog_content = "I remember! Karl was the name of Bacon and Fanny's friend!",
  ui_story_5045_50451701_65_dialog_content = "And I think Sophie's neighbor was also called Karl...",
  ui_story_5045_50451701_66_dialog_content = "Can it simply be a coincidence?",
  ui_story_5045_50451701_67_dialog_content = "PlayerName, what were you mumbling to yourself about just now?",
  ui_story_5045_50451701_68_dialog_content = "We really can't help with Matthieu's case.",
  ui_story_5045_50451701_69_dialog_content = "Let's try to deal with the cases we're responsible for right now.",
  ui_story_5045_50451701_70_dialog_content = "PlayerName, who are you going to help this time?",
  ui_story_5045_50451701_71_dialog_content = "Why don't we let PlayerName take turns helping us, just like the other day?",
  ui_story_5045_50451701_72_dialog_content = "That would be fair, no?",
  ui_story_5045_50451701_73_dialog_content = "Sorry, I want to go out for a while to investigate something...",
  ui_story_5045_50451701_74_dialog_content = "Huh? If you're not investigating the case, what are you investigating exactly?",
  ui_story_5045_50451701_75_dialog_content = "It's about that self-help course... It's probably nothing, hopefully I'm just thinking too much.",
  ui_story_5045_50451701_76_dialog_content = "<color=#737378>Time: 9:00 AM</color>",
  ui_story_5045_50451701_77_dialog_content = "<color=#737378>Location: Lumopolis, Lower Lumopolis</color>",
  ui_story_5045_50451701_78_dialog_content = "Karl!",
  ui_story_5045_50451701_79_dialog_content = "Huh? You are...",
  ui_story_5045_50451701_80_dialog_content = "Don't you remember me? I'm the assistant of the judges, PlayerName.",
  ui_story_5045_50451701_81_dialog_content = "We've met twice before.",
  ui_story_5045_50451701_82_dialog_content = "Oh, Your Honor! What can I do for you?",
  ui_story_5045_50451701_83_dialog_content = "Yes, actually—do you know where I can find that self-help course?",
  ui_story_5045_50451701_84_dialog_content = "How would I know?",
  ui_story_5045_50451701_85_dialog_content = "Because Fanny said you introduced her to it, so I thought you'd maybe know something about it.",
  ui_story_5045_50451701_86_dialog_content = "So, that's how it is—someone just mentioned it to me.",
  ui_story_5045_50451701_87_dialog_content = "I thought it was probably just some place selling peace of mind to desperate people.",
  ui_story_5045_50451701_88_dialog_content = "But for people who feel hopeless about their lives, peace of mind is exactly what they're lacking.",
  ui_story_5045_50451701_89_dialog_content = "... I see. Is there anything else you can tell me?",
  ui_story_5045_50451701_90_dialog_content = "Sorry, that's all I know.",
  ui_story_5045_50451701_91_dialog_content = "Alright, thanks for your time.",
  ui_story_5045_50451701_92_dialog_content = "I'll be off then. All the best.",
  ui_story_5045_50451701_93_dialog_content = "(There's definitely something off about this Karl.)",
  ui_story_5045_50451701_94_dialog_content = "(I'd better follow him and see where he's going. Maybe I'll find some more clues.)",
  ui_story_5045_50451701_95_dialog_content = "(But...)",
  ui_story_5045_50451701_96_dialog_content = "Where did he go? He just disappeared in the blink of an eye like that!",
  ui_story_5045_50451701_97_dialog_content = "<color=#737378>Sometime, Somewhere</color>",
  ui_story_5045_50451701_98_dialog_content = "What are you doing standing about like a dope for? Go find your target.",
  ui_story_5045_50451701_99_dialog_content = "B-But I...",
  ui_story_5045_50451701_100_dialog_content = "I don't want to do this!",
  ui_story_5045_50451701_101_dialog_content = "Sorry, Self-help Guru, forgive me!",
  ui_story_5045_50451701_102_dialog_content = "That's alright, I'm not forcing you.",
  ui_story_5045_50451701_103_dialog_content = "So... can I go home?",
  ui_story_5045_50451701_104_dialog_content = "Wait. Not so fast.",
  ui_story_5045_50451701_105_dialog_content = "Although you've only been here half a day, surely you can do one more thing for me?",
  ui_story_5045_50451701_106_dialog_content = "Otherwise, your wife may end up getting upset.",
  ui_story_5045_50451801_1_dialog_content = "<color=#737378>Time: 4:00 PM</color>",
  ui_story_5045_50451801_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50451801_3_dialog_content = "Back already, PlayerName?",
  ui_story_5045_50451801_4_dialog_content = "How is your investigation going?",
  ui_story_5045_50451801_5_dialog_content = "The lead was a dead end, but I still can't shake this uneasy feeling.",
  ui_story_5045_50451801_6_dialog_content = "By the way, where are Matthieu and Angel?",
  ui_story_5045_50451801_7_dialog_content = "It seems Matthieu wants to put this case on the back burner.",
  ui_story_5045_50451801_8_dialog_content = "Angel went with Matthieu to investigate another case. Don't worry about them—you'd better think about...",
  ui_story_5045_50451801_9_dialog_content = "Who do you plan on assisting today?",
  ui_story_5045_50451801_10_dialog_content = "I...",
  ui_story_5045_50451801_11_dialog_content = "Excuse me, is PlayerName here?",
  ui_story_5045_50451801_12_dialog_content = "Amy? Is there something I can help you with?",
  ui_story_5045_50451801_13_dialog_content = "I... I'm here to <color=#1875ad>arrest</color> you!",
  ui_story_5045_50451801_14_dialog_content = "Arrest me!? What for?",
  ui_story_5045_50451801_15_dialog_content = "Someone reported you to the Supreme Court, saying that you created an illegal organization in Lumopolis specializing in committing fraud.",
  ui_story_5045_50451801_16_dialog_content = "Because the scope of the alleged fraud is particularly vast and the nature is particularly severe...",
  ui_story_5045_50451801_17_dialog_content = "The Hall of Justice has decided to arrest you and start the trial tomorrow!",
  ui_story_5045_50451801_18_dialog_content = "This must be a mistake, no?",
  ui_story_5045_50451801_19_dialog_content = "PlayerName has been helping us with our work non-stop recently.",
  ui_story_5045_50451801_20_dialog_content = "There's no mistake. The plaintiff said the defendant was a Caelestite working in the Hall of Justice.",
  ui_story_5045_50451801_21_dialog_content = "Unless I'm mistaken, you're the only Caelestite around here.",
  ui_story_5045_50451801_22_dialog_content = "Um...",
  ui_story_5045_50451801_23_dialog_content = "<color=#737378>Time: 9:00 AM, The Next Day</color>",
  ui_story_5045_50451801_24_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Main Courtroom</color>",
  ui_story_5045_50451801_25_dialog_content = "(The Hall of Justice gallery is full of whispering audiences.)",
  ui_story_5045_50451801_26_dialog_content = "(Waves of disgusted eyes look like they're about to tear me apart.)",
  ui_story_5045_50451801_27_dialog_content = "(A few days ago, I was still a probationary judge sitting on the bench, but today...)",
  ui_story_5045_50451801_28_dialog_content = "(Leyn, Tina... They didn't come?)",
  ui_story_5045_50451801_29_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451801_30_dialog_content = "<size=45>White Night up high. Court is now in session!</size>",
  ui_story_5045_50451801_31_dialog_content = "White Night up high.",
  ui_story_5045_50451801_32_option_content = "White Night up high...",
  ui_story_5045_50451801_33_dialog_content = "I can't believe he actually said it! How dare he!",
  ui_story_5045_50451801_34_option_content = "I've been set up!",
  ui_story_5045_50451801_35_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451801_36_dialog_content = "The defendant is requested to observe the rules and regulations of the court.",
  ui_story_5045_50451801_37_dialog_content = "Please note that you will lose the opportunity to defend yourself after receiving three warnings.",
  ui_story_5045_50451801_38_dialog_content = "(I know the rules... Why did I suddenly forget myself just now!?)",
  ui_story_5045_50451801_39_option_content = "Objection!",
  ui_story_5045_50451801_40_dialog_content = "PlayerName, you have been working in the Hall of Justice for some time now.",
  ui_story_5045_50451801_41_dialog_content = "Do you still need me to teach you about the process and disciplinary measures practiced here in the Hall of Justice?",
  ui_story_5045_50451801_42_dialog_content = "(I remember the disciplinary measures, but being a defendant all of a sudden... Who wouldn't get a bit flustered...?)",
  ui_story_5045_50451801_43_dialog_content = "Now, let us invite the plaintiff <color=#1875ad>Bacon</color> to speak.",
  ui_story_5045_50451801_44_dialog_content = "Your Honor, I-I'm Bacon.",
  ui_story_5045_50451801_45_dialog_content = "(It's Bacon?!? Was he unhappy with the judgment Tina and I reached last time?)",
  ui_story_5045_50451801_46_dialog_content = "(But after the trial, we went into the countryside together. Everything was just fine then.)",
  ui_story_5045_50451801_47_dialog_content = "Today, I... wish to sue PlayerName on behalf of thousands of victims in Lumopolis.",
  ui_story_5045_50451801_48_dialog_content = "The reason for this is...",
  ui_story_5045_50451801_49_dialog_content = "His <color=#1875ad>self-help course</color> is supposedly a training program that teaches skills to people in need.",
  ui_story_5045_50451801_50_dialog_content = "The truth is, all he teaches his students...",
  ui_story_5045_50451801_51_dialog_content = "... is how to manipulate people's emotions to extort the wealthy!",
  ui_story_5045_50451801_52_dialog_content = "<size=45>What!?</size>",
  ui_story_5045_50451801_53_dialog_content = "I can't believe that such filth exists in Lumopolis!",
  ui_story_5045_50451801_54_dialog_content = "This scumbag must have somehow snuck into Lumopolis!",
  ui_story_5045_50451801_55_dialog_content = "PlayerName, do you admit to the plaintiff's charges against you?",
  ui_story_5045_50451801_56_dialog_content = "I didn't do anything like that, and I don't even know where this self-help course is!",
  ui_story_5045_50451801_57_dialog_content = "Bacon, did someone tell you to come here and do this?",
  ui_story_5045_50451801_58_dialog_content = "Uh, I...",
  ui_story_5045_50451801_59_dialog_content = "No!",
  ui_story_5045_50451801_60_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451801_61_dialog_content = "The defendant is urged not to mislead the plaintiff.",
  ui_story_5045_50451801_62_dialog_content = "(But Bacon clearly looks worried about something.)",
  ui_story_5045_50451801_63_dialog_content = "(I was arrested after looking for Karl yesterday... This can't be a coincidence!)",
  ui_story_5045_50451801_64_dialog_content = "Plaintiff, you said you have two witnesses who can prove everything you have claimed thus far.",
  ui_story_5045_50451801_65_dialog_content = "That's correct, Your Honor.",
  ui_story_5045_50451801_66_dialog_content = "I ask that the first <color=#1875ad>witness</color> take the stand!",
  ui_story_5045_50451801_67_dialog_content = "White Night up high.",
  ui_story_5045_50451801_68_dialog_content = "(Sophie!?)",
  ui_story_5045_50451801_69_dialog_content = "(Well, well... It's just as I thought.)",
  ui_story_5045_50451801_70_option_content = "Objection!",
  ui_story_5045_50451801_71_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451801_72_dialog_content = "Now is the time for Sophie to speak. The defendant is requested to observe the rules and regulations of the court.",
  ui_story_5045_50451801_73_dialog_content = "Didn't I just tell you that you'll lose the opportunity to defend yourself after receiving three warnings?",
  ui_story_5045_50451801_74_dialog_content = "(Oh... I can't let my nerves get the better of me!)",
  ui_story_5045_50451801_75_dialog_content = "(One more warning and I'm done for!)",
  ui_story_5045_50451801_76_option_content = "(Stay silent)",
  ui_story_5045_50451801_77_dialog_content = "(I want to hear what she's going to say.)",
  ui_story_5045_50451801_78_dialog_content = "Your Honor, my name is Sophie. I can prove that what Bacon said is true.",
  ui_story_5045_50451801_79_dialog_content = "I'm one of the earliest students of this self-help course.",
  ui_story_5045_50451801_80_dialog_content = "PlayerName told me that he was the last Caelestite and knew how to manipulate people's minds.",
  ui_story_5045_50451801_81_dialog_content = "We students revere him as the Self-help Guru.",
  ui_story_5045_50451801_82_dialog_content = "But he used intimidation, coercion, and other means to make us go out, manipulate people's emotions, and rob them of their money.",
  ui_story_5045_50451801_83_dialog_content = "We were not allowed to keep the money we tricked out of people, and we had to hand it all over to him.",
  ui_story_5045_50451801_84_dialog_content = "In other words, you admit that you are also involved in the illegal extortion of wealth?",
  ui_story_5045_50451801_85_dialog_content = "Yes.",
  ui_story_5045_50451801_86_dialog_content = "This means that you will be judged accordingly. Do you understand?",
  ui_story_5045_50451801_87_dialog_content = "I understand, but my conscience cannot bear this any longer. I don't want any more people to suffer.",
  ui_story_5045_50451801_88_dialog_content = "Rather than continue muddling through the rest of my life, I hope to stand up for something worthwhile, just this once.",
  ui_story_5045_50451801_89_dialog_content = "(Sophie sounds so sincere... If she wasn't accusing me, I'd believe it!)",
  ui_story_5045_50451801_90_dialog_content = "PlayerName, do you have anything to say?",
  ui_story_5045_50451801_91_dialog_content = "(Is there any evidence to prove that <color=#1875ad>what Sophie said is false</color>...)",
  ui_story_5045_50451801_92_dialog_content = "What do you mean by this?",
  ui_story_5045_50451801_93_dialog_content = "(Oh, no! It's not it?)",
  ui_story_5045_50451801_94_dialog_content = "Lady Irridon! This is the judge's notebook you gave me?",
  ui_story_5045_50451801_95_dialog_content = "Hmm? Although you still possess a judge's notebook, you are now a defendant in the Hall of Justice.",
  ui_story_5045_50451801_96_dialog_content = "This notebook will not help you.",
  ui_story_5045_50451801_97_dialog_content = "I can swear on this judge's notebook that I am not the Self-help Guru she's making me out to be!",
  ui_story_5045_50451801_98_dialog_content = "Sorry, PlayerName.",
  ui_story_5045_50451801_99_dialog_content = "If such oaths were of any use, there would be no need for the Hall of Justice.",
  ui_story_5045_50451801_100_dialog_content = "(That won't work, either?)",
  ui_story_5045_50451801_101_dialog_content = "Your Honor, Sophie once fabricated evidence during a trial!",
  ui_story_5045_50451801_102_dialog_content = "Really? Is this true?",
  ui_story_5045_50451801_103_dialog_content = "B-But that time, I had to do it.",
  ui_story_5045_50451801_104_dialog_content = "At that time, I was afraid that Farrell would find out about our self-help course...",
  ui_story_5045_50451801_105_dialog_content = "If that were to happen, Self-help Guru would punish me.",
  ui_story_5045_50451801_106_dialog_content = "Now that you have captured him, I have nothing to be afraid of!",
  ui_story_5045_50451801_107_dialog_content = "Well, that is indeed excusable.",
  ui_story_5045_50451801_108_dialog_content = "Then let us call the second witness.",
  ui_story_5045_50451801_109_dialog_content = "Your Honor, my name is Karl.",
  ui_story_5045_50451801_110_dialog_content = "I had an appointment to go for dinner with Bacon yesterday, but he never showed up.",
  ui_story_5045_50451801_111_dialog_content = "Fortunately, Bacon told me where he was going. It took me a long time to find him.",
  ui_story_5045_50451801_112_dialog_content = "Eventually, I found the legendary self-help course.",
  ui_story_5045_50451801_113_dialog_content = "When I got there, I overheard Bacon saying he didn't want to accept the task assigned to him by Self-help Guru, and he insisted on leaving with me.",
  ui_story_5045_50451801_114_dialog_content = "I sensed something was very wrong, so I lit a fire amid the chaos and escaped with Bacon.",
  ui_story_5045_50451801_115_dialog_content = "In order to escape, the legendary Self-help Guru took off his black robe and revealed his true face.",
  ui_story_5045_50451801_116_dialog_content = "In other words, you saw what the Self-help Guru looked like?",
  ui_story_5045_50451801_117_dialog_content = "Yes.",
  ui_story_5045_50451801_118_dialog_content = "And do you see this Self-help Guru here in the court today?",
  ui_story_5045_50451801_119_dialog_content = "Yes. The Self-help Guru is the gentleman sitting in the dock.",
  ui_story_5045_50451801_120_dialog_content = "(How can this be? What does this Karl guy think he's doing...?)",
  ui_story_5045_50451801_121_dialog_content = "(Oh yeah, I know something that might work here!)",
  ui_story_5045_50451801_122_option_content = "Mind link!",
  ui_story_5045_50451801_123_dialog_content = "(It was a smart move claiming to be the Caelestite when creating that self-help course.)",
  ui_story_5045_50451801_124_dialog_content = "(Now everyone knows that the Self-help Guru is the Caelestite, and no one has a clue about my true identity.)",
  ui_story_5045_50451801_125_dialog_content = "(It's a pity that the self-help course has to end here... Fortunately, I made more than enough from it.)",
  ui_story_5045_50451801_126_dialog_content = "Drat, the real Self-help Guru is actually Karl!",
  ui_story_5045_50451801_127_dialog_content = "(My dear PlayerName, I know there's a chance you're listening to my inner voice right now.)",
  ui_story_5045_50451801_128_dialog_content = "What? How did he know?",
  ui_story_5045_50451801_129_dialog_content = "(You may be able to hear people's thoughts thanks to your special talent...)",
  ui_story_5045_50451801_130_dialog_content = "(But I can infer your thoughts through your every movement.)",
  ui_story_5045_50451801_131_dialog_content = "(So, which of us is more powerful?)",
  ui_story_5045_50451801_132_dialog_content = "Your Honor!",
  ui_story_5045_50451801_133_dialog_content = "I have uncovered through my psychic ability that Karl is the Self-help Guru!",
  ui_story_5045_50451801_134_dialog_content = "This defendant really knows how to manipulate people!",
  ui_story_5045_50451801_135_dialog_content = "How can we believe anything he says!?",
  ui_story_5045_50451801_136_dialog_content = "It looks like this method won't work here...",
  ui_story_5045_50451801_137_dialog_content = "But there must be a contradiction hidden somewhere in <color=#1875ad>Karl's testimony</color>.",
  ui_story_5045_50451801_138_dialog_content = "What are you trying to say?",
  ui_story_5045_50451801_139_dialog_content = "Erm, I just wanted to say...",
  ui_story_5045_50451801_140_dialog_content = "Karl told me yesterday that he had never been to the self-help course and didn't even know where it was held!",
  ui_story_5045_50451801_141_dialog_content = "But just now, he said that Bacon told him the address!",
  ui_story_5045_50451801_142_dialog_content = "That's because, when I saw you, I hadn't arranged to eat with Bacon yet.",
  ui_story_5045_50451801_143_dialog_content = "Oh, really? Bacon, what time did you make the appointment with Karl?",
  ui_story_5045_50451801_144_dialog_content = "Ten o'clock in the morning, we both agreed to—",
  ui_story_5045_50451801_145_dialog_content = "I'm asking you, Bacon. When were you supposed to meet Karl?",
  ui_story_5045_50451801_146_dialog_content = "We made an appointment at 10 AM to have dinner at 6 PM...",
  ui_story_5045_50451801_147_dialog_content = "That's strange. I was arrested at four o'clock yesterday afternoon.",
  ui_story_5045_50451801_148_dialog_content = "How could I be there at the self-help course with you two then?",
  ui_story_5045_50451801_149_dialog_content = "Bacon was scared out of his wits yesterday! He simply couldn't remember clearly for a fleeting moment!",
  ui_story_5045_50451801_150_dialog_content = "We had an appointment for lunch at twelve o'clock, right?",
  ui_story_5045_50451801_151_dialog_content = "Right, that's it... I remembered incorrectly just now because I was so scared yesterday...",
  ui_story_5045_50451801_152_dialog_content = "After being frightened so, victims may indeed develop memory disorders.",
  ui_story_5045_50451801_153_dialog_content = "But more importantly, PlayerName...",
  ui_story_5045_50451801_154_dialog_content = "The Justice Knights discovered plenty of unused attendance cards in your temporary residence.",
  ui_story_5045_50451801_155_dialog_content = "What do you have to say for yourself?",
  ui_story_5045_50451801_156_option_content = "Someone planted them!",
  ui_story_5045_50451801_157_dialog_content = "All the evidence points to you. You'd better explain yourself as clearly as possible.",
  ui_story_5045_50451801_158_dialog_content = "But I really don't know where these attendance cards came from.",
  ui_story_5045_50451801_159_dialog_content = "Have I been sleepwalking or something!?",
  ui_story_5045_50451801_160_option_content = "Objection!",
  ui_story_5045_50451801_161_dialog_content = "What gives you the right to search my residence at will?",
  ui_story_5045_50451801_162_dialog_content = "You are the number one suspect in this case. With such probable cause, searching your residence is lawful and reasonable.",
  ui_story_5045_50451801_163_dialog_content = "Well...",
  ui_story_5045_50451801_164_option_content = "Where are Tina and Leyn?",
  ui_story_5045_50451801_165_dialog_content = "I want them to testify for me!",
  ui_story_5045_50451801_166_dialog_content = "They have been busy investigating their respective cases, and I have been unable to find them.",
  ui_story_5045_50451801_167_dialog_content = "What should I do?",
  ui_story_5045_50451801_168_dialog_content = "Is that all you have to say?",
  ui_story_5045_50451801_169_dialog_content = "Uh, I...",
  ui_story_5045_50451801_170_dialog_content = "<color=#737378>Thud!</color>",
  ui_story_5045_50451801_171_dialog_content = "White Night up high. It is time for...",
  ui_story_5045_50451801_172_dialog_content = "Wait!",
  ui_story_5045_50451801_173_dialog_content = "Really?",
  ui_story_5045_50451801_174_dialog_content = "Your Honor, we still have witnesses who have not appeared before the court!",
  ui_story_5045_50451801_175_dialog_content = "Sorry, PlayerName... We're not too late, are we?",
  ui_story_5045_50451801_176_dialog_content = "Leyn, Tina...",
  ui_story_5045_50451801_177_dialog_content = "The trial is not over yet. I ask that the remaining witnesses now step forward and testify!",
  ui_story_5045_50451801_178_dialog_content = "Your Honor, my name is Fanny...",
  ui_story_5045_50451801_179_dialog_content = "F-Fanny? Are you okay!?",
  ui_story_5045_50451801_180_dialog_content = "...!?",
  ui_story_5045_50451801_181_dialog_content = "I'm fine, Bacon. Don't worry about me. We can tell the chief judge the truth.",
  ui_story_5045_50451801_182_dialog_content = "Don't be afraid. The Hall of Justice will ensure your safety.",
  ui_story_5045_50451801_183_dialog_content = "Yesterday, I was <color=#1875ad>kidnapped</color>.",
  ui_story_5045_50451801_184_dialog_content = "The kidnappers held me hostage and used me to threaten Bacon, forcing him to testify against an innocent person.",
  ui_story_5045_50451801_185_dialog_content = "Yes! It's true! Everything I said just now was what the Self-help Guru told me to say!",
  ui_story_5045_50451801_186_dialog_content = "I was scared to death that they'd hurt Fanny...",
  ui_story_5045_50451801_187_dialog_content = "Fortunately, judges Leyn and Tina found me and rescued me.",
  ui_story_5045_50451801_188_dialog_content = "Now, I can testify in court.",
  ui_story_5045_50451801_189_dialog_content = "Are you sure PlayerName is innocent?",
  ui_story_5045_50451801_190_dialog_content = "He is, Your Honor.",
  ui_story_5045_50451801_191_dialog_content = "As for the real Self-help Guru, although he wore a mask, I remember his voice...",
  ui_story_5045_50451801_192_dialog_content = "Karl, we treated you as a friend. Why did you do this to us?",
  ui_story_5045_50451801_193_dialog_content = "...",
  ui_story_5045_50451801_194_dialog_content = "Your Honor, this must be some kind of misunderstanding! Some kind of gross misunderstanding!",
  ui_story_5045_50451801_195_dialog_content = "Lady Irridon, we found the entrance to a secret basement in his house.",
  ui_story_5045_50451801_196_dialog_content = "If we go in and search, we may find more evidence.",
  ui_story_5045_50451801_197_dialog_content = "Exactly, and we asked the Lumo Knights to surround the whole vicinity.",
  ui_story_5045_50451801_198_dialog_content = "We're just waiting for your confirmation, Lady Irridon.",
  ui_story_5045_50451801_199_dialog_content = "...",
  ui_story_5045_50451801_200_dialog_content = "Karl's trying to get away! Watch out!",
  ui_story_5045_50451801_201_dialog_content = "Stop right there!",
  ui_story_5045_50451801_202_dialog_content = "You can't escape!",
  ui_story_5045_50451801_203_dialog_content = "Urgh...",
  ui_story_5045_50451901_1_dialog_content = "<color=#737378>Time: 12:00 PM</color>",
  ui_story_5045_50451901_2_dialog_content = "<color=#737378>Location: Lumo Hall of Justice, Romance Division Office</color>",
  ui_story_5045_50451901_3_dialog_content = "Lady Irridon, that really was a tough trial just now!",
  ui_story_5045_50451901_4_dialog_content = "Lady Irridon is talking to PlayerName. Save your breath.",
  ui_story_5045_50451901_5_dialog_content = "... I will forgive you this time, but only because you actually raise a good point.",
  ui_story_5045_50451901_6_dialog_content = "PlayerName, I did you a great injustice today.",
  ui_story_5045_50451901_7_dialog_content = "Lady Irridon... You didn't know I was being set up all along, did you?",
  ui_story_5045_50451901_8_dialog_content = "Is that what I said?",
  ui_story_5045_50451901_9_dialog_content = "My thought is, if you really had gotten that much money...",
  ui_story_5045_50451901_10_dialog_content = "You wouldn't have been willing to come to the Hall of Justice to help us for such a salary paycheck.",
  ui_story_5045_50451901_11_dialog_content = "Erm... I really don't know whether I should be happy or sad.",
  ui_story_5045_50451901_12_dialog_content = "Tina, Leyn, your performance today really surprised me.",
  ui_story_5045_50451901_13_dialog_content = "How did you know that Fanny had been kidnapped?",
  ui_story_5045_50451901_14_dialog_content = "We found my client, Farrell. He wasn't willing to say anything at first, but thanks to Tina...",
  ui_story_5045_50451901_15_dialog_content = "I know you don't want to testify against the woman you love, but this is the only way you can save her!",
  ui_story_5045_50451901_16_dialog_content = "If you don't, she'll be forever manipulated by that Self-help Guru and live a life of suffering and humiliation!",
  ui_story_5045_50451901_17_dialog_content = "Is this... the only way to save her?",
  ui_story_5045_50451901_18_dialog_content = "Farrell told us that he had noticed certain strange things Sophie had been doing.",
  ui_story_5045_50451901_19_dialog_content = "The reason he wanted Sophie to marry him so desperately was so that he could save her from the Self-help Guru's clutches.",
  ui_story_5045_50451901_20_dialog_content = "He also told us some of the places Sophie used to go.",
  ui_story_5045_50451901_21_dialog_content = "This place is so big. Where should we start...?",
  ui_story_5045_50451901_21X1_dialog_content = "Huh? Where's Leyn?",
  ui_story_5045_50451901_22_dialog_content = "Ladies, have you seen a group of suspicious people around here?",
  ui_story_5045_50451901_23_dialog_content = "Yes! We most certainly have! Let me tell you all about them, handsome!",
  ui_story_5045_50451901_24_dialog_content = "There, we found not only Fanny, but also a little girl.",
  ui_story_5045_50451901_25_dialog_content = "That little girl was Sophie's sister...",
  ui_story_5045_50451901_26_dialog_content = "He was using multiple hostages to bend these good people to his will. Karl is utterly incorrigible!",
  ui_story_5045_50451901_27_dialog_content = "However, Sophie had a chance to save herself, and now she cannot escape the judgment of the Hall of Justice.",
  ui_story_5045_50451901_28_dialog_content = "It seems you have grown a lot during your time with the Romance Division.",
  ui_story_5045_50451901_29_dialog_content = "Th-Thank you for saying so, Lady Irridon!",
  ui_story_5045_50451901_30_dialog_content = "Actually, we owe our success today to PlayerName's intuition.",
  ui_story_5045_50451901_31_dialog_content = "Huh? Really?",
  ui_story_5045_50451901_32_dialog_content = "PlayerName told us before he was arrested that perhaps the clues were hidden in the two cases he had tried previously.",
  ui_story_5045_50451901_33_dialog_content = "That was basically just me talking to myself. I wasn't sure of anything at the time...",
  ui_story_5045_50451901_34_dialog_content = "Anyway, we cracked a big case this time!",
  ui_story_5045_50451901_35_dialog_content = "Lady Irridon, are you considering giving us a reward?",
  ui_story_5045_50451901_36_dialog_content = "Tina...",
  ui_story_5045_50451901_37_dialog_content = "How can you ask for such a thing so brazenly?",
  ui_story_5045_50451901_38_dialog_content = "With regard to a reward, I have already prepared something for you.",
  ui_story_5045_50451901_39_dialog_content = "Wait... Do Angel and I get something too?",
  ui_story_5045_50451901_40_dialog_content = "PlayerName, thank you for coming to help us when the Hall of Justice faced a dire lack of personnel.",
  ui_story_5045_50451901_41_dialog_content = "During this period, you not only helped the judges of the Romance Division to successfully try two cases...",
  ui_story_5045_50451901_42_dialog_content = "You took it upon yourself to root out evil...",
  ui_story_5045_50451901_43_dialog_content = "And helped us to bring the Self-help Guru terrorizing the people of Lumopolis to justice.",
  ui_story_5045_50451901_44_dialog_content = "The members of the Hall of Justice have agreed that an <color=#1875ad>Honorary Judge</color> trophy will be awarded to you.",
  ui_story_5045_50451901_45_dialog_content = "Wow, it's a sculpture! It looks so special!",
  ui_story_5045_50451901_46_dialog_content = "PlayerName, this trophy holds tremendous weight.",
  ui_story_5045_50451901_47_dialog_content = "Huh? Will I be able to carry it?",
  ui_story_5045_50451901_48_dialog_content = "I mean, the honor of receiving this trophy should not be taken lightly.",
  ui_story_5045_50451901_49_dialog_content = "Heehee! If you can't handle it, PlayerName, I can use my Divine Hand to carry it for you!",
  ui_story_5045_50451901_50_dialog_content = "You're giving me a trophy...?",
  ui_story_5045_50451901_51_dialog_content = "What? You don't want it?",
  ui_story_5045_50451901_52_dialog_content = "I-I'm just wondering whether you don't need my help anymore?",
  ui_story_5045_50451901_53_dialog_content = "Yes, you can look at it that way.",
  ui_story_5045_50451901_54_dialog_content = "Recently, many cases in Lumopolis were, in fact, related to the Self-help Guru.",
  ui_story_5045_50451901_55_dialog_content = "Now that the Self-help Guru has been arrested, the Romance Division's cases will gradually decrease.",
  ui_story_5045_50451901_56_dialog_content = "Also, there are many youngsters from Dawn Academy ready to come here for internships. Soon, we'll no longer be short of staff.",
  ui_story_5045_50451901_57_dialog_content = "Of course, but if you still want to stay...",
  ui_story_5045_50451901_58_dialog_content = "You can train along with the youngsters, and stay on after passing the review at the end of the probationary period.",
  ui_story_5045_50451901_59_dialog_content = "This process may take from half a year to a year.",
  ui_story_5045_50451901_60_dialog_content = "But I need to go back and take care of Cloud Gardens, and my friends always need me to go out on adventures with them...",
  ui_story_5045_50451901_61_dialog_content = "Maybe it's best if my time in the Hall of Justice ends here.",
  ui_story_5045_50451901_62_dialog_content = "It's just as I said—life in the Hall of Justice is not for everyone.",
  ui_story_5045_50451901_63_dialog_content = "So, PlayerName, are you leaving now?",
  ui_story_5045_50451901_64_dialog_content = "PlayerName...",
  ui_story_5045_50451901_65_dialog_content = "(I feel like I should say something right now.)",
  ui_story_5045_50451901_66_dialog_content = "(But what should I say?)",
  ui_story_5045_50451901_67_dialog_content = "(Oh! I've got it!)",
  ui_story_5045_50451901_68_dialog_content = "Yes, yes—there's no need to look at these anymore.",
  ui_story_5045_50451901_69_dialog_content = "(Is that it? I feel like I forget something...)",
  ui_story_5045_50451901_70_dialog_content = "I still have this <color=#1875ad>kite</color>.",
  ui_story_5045_50451901_71_dialog_content = "PlayerName, what should do with this kite now?",
  ui_story_5045_50451901_72_dialog_content = "We should give it to Farrell, the knight waiting for Sophie to get out of prison.",
  ui_story_5045_50451901_73_dialog_content = "I think that after Sophie is released from prison, maybe they'll have the chance to fly this kite together.",
  ui_story_5045_50451901_74_dialog_content = "Alright, I'll make sure he gets it.",
  ui_story_5045_50451901_75_dialog_content = "The next time you return to Lumopolis, maybe we'll also have the chance to fly kites together...",
  ui_story_5045_50451901_76_dialog_content = "Of course! It's not like we're never going to see each other again!",
  ui_story_5045_50451901_77_dialog_content = "Good. Then we'll make our own kites when you're back!",
  ui_story_5045_50451901_78_dialog_content = "I'll hold you to it!",
  ui_story_5045_50451901_79_dialog_content = "Tina's <color=#1875ad>clay figurines</color> are still here.",
  ui_story_5045_50451901_80_dialog_content = "PlayerName, I want you to have this!",
  ui_story_5045_50451901_81_dialog_content = "Really?",
  ui_story_5045_50451901_82_dialog_content = "But don't get me wrong, I just want to thank you for making my work so much easier and so much more fun while you were here.",
  ui_story_5045_50451901_83_dialog_content = "Since we work in the Romance Division, of course, I wish you all the best in matters of the heart in the future...",
  ui_story_5045_50451901_84_dialog_content = "When you meet someone you like, and that person likes you back, I know you'll have a sweet love that lasts forever!",
  ui_story_5045_50451901_85_dialog_content = "Like these two little clay figurines...",
  ui_story_5045_50451901_86_dialog_content = "The image of love, extracted from the earth and tempered by fire, finally becomes an eternal bond!",
  ui_story_5045_50451901_87_dialog_content = "Thank you so much, Tina!",
  ui_story_5045_50451901_88_dialog_content = "Although, I think it may be too early in my life for me to receive that kind of blessing...",
  ui_story_5045_50451901_89_dialog_content = "It's not too early at all!",
  ui_story_5045_50451901_90_dialog_content = "I mean... if you can't find someone you like, just come back to Lumopolis, or maybe Hall of Justice.",
  ui_story_5045_50451901_91_dialog_content = "Of course, I promise I'll return.",
  ui_story_5045_50451901_92_dialog_content = "R-Really?",
  ui_story_5045_50451901_93_dialog_content = "Then we can go into the countryside and make loads of little clay figurines and then give them to all the lovers out there!",
  ui_story_5045_50451901_94_dialog_content = "You bet!",
  ui_story_5045_50451901_95_dialog_content = "Without the Romance Division, I would never have been granted this cherished trophy.",
  ui_story_5045_50451901_96_dialog_content = "I want to leave this trophy with the Romance Division.",
  ui_story_5045_50451901_97_dialog_content = "This is a great idea!",
  ui_story_5045_50451901_98_dialog_content = "But where do you want to put it, PlayerName?",
  ui_story_5045_50451901_99_dialog_content = "Do you really need to ask? Just put it on my desk!",
  ui_story_5045_50451901_100_dialog_content = "Take a look around—I'm the only one with a desk clean enough for that thing!",
  ui_story_5045_50451901_101_dialog_content = "I think...",
  ui_story_5045_50451901_102_dialog_content = "Everyone should take turns putting it on their desks.",
  ui_story_5045_50451901_103_dialog_content = "Yes, that's fair!",
  ui_story_5045_50451901_104_dialog_content = "So, it's decided!",
  ui_story_5045_50451901_105_dialog_content = "Everyone?",
  ui_story_5045_50451901_106_dialog_content = "That includes me, right? Hey...",
  ui_story_5045_50451901_107_dialog_content = "In this notebook...",
  ui_story_5045_50451901_108_dialog_content = "I noted down everything and everyone I encountered after coming to the Romance Division.",
  ui_story_5045_50451901_109_dialog_content = "Our helplessness and heartache when we came up against great difficulties together...",
  ui_story_5045_50451901_110_dialog_content = "And the happiness and sense of achievement after making a successful judgment together!",
  ui_story_5045_50451901_111_dialog_content = "As long as I have this, I'll never forget the wonderful days I spent in the Romance Division!",
  ui_story_5045_50451901_112_dialog_content = "While I'm gone, everyone—please write down your feelings in your notebooks for me.",
  ui_story_5045_50451901_113_dialog_content = "In the future, when I come back...",
  ui_story_5045_50451901_114_dialog_content = "I'll be able to hear all about the strange cases I've been missing out on!",
  ui_story_5045_50451901_115_dialog_content = "Indeed...",
  ui_story_5045_50451901_116_dialog_content = "PlayerName, you're so bad...",
  ui_story_5045_50451901_117_dialog_content = "Stop trying to make us all cry!",
  ui_story_5045_50451901_118_dialog_content = "Thanks for the advice, PlayerName...",
  ui_story_5045_50451901_119_dialog_content = "I'll record all the most fascinating cases for you!",
  ui_story_5045_50451901_120_dialog_content = "Do you see this, Angel? Start taking notes!",
  ui_story_5045_50451901_121_dialog_content = "... Okay!",
  ui_story_5045_50451901_122_dialog_content = "Goodbye, everyone.",
  ui_story_5045_50451901_123_dialog_content = "Goodbye, Romance Division.",
  ui_story_5045_50451901_124_dialog_content = "I know that one day...",
  ui_story_5045_50451901_125_option_content = "I'll see you again!"
}
return config
